window.TBC={"categories":[{"id":"body-butter","name":"Body Butter","emoji":"🧈","color":"#C9A66B","fuente":"body-butter-recipes.html","nombre_bono":"Body Butter Recipes"},{"id":"body-oil","name":"Body Oil","emoji":"💧","color":"#8B9B7D","fuente":"body-oil-recipes.html","nombre_bono":"Body Oil Recipes"},{"id":"whipped-soap","name":"Whipped Soap","emoji":"🧼","color":"#7FA8C9","fuente":"whipped-soap-recipes.html","nombre_bono":"Whipped Soap Recipes"},{"id":"emulsified-scrub","name":"Emulsified Scrub","emoji":"🫧","color":"#B98A6B","fuente":"emulsified-body-scrub-recipes.html","nombre_bono":"Emulsified Body Scrub Recipes"},{"id":"salt-scrub","name":"Salt Scrub","emoji":"🧂","color":"#9FB8AD","fuente":"salt-based-emulsified-recipes.html","nombre_bono":"Salt-Based Emulsified Recipes"},{"id":"lip-oil","name":"Lip Oil","emoji":"💄","color":"#C77B8B","fuente":"lip-oil-recipes.html","nombre_bono":"Lip Oil Recipes"},{"id":"body-spray","name":"Body Spray","emoji":"🌼","color":"#A68BC2","fuente":"body-spray-recipes.html","nombre_bono":"Body Spray Recipes"},{"id":"deodorant","name":"Deodorant","emoji":"🌿","color":"#6B8E6B","fuente":"deodorant-recipes.html","nombre_bono":"Deodorant Recipes"}],"recipes":[{"slug":"classic-shea-body-butter","title":"Classic Shea Body Butter","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"Up to 1 year at room temperature. This recipe has no water in it, so it doesn't need a preservative — just keep water (wet fingers, steam) out of the jar.","ingredients":[{"item":"Raw shea butter","amount":"120 g (4.2 oz)"},{"item":"Sweet almond oil (or any light liquid oil)","amount":"60 g (2.1 oz)"},{"item":"Beeswax pellets (or candelilla wax for a vegan version)","amount":"10 g (0.35 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp) — adds skin-feel and slows rancidity, it is not a preservative"},{"item":"Essential oil of your choice (optional)","amount":"15-20 drops"}],"method":["Set up a double boiler: a heatproof bowl over a pot with 1-2 in (2-3 cm) of simmering water, bowl not touching the water.","Melt the shea butter, almond oil and beeswax together, stirring occasionally, until fully liquid and clear (about 5-8 min).","Remove from heat and stir in the vitamin E oil.","Let the mixture cool at room temperature for 20-30 min, until it turns cloudy and starts to firm at the edges — this prevents the oils from separating later.","Whip with a hand or stand mixer on medium-high for 5-8 min, until light, pale and fluffy, like buttercream.","Add the essential oil in the last minute of whipping, if using.","Spoon into a clean, dry jar. Don't tap it down — the air you whipped in is what keeps it light."],"tips":["If it comes out grainy, it cooled too fast or unevenly — remelt gently and let it cool slower next time, stirring every few minutes.","In a hot climate, add an extra 5 g of beeswax so it doesn't melt in the jar."],"safety_note":null,"keywords":["shea butter","body butter","moisturizer","dry skin","whipped","anhydrous","gift"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"lavender-dry-body-oil","title":"Lavender Dry Body Oil","cat":"body-oil","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"6-12 months at room temperature, away from direct sunlight. No water in this recipe, so no preservative is needed — just keep the dropper or cap dry.","ingredients":[{"item":"Fractionated coconut oil (or light jojoba oil)","amount":"90 g (3.2 oz)"},{"item":"Sweet almond oil","amount":"25 g (0.9 oz)"},{"item":"Vitamin E oil","amount":"2 g (about 1/3 tsp), slows rancidity"},{"item":"Lavender essential oil","amount":"25-30 drops (about 1.25 g)"}],"method":["Measure the fractionated coconut oil and almond oil directly into a clean glass bottle.","Add the vitamin E oil.","Add the lavender essential oil.","Cap tightly and shake gently for 15-20 seconds to combine.","Label with the date you made it."],"tips":["Apply right after a shower, while skin is still damp, so the oil seals in water instead of just sitting on top.","Swap the essential oil for any skin-safe scent you like — the base ratio stays the same."],"safety_note":"Essential oils are concentrated. Do a patch test on your inner arm and wait 24 hours before using a new blend on your whole body.","keywords":["body oil","dry oil","lavender","moisturizer","massage oil","anhydrous"],"pdf":"../../body-oil-recipes/g65gssg2kj/body-oil-recipes.pdf"},{"slug":"honey-oat-whipped-soap","title":"Honey Oat Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 10 oz (280 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (goat's milk or glycerin)","amount":"200 g (7 oz)"},{"item":"Liquid foaming bath base (to get the fluffy, whipped texture)","amount":"40 g (1.4 oz)"},{"item":"Raw honey","amount":"10 g (2 tsp)"},{"item":"Finely ground oats","amount":"10 g (2 tbsp)"},{"item":"Fragrance or essential oil","amount":"2 g (about 1/2 tsp)"}],"method":["Cut the soap base into small cubes and melt in a double boiler or microwave in 20-second bursts, stirring between each, until fully liquid.","Let it cool for 2-3 min, just until it starts to thicken slightly at the edges.","Whip with a hand mixer on high for 3-5 min, until it turns light, opaque and fluffy.","Add the foaming bath base and whip for another 1-2 min to combine.","Fold in the honey, ground oats and fragrance with a spatula (don't whip these in, or you'll knock out the air).","Spoon into jars right away — it firms up fast once it stops being whipped.","Leave uncovered overnight to fully set, then cap."],"tips":["This is a melt-and-pour recipe: it never involves raw lye, so it's safe to make without the gear or ventilation that from-scratch soap making needs.","If it deflates instead of staying fluffy, the base cooled too much before whipping — work faster next time, or rewarm it for a few seconds."],"safety_note":null,"keywords":["whipped soap","soap","melt and pour","honey","oatmeal","gentle","exfoliating"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"vanilla-sugar-emulsified-scrub","title":"Vanilla Sugar Emulsified Scrub","cat":"emulsified-scrub","time":"10 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"This recipe includes water, so it needs a broad-spectrum preservative (see ingredients) and lasts about 3 months at room temperature, away from the shower's direct spray. Without the preservative it can grow mold or bacteria within days — never skip it.","ingredients":[{"item":"Emulsifying wax NF","amount":"15 g (0.5 oz)"},{"item":"Sweet almond oil","amount":"60 g (2.1 oz)"},{"item":"Distilled water","amount":"40 g (1.4 oz)"},{"item":"White granulated sugar","amount":"100 g (3.5 oz)"},{"item":"Broad-spectrum preservative (e.g. a liquid preservative rated for water-containing scrubs, used at the rate its own label states)","amount":"per label — typically 0.5-1 g"},{"item":"Vanilla fragrance oil","amount":"3 g (about 1/2 tsp)"}],"method":["Melt the emulsifying wax and almond oil together in a double boiler until clear.","In a separate cup, warm the distilled water to about the same temperature as the oil mixture (check with a thermometer, aim for 160-170°F / 70-77°C on both).","Pour the warm water into the oil mixture in a thin stream, stirring constantly, until it turns opaque and creamy — this is the emulsion forming.","Let it cool to under 110°F (43°C), checking with a thermometer — adding the preservative while too hot can break it down.","Stir in the preservative at the exact rate its label specifies, then the fragrance oil.","Fold in the sugar last, once the mixture is thick enough that the sugar won't sink to the bottom.","Spoon into a jar and label with the date made."],"tips":["Always add the preservative after cooling, at the manufacturer's stated rate — more isn't safer, it just follows what was tested to work.","If the sugar dissolves instead of staying gritty, your mixture was too hot when you added it — let it cool further next time."],"safety_note":"This scrub contains water and must be preserved correctly, used within its stated shelf life, and kept out of reach of children. Discontinue if it changes smell, color or texture.","keywords":["sugar scrub","emulsified scrub","vanilla","exfoliating","body scrub","foaming scrub"],"pdf":"../../emulsified-body-scrub-recipes/ak8qdjexea/emulsified-body-scrub-recipes.pdf"},{"slug":"citrus-foaming-salt-scrub","title":"Citrus Foaming Salt Scrub","cat":"salt-scrub","time":"10 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"6 months at room temperature. This version has no water in the jar — it only foams when it meets water in the shower — so it doesn't need a preservative. Keep the lid on tight so moisture from the shower doesn't get in between uses.","ingredients":[{"item":"Fine sea salt","amount":"150 g (5.3 oz)"},{"item":"Fractionated coconut oil","amount":"40 g (1.4 oz)"},{"item":"Polysorbate 80 (an emulsifier that lets the oil rinse off instead of clogging the shower)","amount":"15 g (0.5 oz)"},{"item":"Sweet orange essential oil","amount":"20-25 drops"}],"method":["In a bowl, stir the fractionated coconut oil and polysorbate 80 together until fully blended.","Add the sweet orange essential oil and stir again.","Pour this mixture over the sea salt and fold together with a spatula until every grain is coated.","Spoon into a wide-mouth jar, pressing down gently so there are no big air pockets."],"tips":["The polysorbate 80 is what makes this 'foaming' — skip it and you'll get a regular oily salt scrub that can make the tub slippery.","Use a wide-mouth jar: this scrub is thick and hard to get out of a narrow one."],"safety_note":"Salt scrubs can make a wet shower floor slippery — use a mat and rinse the tub after.","keywords":["salt scrub","foaming scrub","citrus","body scrub","exfoliating","orange"],"pdf":"../../salt-based-emulsified-recipes/060n4zqnvd/salt-based-emulsified-recipes.pdf"},{"slug":"peppermint-lip-oil","title":"Peppermint Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed.","ingredients":[{"item":"Castor oil (gives shine and a slightly glossy finish)","amount":"6 g"},{"item":"Sweet almond oil","amount":"3 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Peppermint essential oil","amount":"2-3 drops"}],"method":["Combine the castor oil and almond oil in a small cup.","Add the vitamin E oil and stir.","Add the peppermint essential oil, 1 drop at a time, stirring and tasting a tiny dab between drops — peppermint is strong.","Use a dropper or small funnel to fill clean lip oil tubes."],"tips":["Peppermint oil can tingle more than expected on lips — start with 2 drops and add a third only if you want a stronger cooling effect.","Swap peppermint for a flavor oil (not essential oil) if you want sweetness instead of a cooling tingle."],"safety_note":"Keep peppermint essential oil away from the eyes, and don't use this on very young children's lips without checking the essential oil is rated safe for their age.","keywords":["lip oil","lip gloss","peppermint","lip care","gift","anhydrous"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"citrus-mint-body-spray","title":"Citrus Mint Body Spray","cat":"body-spray","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"About 6 months at room temperature. The high alcohol content in this recipe helps keep it fresh, but it still contains water, so don't stretch it past 6 months, and stop using it if the smell changes.","ingredients":[{"item":"High-proof unflavored vodka or perfumer's alcohol (at least 80 proof / 40% alcohol)","amount":"60 g (2.1 oz)"},{"item":"Distilled water","amount":"50 g (1.8 oz)"},{"item":"Polysorbate 20 (helps the essential oils mix into the water instead of floating on top)","amount":"5 g (1 tsp)"},{"item":"Sweet orange essential oil","amount":"30 drops"},{"item":"Peppermint essential oil","amount":"10 drops"}],"method":["In a small bowl, mix the polysorbate 20 with the essential oils first, stirring until fully blended.","Add the alcohol and stir again.","Add the distilled water last, stirring gently.","Pour into a fine-mist spray bottle through a small funnel.","Shake before each use."],"tips":["Mixing the oils into the polysorbate before adding any liquid is what keeps the spray clear instead of cloudy with floating oil droplets.","Let it sit for 24-48 hours before judging the scent — it mellows and blends as it rests."],"safety_note":"This spray contains alcohol: keep it away from open flame, and avoid spraying directly onto broken or irritated skin.","keywords":["body spray","body mist","citrus","mint","perfume","deodorizing spray"],"pdf":"../../body-spray-recipes/352csvv5aw/body-spray-recipes.pdf"},{"slug":"lavender-baking-soda-deodorant","title":"Lavender Baking Soda Deodorant","cat":"deodorant","time":"10 min active, no cook time","batch_size":"about 2.5 oz (70 g), one standard deodorant tube","shelf_life":"Up to 6 months at room temperature. No water in this recipe, so no preservative is needed.","ingredients":[{"item":"Coconut oil","amount":"25 g (0.9 oz)"},{"item":"Shea butter","amount":"10 g (0.35 oz)"},{"item":"Beeswax pellets","amount":"8 g (0.3 oz)"},{"item":"Arrowroot powder (or cornstarch)","amount":"15 g (0.5 oz)"},{"item":"Baking soda","amount":"10 g (0.35 oz) — see the note below if your skin is sensitive"},{"item":"Lavender essential oil","amount":"15 drops"}],"method":["Melt the coconut oil, shea butter and beeswax together in a double boiler until fully liquid.","Remove from heat and whisk in the arrowroot powder and baking soda until no lumps remain.","Let the mixture cool for 2-3 min, stirring once or twice so the powders don't settle to the bottom.","Stir in the lavender essential oil.","Pour into an empty deodorant tube or a small jar before it sets — it firms up fast.","Let it cool fully at room temperature (1-2 hours) before using."],"tips":["This recipe uses less baking soda than many older DIY recipes, which helps with sensitivity — see the safety note below if you still react.","In hot weather, add an extra 2-3 g of beeswax so it stays solid."],"safety_note":"Baking soda is alkaline and irritates some people's underarm skin (redness, itching, a rash). Patch test on your arm for a few days first. If you react, cut the baking soda to 5 g, or replace it entirely with the same amount of magnesium hydroxide powder, which most people tolerate better.","keywords":["deodorant","natural deodorant","baking soda","lavender","diy deodorant"],"pdf":"../../deodorant-recipes/4jp9eupm6n/deodorant-recipes.pdf"},{"slug":"whipped-mango-butter-almond-lavender","title":"Whipped Mango Butter with Sweet Almond Oil & Lavender","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"Up to 1 year at room temperature, away from direct sunlight. This recipe has no water in it, so it doesn't need a preservative — just keep water (wet fingers, steam) out of the jar.","ingredients":[{"item":"Mango butter","amount":"120 g (4.2 oz)"},{"item":"Sweet almond oil","amount":"60 g (2.1 oz)"},{"item":"Beeswax pellets (or candelilla wax for a vegan version)","amount":"10 g (0.35 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp) — slows rancidity, not a preservative"},{"item":"Lavender essential oil","amount":"25 drops"}],"method":["Set up a double boiler: a heatproof bowl over a pot with 1-2 in (2-3 cm) of simmering water, bowl not touching the water.","Melt the mango butter, almond oil and beeswax together, stirring occasionally, until fully liquid and clear (5-8 min).","Remove from heat and stir in the vitamin E oil.","Let the mixture cool at room temperature for 20-30 min, until cloudy and firm at the edges.","Whip with a hand or stand mixer on medium-high for 5-8 min, until light and fluffy.","Add the lavender essential oil in the last minute of whipping.","Spoon into a clean, dry jar without tapping it down."],"tips":["Mango butter is softer than shea at room temperature — if your kitchen runs warm, chill the bowl for 5 min before whipping.","If it turns grainy, it cooled too fast; remelt gently and let it cool slower, stirring every few minutes."],"safety_note":null,"keywords":["mango butter","body butter","lavender","whipped","moisturizer","anhydrous","relaxing"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"whipped-cocoa-butter-jojoba-vanilla","title":"Whipped Cocoa Butter with Jojoba Oil & Vanilla","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"Up to 1 year at room temperature, away from direct sunlight. This recipe has no water in it, so it doesn't need a preservative — just keep water (wet fingers, steam) out of the jar.","ingredients":[{"item":"Cocoa butter, chopped","amount":"110 g (3.9 oz)"},{"item":"Jojoba oil","amount":"65 g (2.3 oz)"},{"item":"Candelilla wax (vegan; or beeswax pellets)","amount":"8 g (0.28 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Vanilla fragrance oil (or vanilla-infused jojoba)","amount":"20 drops (about 1 g)"}],"method":["Melt the cocoa butter, jojoba oil and candelilla wax together in a double boiler until fully clear (6-9 min — cocoa butter melts a bit slower than shea).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 25-35 min, until the edges turn pale and opaque.","Whip on medium-high for 6-8 min, until light and mousse-like with a faint chocolate smell.","Fold in the vanilla fragrance oil by hand for the last 30 seconds so the scent doesn't cook off.","Spoon into a jar and smooth the top."],"tips":["Real cocoa butter keeps a faint natural chocolate smell even after whipping — vanilla rounds it into a dessert-like scent instead of fighting it.","Cocoa butter whips up firmer than shea; if yours feels too stiff to scoop, add 5 g more jojoba oil next batch."],"safety_note":null,"keywords":["cocoa butter","body butter","vanilla","whipped","jojoba oil","moisturizer","gift"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"unscented-whipped-kokum-butter-grapeseed","title":"Unscented Whipped Kokum Butter with Grapeseed Oil","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"6-12 months at room temperature, away from direct heat. This is a water-free (anhydrous) recipe, so it doesn't need a preservative.","ingredients":[{"item":"Kokum butter, chopped","amount":"115 g (4.1 oz)"},{"item":"Grapeseed oil","amount":"60 g (2.1 oz)"},{"item":"Beeswax pellets","amount":"10 g (0.35 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"}],"method":["Melt the kokum butter, grapeseed oil and beeswax together in a double boiler until clear (6-8 min). Kokum butter is quite hard, so give it the full time.","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 25-30 min, until firm at the edges.","Whip on medium-high for 6-8 min, until pale and fluffy.","Spoon into a jar without tapping it down."],"tips":["Kokum butter is one of the firmest natural butters, which makes this version extra stable in warm rooms — good for anyone sensitive to fragrance.","No essential oil here on purpose: if you want a light scent later, you can stir 10-15 drops into a single jar without reformulating the whole batch."],"safety_note":null,"keywords":["kokum butter","body butter","unscented","fragrance-free","sensitive skin","whipped","anhydrous"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"whipped-illipe-butter-argan-rose","title":"Whipped Illipe Butter with Argan Oil & Rose","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"Up to 1 year at room temperature, away from direct sunlight. This recipe has no water in it, so it doesn't need a preservative — just keep water (wet fingers, steam) out of the jar.","ingredients":[{"item":"Illipe butter, chopped","amount":"115 g (4.1 oz)"},{"item":"Argan oil","amount":"60 g (2.1 oz)"},{"item":"Beeswax pellets","amount":"10 g (0.35 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Rose essential oil (or rose fragrance oil)","amount":"15 drops"}],"method":["Melt the illipe butter, argan oil and beeswax together in a double boiler until clear (illipe is firm, allow 8-10 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 30 min, until the edges firm up and the center turns cloudy.","Whip on medium-high for 6-8 min, until light and silky.","Add the rose essential oil in the last minute of whipping.","Spoon into a jar, smoothing the top with the back of a spoon."],"tips":["Illipe butter behaves like a firmer cousin of shea butter — it holds its whipped structure especially well in warm bathrooms.","True rose essential oil is expensive and strong; a rose fragrance oil gives the same scent at a fraction of the cost if you're making this to sell or gift often."],"safety_note":null,"keywords":["illipe butter","body butter","rose","argan oil","whipped","floral","moisturizer"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"winter-spice-shea-cocoa-butter-bar","title":"Winter Spice Shea-Cocoa Butter Bar","cat":"body-butter","time":"15 min active, plus 30 min to set","batch_size":"six 2 oz (55 g) bars, about 12 oz (340 g) total","shelf_life":"6-12 months at room temperature in a sealed tin or jar. Anhydrous, so no preservative is needed — just keep the bar dry between uses.","ingredients":[{"item":"Shea butter","amount":"100 g (3.5 oz)"},{"item":"Cocoa butter, chopped","amount":"80 g (2.8 oz)"},{"item":"Sweet almond oil","amount":"60 g (2.1 oz)"},{"item":"Beeswax pellets","amount":"95 g (3.3 oz) — the high wax is what lets the bar hold its shape"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Cinnamon essential oil","amount":"8 drops"},{"item":"Vanilla fragrance oil","amount":"20 drops"}],"method":["Melt the shea butter, cocoa butter, almond oil and beeswax together in a double boiler until fully clear (10-12 min — this mix carries a lot of wax).","Remove from heat and stir in the vitamin E oil.","Let it cool for 3-4 min, just until it stops steaming, then stir in the cinnamon and vanilla.","Pour into six silicone bar molds (or one bar-shaped silicone loaf mold).","Refrigerate for 20-30 min, or leave at room temperature for 2-3 hours, until fully solid and opaque.","Pop the bars out of the molds and store in a tin."],"tips":["This is a solid lotion bar, not a whip: it's meant to be rubbed between warm hands until it melts into a thin layer, not scooped with fingers.","Cinnamon essential oil is a strong skin sensitizer — the 8-drop dose across a 340 g batch keeps each bar's concentration low; don't be tempted to add more for a stronger scent."],"safety_note":"Cinnamon essential oil can irritate skin at higher concentrations. This recipe keeps it deliberately low — do a patch test on your inner arm before using a full bar on your body, and don't increase the amount.","keywords":["body butter bar","lotion bar","winter","cinnamon","shea butter","cocoa butter","gift","solid"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"whipped-shea-butter-rosehip-jasmine","title":"Whipped Shea Butter with Rosehip Oil & Jasmine","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"Up to 1 year at room temperature, away from direct sunlight. This recipe has no water in it, so it doesn't need a preservative — just keep water (wet fingers, steam) out of the jar.","ingredients":[{"item":"Shea butter","amount":"120 g (4.2 oz)"},{"item":"Rosehip seed oil","amount":"55 g (1.9 oz)"},{"item":"Beeswax pellets","amount":"10 g (0.35 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Jasmine fragrance oil","amount":"20 drops"}],"method":["Melt the shea butter, rosehip oil and beeswax together in a double boiler until clear (5-7 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 20-30 min, until cloudy and firm at the edges.","Whip on medium-high for 5-7 min, until light and fluffy.","Add the jasmine fragrance oil in the last minute of whipping.","Spoon into a jar without tapping it down."],"tips":["Rosehip oil is thin and slightly nutty-smelling on its own — jasmine covers that nicely without needing a huge amount.","Rosehip oil oxidizes faster than almond or jojoba; keep the jar's lid tight and use within the shelf life for the best scent and feel."],"safety_note":null,"keywords":["shea butter","body butter","jasmine","rosehip oil","whipped","floral","anti-aging feel"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"whipped-mango-butter-sunflower-grapefruit","title":"Whipped Mango Butter with Sunflower Oil & Grapefruit","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"6-12 months at room temperature, away from direct heat. This is a water-free (anhydrous) recipe, so it doesn't need a preservative.","ingredients":[{"item":"Mango butter","amount":"120 g (4.2 oz)"},{"item":"Sunflower oil","amount":"60 g (2.1 oz)"},{"item":"Beeswax pellets","amount":"10 g (0.35 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Grapefruit essential oil","amount":"25 drops"}],"method":["Melt the mango butter, sunflower oil and beeswax together in a double boiler until clear (5-7 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 20-25 min, until the edges firm up.","Whip on medium-high for 5-7 min, until light and airy.","Add the grapefruit essential oil in the last minute of whipping.","Spoon into a jar and smooth the top."],"tips":["Sunflower oil is light and fast-absorbing, which keeps this version from feeling heavy — good for daytime use under clothes.","Grapefruit essential oil fades faster than citrus you'd expect; store the jar away from a sunny windowsill to keep the scent bright longer."],"safety_note":null,"keywords":["mango butter","body butter","grapefruit","citrus","sunflower oil","whipped","light"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"bergamot-cocoa-illipe-butter-bar","title":"Bergamot Cocoa-Illipe Butter Bar","cat":"body-butter","time":"15 min active, plus 30 min to set","batch_size":"six 2 oz (55 g) bars, about 12 oz (340 g) total","shelf_life":"6-12 months at room temperature in a sealed tin or jar. Anhydrous, so no preservative is needed — just keep the bar dry between uses.","ingredients":[{"item":"Cocoa butter, chopped","amount":"90 g (3.2 oz)"},{"item":"Illipe butter, chopped","amount":"90 g (3.2 oz)"},{"item":"Grapeseed oil","amount":"50 g (1.8 oz)"},{"item":"Beeswax pellets","amount":"100 g (3.5 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Bergamot essential oil (bergapten-free / FCF, non-phototoxic type)","amount":"15 drops"}],"method":["Melt the cocoa butter, illipe butter, grapeseed oil and beeswax together in a double boiler until fully clear (10-12 min).","Remove from heat and stir in the vitamin E oil.","Let it cool for 3-4 min, just until it stops steaming, then stir in the bergamot essential oil.","Pour into six silicone bar molds.","Refrigerate 20-30 min, or room temperature 2-3 hours, until fully solid.","Pop out of the molds and store in a tin."],"tips":["Two firm butters plus a high wax ratio make this the sturdiest bar in the lineup — it travels well without melting in a gym bag.","Regular bergamot oil is phototoxic (it can cause sun damage on treated skin); this recipe calls for the bergapten-free (FCF) type specifically so it's safe for leave-on daytime use."],"safety_note":"Standard bergamot essential oil can cause skin damage in sunlight (phototoxicity). Use only a bergapten-free / FCF bergamot oil in a leave-on product like this, and if you're unsure which type you have, avoid direct sun on treated skin for 12-18 hours after use.","keywords":["body butter bar","bergamot","cocoa butter","illipe butter","citrus","gift","solid","travel"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"whipped-kokum-butter-avocado-eucalyptus-mint","title":"Whipped Kokum Butter with Avocado Oil & Eucalyptus Mint","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"6-12 months at room temperature, away from direct heat. This is a water-free (anhydrous) recipe, so it doesn't need a preservative.","ingredients":[{"item":"Kokum butter, chopped","amount":"110 g (3.9 oz)"},{"item":"Avocado oil","amount":"60 g (2.1 oz)"},{"item":"Beeswax pellets","amount":"10 g (0.35 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Eucalyptus essential oil","amount":"15 drops"},{"item":"Peppermint essential oil","amount":"10 drops"}],"method":["Melt the kokum butter, avocado oil and beeswax together in a double boiler until clear (7-9 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 25-30 min, until firm at the edges.","Whip on medium-high for 6-8 min, until light and fluffy.","Add the eucalyptus and peppermint essential oils in the last minute of whipping.","Spoon into a jar without tapping it down."],"tips":["Avocado oil is heavier and greener-smelling than almond or jojoba — the eucalyptus-mint combo keeps the overall scent crisp instead of muddy.","Great for tired legs after a workout; the cooling tingle from the peppermint fades within a few minutes."],"safety_note":"Peppermint essential oil can tingle strongly and isn't meant for the face, broken skin, or young children. Keep use to arms and legs and patch test if you haven't used peppermint on your skin before.","keywords":["kokum butter","body butter","eucalyptus","peppermint","avocado oil","whipped","cooling"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"holiday-orange-cardamom-shea-mango-whip","title":"Holiday Orange Cardamom Shea-Mango Whipped Butter","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 10 oz (280 g), good for 3 small gift jars","shelf_life":"Up to 1 year at room temperature. No water, no preservative needed — this richer, double-butter blend is especially stable.","ingredients":[{"item":"Shea butter","amount":"80 g (2.8 oz)"},{"item":"Mango butter","amount":"70 g (2.5 oz)"},{"item":"Sweet almond oil","amount":"45 g (1.6 oz)"},{"item":"Beeswax pellets","amount":"16 g (0.56 oz) — a bit more than a single-butter whip, for extra firmness"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Sweet orange essential oil","amount":"25 drops"},{"item":"Cardamom essential oil","amount":"6 drops"}],"method":["Melt the shea butter, mango butter, almond oil and beeswax together in a double boiler until fully clear (8-10 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 30-35 min — the extra wax and double butter make this firm up faster than a single-butter whip, so check it at the 20-min mark.","Whip on medium-high for 5-7 min, until light but noticeably denser than a classic whip.","Add the orange and cardamom essential oils in the last minute of whipping.","Divide into 3 small gift jars (or one 10 oz jar) and smooth the tops."],"tips":["The double-butter base holds its shape better than a single-butter whip if the jars travel or sit somewhere warm before gifting.","Cardamom is potent — 6 drops across the whole batch gives warmth without smelling medicinal; resist adding more."],"safety_note":null,"keywords":["body butter","holiday gift","orange","cardamom","shea butter","mango butter","whipped","double butter"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"whipped-illipe-butter-almond-rosemary-mint","title":"Whipped Illipe Butter with Almond Oil & Rosemary Mint","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"Up to 1 year at room temperature, away from direct sunlight. This recipe has no water in it, so it doesn't need a preservative — just keep water (wet fingers, steam) out of the jar.","ingredients":[{"item":"Illipe butter, chopped","amount":"115 g (4.1 oz)"},{"item":"Sweet almond oil","amount":"60 g (2.1 oz)"},{"item":"Beeswax pellets","amount":"10 g (0.35 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Rosemary essential oil","amount":"15 drops"},{"item":"Peppermint essential oil","amount":"8 drops"}],"method":["Melt the illipe butter, almond oil and beeswax together in a double boiler until clear (8-10 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 30 min, until firm at the edges.","Whip on medium-high for 6-8 min, until light and silky.","Add the rosemary and peppermint essential oils in the last minute of whipping.","Spoon into a jar, smoothing the top."],"tips":["This combination makes a good morning leg-and-shoulder butter — rosemary smells sharp and herbal, peppermint adds a light wake-up tingle.","If you want it purely herbal without the cooling effect, drop the peppermint and add 5 more drops of rosemary instead."],"safety_note":null,"keywords":["illipe butter","body butter","rosemary","peppermint","herbal","whipped","energizing"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"spa-night-peppermint-eucalyptus-cocoa-bars","title":"Spa Night Peppermint Eucalyptus Cocoa Butter Bars","cat":"body-butter","time":"15 min active, plus 30 min to set","batch_size":"six 2 oz (55 g) bars, about 12 oz (340 g) total","shelf_life":"6-12 months at room temperature in a sealed tin or jar. Anhydrous, so no preservative is needed — just keep the bar dry between uses.","ingredients":[{"item":"Cocoa butter, chopped","amount":"100 g (3.5 oz)"},{"item":"Jojoba oil","amount":"70 g (2.5 oz)"},{"item":"Beeswax pellets","amount":"95 g (3.3 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Peppermint essential oil","amount":"12 drops"},{"item":"Eucalyptus essential oil","amount":"15 drops"}],"method":["Melt the cocoa butter, jojoba oil and beeswax together in a double boiler until fully clear (10-12 min).","Remove from heat and stir in the vitamin E oil.","Let it cool for 3-4 min, just until it stops steaming, then stir in the peppermint and eucalyptus.","Pour into six silicone bar molds.","Refrigerate 20-30 min, or room temperature 2-3 hours, until fully solid.","Pop out of the molds and store in a tin for the bath or shower shelf."],"tips":["Rub a bar over calves and feet after a hot shower for a cooling, spa-like finish — the heat from your skin melts just enough to spread thin.","Keep bars away from the eye area; the peppermint-eucalyptus combo is bracing if it gets near the face."],"safety_note":"Peppermint and eucalyptus essential oils are strong on skin and shouldn't be used near the eyes, on broken skin, or on young children. Patch test if this is your first time using either oil on your body.","keywords":["body butter bar","spa night","peppermint","eucalyptus","cocoa butter","solid","cooling","gift"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"whipped-shea-butter-charcoal-eucalyptus","title":"Whipped Shea Butter with Activated Charcoal & Eucalyptus","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"Up to 1 year at room temperature, away from direct sunlight. This recipe has no water in it, so it doesn't need a preservative — just keep water (wet fingers, steam) out of the jar.","ingredients":[{"item":"Shea butter","amount":"120 g (4.2 oz)"},{"item":"Sunflower oil","amount":"55 g (1.9 oz)"},{"item":"Beeswax pellets","amount":"10 g (0.35 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Food-grade activated charcoal powder","amount":"2 g (about 1/2 tsp) — for a soft grey tint only"},{"item":"Eucalyptus essential oil","amount":"20 drops"}],"method":["Melt the shea butter, sunflower oil and beeswax together in a double boiler until clear (5-7 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 20-30 min, until cloudy and firm at the edges.","Whip on medium-high for 5-7 min, until light and fluffy.","Add the eucalyptus essential oil in the last minute of whipping.","Sprinkle the activated charcoal over the top and fold it in gently by hand with a spatula for a soft marbled grey look — don't whip it in, or the color goes flat and grey all over.","Spoon into a jar."],"tips":["Start with less charcoal than you think you need — 2 g gives a smoky marbled look in 225 g of butter; more turns the whole jar dark grey.","Activated charcoal can mark light-colored towels at first; let skin absorb fully before dressing."],"safety_note":null,"keywords":["shea butter","body butter","activated charcoal","eucalyptus","whipped","detox feel","marbled"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"holiday-vanilla-kokum-mango-butter-bars","title":"Holiday Vanilla Bean Kokum-Mango Butter Bars","cat":"body-butter","time":"15 min active, plus 30 min to set","batch_size":"eight 1.5 oz (40 g) mini bars, about 12 oz (340 g) total","shelf_life":"6-12 months at room temperature in a sealed tin or jar. Anhydrous, so no preservative is needed — just keep the bar dry between uses.","ingredients":[{"item":"Kokum butter, chopped","amount":"90 g (3.2 oz)"},{"item":"Mango butter","amount":"90 g (3.2 oz)"},{"item":"Sweet almond oil","amount":"55 g (1.9 oz)"},{"item":"Beeswax pellets","amount":"100 g (3.5 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Vanilla fragrance oil","amount":"30 drops"}],"method":["Melt the kokum butter, mango butter, almond oil and beeswax together in a double boiler until fully clear (10-12 min).","Remove from heat and stir in the vitamin E oil.","Let it cool for 3-4 min, just until it stops steaming, then stir in the vanilla fragrance oil.","Pour into eight small mini-bar or mini-muffin silicone molds.","Refrigerate 15-20 min, or room temperature 1.5-2 hours, until fully solid.","Pop out of the molds and wrap individually or box as a gift set."],"tips":["Mini bars are an easy stocking-stuffer size — eight bars from one batch means low cost per gift.","If a bar looks dull or has a thin white film after unmolding, that's cocoa-butter-style bloom from fast cooling; it doesn't affect how it performs, only the shine."],"safety_note":null,"keywords":["body butter bar","holiday gift","vanilla","kokum butter","mango butter","mini bars","solid"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"whipped-mango-butter-pink-clay-rose","title":"Whipped Mango Butter with Pink Clay & Rose","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"Up to 1 year at room temperature, away from direct sunlight. This recipe has no water in it, so it doesn't need a preservative — just keep water (wet fingers, steam) out of the jar.","ingredients":[{"item":"Mango butter","amount":"120 g (4.2 oz)"},{"item":"Sweet almond oil","amount":"55 g (1.9 oz)"},{"item":"Beeswax pellets","amount":"10 g (0.35 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"French pink cosmetic clay","amount":"4 g (about 1 tsp) — for a soft blush tint only"},{"item":"Rose fragrance oil","amount":"20 drops"}],"method":["Melt the mango butter, almond oil and beeswax together in a double boiler until clear (5-7 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 20-30 min, until firm at the edges.","Whip on medium-high for 5-7 min, until light and fluffy.","Add the rose fragrance oil in the last minute of whipping.","Sift the pink clay over the top and fold it in gently with a spatula just until streaky — over-mixing turns the whole batch a flat, even pink.","Spoon into a jar."],"tips":["French pink clay is mild and mostly used here for color, not for its usual clay benefits (those need water contact to really work) — think of it as a natural blush, not an active ingredient.","For a deeper rose color, add clay in 1 g increments and check the shade before adding more."],"safety_note":null,"keywords":["mango butter","body butter","rose","pink clay","whipped","floral","marbled","gift"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"whipped-cocoa-butter-rosehip-cinnamon","title":"Whipped Cocoa Butter with Rosehip Oil & Cinnamon","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"Up to 1 year at room temperature, away from direct sunlight. This recipe has no water in it, so it doesn't need a preservative — just keep water (wet fingers, steam) out of the jar.","ingredients":[{"item":"Cocoa butter, chopped","amount":"115 g (4.1 oz)"},{"item":"Rosehip seed oil","amount":"55 g (1.9 oz)"},{"item":"Beeswax pellets","amount":"8 g (0.28 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Cinnamon essential oil","amount":"5 drops — keep this low, see safety note"},{"item":"Vanilla fragrance oil","amount":"15 drops"}],"method":["Melt the cocoa butter, rosehip oil and beeswax together in a double boiler until fully clear (8-10 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 25-30 min, until the edges turn pale and opaque.","Whip on medium-high for 6-8 min, until light and mousse-like.","Add the cinnamon and vanilla in the last minute of whipping.","Spoon into a jar and smooth the top."],"tips":["This smells like spiced hot chocolate — the natural cocoa butter scent does a lot of the work, so cinnamon only needs a whisper.","If the cinnamon scent fades faster than you'd like after a few weeks, add 2 more drops to your next batch rather than increasing this one."],"safety_note":"Cinnamon essential oil is a known skin sensitizer even in small amounts. This recipe uses a low, leave-on-safe dose — don't add more, and patch test on your inner arm before applying to larger areas.","keywords":["cocoa butter","body butter","cinnamon","rosehip oil","whipped","spiced","dessert scent"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"unscented-whipped-shea-butter-sensitive-skin","title":"Unscented Whipped Shea Butter for Sensitive Skin","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"Up to 1 year at room temperature, away from direct sunlight. This recipe has no water in it, so it doesn't need a preservative — just keep water (wet fingers, steam) out of the jar.","ingredients":[{"item":"Shea butter","amount":"125 g (4.4 oz)"},{"item":"Grapeseed oil","amount":"55 g (1.9 oz)"},{"item":"Beeswax pellets","amount":"10 g (0.35 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"}],"method":["Melt the shea butter, grapeseed oil and beeswax together in a double boiler until clear (5-7 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 20-30 min, until cloudy and firm at the edges.","Whip on medium-high for 5-8 min, until light and fluffy.","Spoon into a jar without tapping it down."],"tips":["No fragrance or essential oil at all makes this a safe default for reactive skin, eczema-prone patches, or right after shaving.","Grapeseed oil is lighter and less greasy-feeling than almond oil, which suits sensitive skin that doesn't like heavy residue."],"safety_note":null,"keywords":["shea butter","body butter","unscented","fragrance-free","sensitive skin","whipped","eczema-friendly"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"holiday-jasmine-illipe-cocoa-butter-bars","title":"Holiday Jasmine Illipe-Cocoa Butter Bars","cat":"body-butter","time":"15 min active, plus 30 min to set","batch_size":"six 2 oz (55 g) bars, about 12 oz (340 g) total","shelf_life":"6-12 months at room temperature in a sealed tin or jar. Anhydrous, so no preservative is needed — just keep the bar dry between uses.","ingredients":[{"item":"Illipe butter, chopped","amount":"90 g (3.2 oz)"},{"item":"Cocoa butter, chopped","amount":"90 g (3.2 oz)"},{"item":"Sweet almond oil","amount":"50 g (1.8 oz)"},{"item":"Beeswax pellets","amount":"100 g (3.5 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Jasmine fragrance oil","amount":"25 drops"}],"method":["Melt the illipe butter, cocoa butter, almond oil and beeswax together in a double boiler until fully clear (10-12 min).","Remove from heat and stir in the vitamin E oil.","Let it cool for 3-4 min, just until it stops steaming, then stir in the jasmine fragrance oil.","Pour into six silicone bar molds.","Refrigerate 20-30 min, or room temperature 2-3 hours, until fully solid.","Pop out of the molds and wrap for gifting."],"tips":["The illipe-cocoa combination makes an unusually hard, long-wearing bar — a good choice if you're shipping gifts in warm weather.","Jasmine is a heavy, sweet floral; if you want it lighter, blend half jasmine with half a citrus fragrance oil instead."],"safety_note":null,"keywords":["body butter bar","holiday gift","jasmine","illipe butter","cocoa butter","floral","solid"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"whipped-kokum-butter-argan-bergamot","title":"Whipped Kokum Butter with Argan Oil & Bergamot","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"6-12 months at room temperature, away from direct heat. This is a water-free (anhydrous) recipe, so it doesn't need a preservative.","ingredients":[{"item":"Kokum butter, chopped","amount":"110 g (3.9 oz)"},{"item":"Argan oil","amount":"60 g (2.1 oz)"},{"item":"Beeswax pellets","amount":"10 g (0.35 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Bergamot essential oil (bergapten-free / FCF, non-phototoxic type)","amount":"20 drops"}],"method":["Melt the kokum butter, argan oil and beeswax together in a double boiler until clear (7-9 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 25-30 min, until firm at the edges.","Whip on medium-high for 6-8 min, until light and fluffy.","Add the bergamot essential oil in the last minute of whipping.","Spoon into a jar."],"tips":["Argan oil's nutty undertone pairs well with bergamot's bright citrus-floral note instead of competing with it.","Kokum butter whips to a very stable, dense foam — if yours feels too stiff to scoop cold, let the jar sit at room temperature for a few minutes first."],"safety_note":"Standard bergamot essential oil can cause skin damage in sunlight (phototoxicity). Use only a bergapten-free / FCF bergamot oil in this leave-on product, and avoid direct sun on treated skin for 12-18 hours if unsure of the type.","keywords":["kokum butter","body butter","bergamot","argan oil","citrus","whipped","anhydrous"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"lavender-mango-butter-solid-bar","title":"Lavender Mango Butter Solid Bar","cat":"body-butter","time":"15 min active, plus 30 min to set","batch_size":"six 2 oz (55 g) bars, about 12 oz (340 g) total","shelf_life":"6-12 months at room temperature in a sealed tin or jar. Anhydrous, so no preservative is needed — just keep the bar dry between uses.","ingredients":[{"item":"Mango butter","amount":"100 g (3.5 oz)"},{"item":"Sunflower oil","amount":"70 g (2.5 oz)"},{"item":"Beeswax pellets","amount":"95 g (3.3 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Lavender essential oil","amount":"30 drops"}],"method":["Melt the mango butter, sunflower oil and beeswax together in a double boiler until fully clear (9-11 min).","Remove from heat and stir in the vitamin E oil.","Let it cool for 3-4 min, just until it stops steaming, then stir in the lavender essential oil.","Pour into six silicone bar molds.","Refrigerate 20-30 min, or room temperature 2-3 hours, until fully solid.","Pop out of the molds and store in a tin."],"tips":["Mango butter makes a slightly softer bar than cocoa or illipe — it glides on a touch more easily, which works well for a bedtime routine.","Keep a bar on the nightstand: rubbing it over hands and feet before bed is a simple wind-down ritual."],"safety_note":null,"keywords":["body butter bar","lavender","mango butter","solid","bedtime","relaxing","gift"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"winter-rich-cardamom-vanilla-shea-illipe-whip","title":"Winter Rich Cardamom Vanilla Shea-Illipe Whip","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 10 oz (280 g)","shelf_life":"Up to 1 year at room temperature. No water, no preservative needed — this richer, double-butter blend is especially stable.","ingredients":[{"item":"Shea butter","amount":"80 g (2.8 oz)"},{"item":"Illipe butter, chopped","amount":"70 g (2.5 oz)"},{"item":"Avocado oil","amount":"45 g (1.6 oz)"},{"item":"Beeswax pellets","amount":"16 g (0.56 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Cardamom essential oil","amount":"8 drops"},{"item":"Vanilla fragrance oil","amount":"25 drops"}],"method":["Melt the shea butter, illipe butter, avocado oil and beeswax together in a double boiler until fully clear (9-11 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 30-35 min — check at 20 min, since the double butter and extra wax firm up faster than a single-butter whip.","Whip on medium-high for 5-7 min, until light but denser than a classic single-butter whip.","Add the cardamom and vanilla in the last minute of whipping.","Spoon into a 10 oz jar."],"tips":["This is the richest, heaviest whip in the lineup — built for cracked winter heels and elbows, not for a light daytime layer.","Avocado oil adds a deep green tint to the raw mixture that fades to warm cream once whipped; that's normal, not a sign anything went wrong."],"safety_note":null,"keywords":["body butter","winter","cardamom","vanilla","shea butter","illipe butter","whipped","rich"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"golden-turmeric-whipped-cocoa-butter","title":"Golden Turmeric Whipped Cocoa Butter","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"Up to 1 year at room temperature, away from direct sunlight. This recipe has no water in it, so it doesn't need a preservative — just keep water (wet fingers, steam) out of the jar.","ingredients":[{"item":"Cocoa butter, chopped","amount":"115 g (4.1 oz)"},{"item":"Sweet almond oil","amount":"60 g (2.1 oz)"},{"item":"Beeswax pellets","amount":"8 g (0.28 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Turmeric powder (for color)","amount":"1.5 g (about 1/4 tsp) — a little goes a long way"},{"item":"Sweet orange essential oil","amount":"15 drops"}],"method":["Melt the cocoa butter, almond oil and beeswax together in a double boiler until clear (8-10 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 25-30 min, until the edges turn pale.","Whip on medium-high for 6-8 min, until light and fluffy.","Whisk the turmeric powder into the orange essential oil first to break up any clumps, then fold this paste into the whipped butter by hand.","Spoon into a jar."],"tips":["Turmeric can temporarily tint very light skin, nails, and pale fabrics (like white towels) a faint yellow — let it absorb fully before dressing, and test on a small patch first if this is new for you.","1.5 g is enough for a warm golden tone in 225 g of butter; adding much more mostly adds staining risk without improving the color."],"safety_note":"Turmeric can stain light fabric and may temporarily tint very fair skin. It's used here only for color in a small, tested amount — let the butter absorb fully before putting on light-colored clothing.","keywords":["cocoa butter","body butter","turmeric","golden","orange","whipped","warm tone"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"spa-night-eucalyptus-rosemary-kokum-bars","title":"Spa Night Eucalyptus Rosemary Kokum Butter Bars","cat":"body-butter","time":"15 min active, plus 30 min to set","batch_size":"six 2 oz (55 g) bars, about 12 oz (340 g) total","shelf_life":"6-12 months at room temperature in a sealed tin or jar. Anhydrous, so no preservative is needed — just keep the bar dry between uses.","ingredients":[{"item":"Kokum butter, chopped","amount":"100 g (3.5 oz)"},{"item":"Jojoba oil","amount":"70 g (2.5 oz)"},{"item":"Beeswax pellets","amount":"95 g (3.3 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Eucalyptus essential oil","amount":"18 drops"},{"item":"Rosemary essential oil","amount":"12 drops"}],"method":["Melt the kokum butter, jojoba oil and beeswax together in a double boiler until fully clear (10-12 min — kokum butter is very firm).","Remove from heat and stir in the vitamin E oil.","Let it cool for 3-4 min, just until it stops steaming, then stir in the eucalyptus and rosemary.","Pour into six silicone bar molds.","Refrigerate 20-30 min, or room temperature 2-3 hours, until fully solid.","Pop out of the molds and store near the shower or bath."],"tips":["Keep one bar in the shower caddy — the steam helps release the eucalyptus-rosemary scent as you rub it on damp skin at the end of a shower.","Kokum butter makes an unusually hard bar; if it feels tough to rub on cold skin, warm it briefly between your palms first."],"safety_note":null,"keywords":["body butter bar","spa night","eucalyptus","rosemary","kokum butter","solid","herbal"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"whipped-mango-butter-rosehip-rose","title":"Whipped Mango Butter with Rosehip Oil & Rose","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"Up to 1 year at room temperature, away from direct sunlight. This recipe has no water in it, so it doesn't need a preservative — just keep water (wet fingers, steam) out of the jar.","ingredients":[{"item":"Mango butter","amount":"120 g (4.2 oz)"},{"item":"Rosehip seed oil","amount":"55 g (1.9 oz)"},{"item":"Beeswax pellets","amount":"10 g (0.35 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Rose fragrance oil","amount":"20 drops"}],"method":["Melt the mango butter, rosehip oil and beeswax together in a double boiler until clear (5-7 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 20-30 min, until firm at the edges.","Whip on medium-high for 5-7 min, until light and fluffy.","Add the rose fragrance oil in the last minute of whipping.","Spoon into a jar."],"tips":["Rosehip oil has a natural reddish-orange tint that can carry through faintly into the finished whip — that's the oil, not a flaw.","This pairing leans toward a classic, old-fashioned rose scent; layer it under a floral perfume for a long-lasting base note."],"safety_note":null,"keywords":["mango butter","body butter","rose","rosehip oil","whipped","floral","classic"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"summer-grapefruit-mint-shea-cocoa-whip","title":"Summer Grapefruit Mint Shea-Cocoa Whip","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 4 oz (115 g), a travel-size tin","shelf_life":"6-12 months at room temperature, away from direct heat. This is a water-free (anhydrous) recipe, so it doesn't need a preservative.","ingredients":[{"item":"Shea butter","amount":"35 g (1.2 oz)"},{"item":"Cocoa butter, chopped","amount":"25 g (0.88 oz)"},{"item":"Grapeseed oil","amount":"40 g (1.4 oz) — extra oil keeps this light for summer"},{"item":"Beeswax pellets","amount":"5 g (0.18 oz)"},{"item":"Vitamin E oil","amount":"1.5 g (about 1/4 tsp)"},{"item":"Grapefruit essential oil","amount":"12 drops"},{"item":"Peppermint essential oil","amount":"4 drops"}],"method":["Melt the shea butter, cocoa butter, grapeseed oil and beeswax together in a double boiler until clear (5-6 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 15-20 min — this small batch cools faster than a full-size one, so check it early.","Whip on medium-high for 4-5 min, until light and airy.","Add the grapefruit and peppermint essential oils in the last minute of whipping.","Spoon into a small 4 oz travel tin."],"tips":["The higher oil-to-butter ratio and small batch size make this soak in fast with almost no greasy feel — built for hot weather, not winter dryness.","A travel tin like this is the right size for a beach bag or gym bag without taking up much room."],"safety_note":null,"keywords":["body butter","summer","grapefruit","peppermint","travel size","whipped","light","shea butter"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"unscented-whipped-illipe-butter-baby-safe","title":"Unscented Whipped Illipe Butter, Baby-Safe","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"Up to 1 year at room temperature, away from direct sunlight. This recipe has no water in it, so it doesn't need a preservative — just keep water (wet fingers, steam) out of the jar.","ingredients":[{"item":"Illipe butter, chopped","amount":"120 g (4.2 oz)"},{"item":"Sweet almond oil","amount":"55 g (1.9 oz)"},{"item":"Beeswax pellets","amount":"10 g (0.35 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"}],"method":["Melt the illipe butter, almond oil and beeswax together in a double boiler until clear (8-10 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 30 min, until firm at the edges.","Whip on medium-high for 6-8 min, until light and silky.","Spoon into a jar without tapping it down."],"tips":["No essential oils at all makes this a reasonable choice for very young or reactive skin — check with a pediatrician before using any new product on an infant, since 'natural' doesn't automatically mean safe for babies.","If you want a trace of scent for an adult version, a single drop of chamomile or lavender per ounce is a gentle place to start — keep it well below that for anyone under 2."],"safety_note":null,"keywords":["illipe butter","body butter","unscented","fragrance-free","gentle","whipped","family-friendly"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"holiday-jasmine-vanilla-cocoa-mango-whip","title":"Holiday Jasmine Vanilla Cocoa-Mango Whip","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 10 oz (280 g)","shelf_life":"Up to 1 year at room temperature. No water, no preservative needed — this richer, double-butter blend is especially stable.","ingredients":[{"item":"Cocoa butter, chopped","amount":"75 g (2.6 oz)"},{"item":"Mango butter","amount":"75 g (2.6 oz)"},{"item":"Argan oil","amount":"45 g (1.6 oz)"},{"item":"Beeswax pellets","amount":"16 g (0.56 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Jasmine fragrance oil","amount":"18 drops"},{"item":"Vanilla fragrance oil","amount":"18 drops"}],"method":["Melt the cocoa butter, mango butter, argan oil and beeswax together in a double boiler until fully clear (9-11 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 30-35 min, checking at 20 min since the double-butter base firms up faster.","Whip on medium-high for 5-7 min, until light but denser than a single-butter whip.","Add the jasmine and vanilla in the last minute of whipping.","Spoon into a 10 oz gift jar."],"tips":["Jasmine and vanilla together smell like a warm, sweet perfume — a good fit for a holiday gift jar with a ribbon.","The natural cocoa butter scent underneath adds a subtle dessert note without needing a chocolate fragrance oil."],"safety_note":null,"keywords":["body butter","holiday gift","jasmine","vanilla","cocoa butter","mango butter","whipped"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"whipped-kokum-butter-almond-orange-cinnamon","title":"Whipped Kokum Butter with Almond Oil & Orange Cinnamon","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"6-12 months at room temperature, away from direct heat. This is a water-free (anhydrous) recipe, so it doesn't need a preservative.","ingredients":[{"item":"Kokum butter, chopped","amount":"110 g (3.9 oz)"},{"item":"Sweet almond oil","amount":"60 g (2.1 oz)"},{"item":"Beeswax pellets","amount":"10 g (0.35 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Sweet orange essential oil","amount":"25 drops"},{"item":"Cinnamon essential oil","amount":"4 drops — keep this low, see safety note"}],"method":["Melt the kokum butter, almond oil and beeswax together in a double boiler until clear (7-9 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 25-30 min, until firm at the edges.","Whip on medium-high for 6-8 min, until light and fluffy.","Add the orange and cinnamon essential oils in the last minute of whipping.","Spoon into a jar."],"tips":["This smells like mulled cider — orange does most of the work, cinnamon just rounds out the warmth at a very low dose.","Good as a cool-weather alternative to a purely floral whip without going fully into heavy winter-spice territory."],"safety_note":"Cinnamon essential oil is a known skin sensitizer even in small amounts. This recipe uses a low, leave-on-safe dose — don't add more, and patch test before applying to larger areas.","keywords":["kokum butter","body butter","orange","cinnamon","whipped","spiced","fall scent"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"charcoal-detox-shea-butter-bar","title":"Charcoal Detox Shea Butter Bar","cat":"body-butter","time":"15 min active, plus 30 min to set","batch_size":"six 2 oz (55 g) bars, about 12 oz (340 g) total","shelf_life":"6-12 months at room temperature in a sealed tin or jar. Anhydrous, so no preservative is needed — just keep the bar dry between uses.","ingredients":[{"item":"Shea butter","amount":"110 g (3.9 oz)"},{"item":"Avocado oil","amount":"65 g (2.3 oz)"},{"item":"Beeswax pellets","amount":"95 g (3.3 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Food-grade activated charcoal powder","amount":"2.5 g (about 1/2 tsp)"},{"item":"Eucalyptus essential oil","amount":"20 drops"}],"method":["Melt the shea butter, avocado oil and beeswax together in a double boiler until fully clear (9-11 min).","Remove from heat and stir in the vitamin E oil.","Let it cool for 3-4 min, just until it stops steaming, then whisk in the activated charcoal until evenly dispersed, followed by the eucalyptus.","Pour into six silicone bar molds.","Refrigerate 20-30 min, or room temperature 2-3 hours, until fully solid.","Pop out of the molds and store in a dark-colored tin (charcoal can dust light containers)."],"tips":["Unlike the whipped charcoal recipe, this one mixes the charcoal fully into the melted base before pouring, so the bars come out an even charcoal-grey instead of marbled.","'Detox' here just means a moisturizing bar with a charcoal tint and a fresh eucalyptus scent — avoid implying any medical detox claim when describing it."],"safety_note":null,"keywords":["body butter bar","activated charcoal","shea butter","eucalyptus","solid","detox feel","gift"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"summer-peppermint-illipe-butter-whip","title":"Summer Peppermint Illipe Butter Whip","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 4 oz (115 g), a travel-size tin","shelf_life":"6-12 months at room temperature, away from direct heat. This is a water-free (anhydrous) recipe, so it doesn't need a preservative.","ingredients":[{"item":"Illipe butter, chopped","amount":"40 g (1.4 oz)"},{"item":"Grapeseed oil","amount":"45 g (1.6 oz)"},{"item":"Beeswax pellets","amount":"5 g (0.18 oz)"},{"item":"Vitamin E oil","amount":"1.5 g (about 1/4 tsp)"},{"item":"Peppermint essential oil","amount":"6 drops"}],"method":["Melt the illipe butter, grapeseed oil and beeswax together in a double boiler until clear (6-8 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 15-20 min.","Whip on medium-high for 4-6 min, until light and fluffy.","Add the peppermint essential oil in the last minute of whipping.","Spoon into a 4 oz travel tin."],"tips":["A high oil ratio keeps this from feeling heavy on hot, sweaty skin, while the peppermint adds a cooling finish.","Keep this size in the fridge in very hot climates for an extra-refreshing after-sun application."],"safety_note":"Peppermint essential oil shouldn't be used near the eyes, on broken or sunburned skin, or on young children. Patch test first if this is new for you.","keywords":["illipe butter","body butter","summer","peppermint","travel size","whipped","cooling"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"spa-night-lavender-rosemary-mango-kokum-whip","title":"Spa Night Lavender Rosemary Mango-Kokum Whip","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 10 oz (280 g)","shelf_life":"Up to 1 year at room temperature. No water, no preservative needed — this richer, double-butter blend is especially stable.","ingredients":[{"item":"Mango butter","amount":"80 g (2.8 oz)"},{"item":"Kokum butter, chopped","amount":"65 g (2.3 oz)"},{"item":"Jojoba oil","amount":"50 g (1.8 oz)"},{"item":"Beeswax pellets","amount":"16 g (0.56 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Lavender essential oil","amount":"20 drops"},{"item":"Rosemary essential oil","amount":"8 drops"}],"method":["Melt the mango butter, kokum butter, jojoba oil and beeswax together in a double boiler until fully clear (9-11 min — kokum butter takes the longest to melt).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 30-35 min, checking at 20 min since this double-butter base firms up faster.","Whip on medium-high for 5-7 min, until light but denser than a single-butter whip.","Add the lavender and rosemary in the last minute of whipping.","Spoon into a 10 oz jar."],"tips":["Lavender calms, rosemary keeps it from smelling purely sweet — a good combination for a wind-down massage before bed.","This whip is firm enough to double as a solid-ish massage butter that warms and softens between the hands before application."],"safety_note":null,"keywords":["body butter","spa night","lavender","rosemary","mango butter","kokum butter","whipped","massage"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"whipped-shea-butter-rosehip-bergamot","title":"Whipped Shea Butter with Rosehip Oil & Bergamot","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"Up to 1 year at room temperature, away from direct sunlight. This recipe has no water in it, so it doesn't need a preservative — just keep water (wet fingers, steam) out of the jar.","ingredients":[{"item":"Shea butter","amount":"120 g (4.2 oz)"},{"item":"Rosehip seed oil","amount":"55 g (1.9 oz)"},{"item":"Beeswax pellets","amount":"10 g (0.35 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Bergamot essential oil (bergapten-free / FCF, non-phototoxic type)","amount":"20 drops"}],"method":["Melt the shea butter, rosehip oil and beeswax together in a double boiler until clear (5-7 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 20-30 min, until cloudy and firm at the edges.","Whip on medium-high for 5-7 min, until light and fluffy.","Add the bergamot essential oil in the last minute of whipping.","Spoon into a jar."],"tips":["Rosehip oil's slightly earthy base note and bergamot's bright citrus-floral top note balance each other out nicely.","This is a good 'everyday elegant' jar — not overtly sweet or heavily herbal, just a clean citrus-floral finish."],"safety_note":"Standard bergamot essential oil can cause skin damage in sunlight (phototoxicity). Use only a bergapten-free / FCF bergamot oil in this leave-on product, and avoid direct sun on treated skin for 12-18 hours if unsure of the type.","keywords":["shea butter","body butter","bergamot","rosehip oil","whipped","citrus","floral"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"holiday-cardamom-orange-cocoa-butter-bar","title":"Holiday Cardamom Orange Cocoa Butter Bar","cat":"body-butter","time":"15 min active, plus 30 min to set","batch_size":"six 2 oz (55 g) bars, about 12 oz (340 g) total","shelf_life":"6-12 months at room temperature in a sealed tin or jar. Anhydrous, so no preservative is needed — just keep the bar dry between uses.","ingredients":[{"item":"Cocoa butter, chopped","amount":"100 g (3.5 oz)"},{"item":"Sweet almond oil","amount":"65 g (2.3 oz)"},{"item":"Beeswax pellets","amount":"95 g (3.3 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Sweet orange essential oil","amount":"25 drops"},{"item":"Cardamom essential oil","amount":"7 drops"}],"method":["Melt the cocoa butter, almond oil and beeswax together in a double boiler until fully clear (10-12 min).","Remove from heat and stir in the vitamin E oil.","Let it cool for 3-4 min, just until it stops steaming, then stir in the orange and cardamom.","Pour into six silicone bar molds.","Refrigerate 20-30 min, or room temperature 2-3 hours, until fully solid.","Pop out of the molds and box for gifting."],"tips":["Orange and cardamom over a cocoa-butter base smells like a holiday dessert without needing any actual chocolate or vanilla added.","Wrap bars in parchment and twine for a rustic gift presentation that also keeps them from sticking to tissue paper."],"safety_note":null,"keywords":["body butter bar","holiday gift","cardamom","orange","cocoa butter","solid","spiced"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"unscented-whipped-mango-butter","title":"Unscented Whipped Mango Butter","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"6-12 months at room temperature, away from direct heat. This is a water-free (anhydrous) recipe, so it doesn't need a preservative.","ingredients":[{"item":"Mango butter","amount":"125 g (4.4 oz)"},{"item":"Sunflower oil","amount":"55 g (1.9 oz)"},{"item":"Beeswax pellets","amount":"10 g (0.35 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"}],"method":["Melt the mango butter, sunflower oil and beeswax together in a double boiler until clear (5-7 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 20-25 min, until the edges firm up.","Whip on medium-high for 5-7 min, until light and airy.","Spoon into a jar without tapping it down."],"tips":["Mango butter on its own has almost no smell, which makes this a good base to layer under perfume without clashing scents.","This plain version also works well as a 'canvas' — stir 15-20 drops of any essential oil into a single jar yourself without touching the master batch."],"safety_note":null,"keywords":["mango butter","body butter","unscented","fragrance-free","whipped","layering base"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"winter-rich-vanilla-illipe-shea-whip","title":"Winter Rich Vanilla Illipe-Shea Whip","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 10 oz (280 g)","shelf_life":"Up to 1 year at room temperature. No water, no preservative needed — this richer, double-butter blend is especially stable.","ingredients":[{"item":"Illipe butter, chopped","amount":"80 g (2.8 oz)"},{"item":"Shea butter","amount":"65 g (2.3 oz)"},{"item":"Argan oil","amount":"45 g (1.6 oz)"},{"item":"Beeswax pellets","amount":"16 g (0.56 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Vanilla fragrance oil","amount":"30 drops"}],"method":["Melt the illipe butter, shea butter, argan oil and beeswax together in a double boiler until fully clear (9-11 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 30-35 min, checking at 20 min.","Whip on medium-high for 5-7 min, until light but denser than a single-butter whip.","Add the vanilla fragrance oil in the last minute of whipping.","Spoon into a 10 oz jar."],"tips":["This is built for the driest months — thicker application, longer-lasting barrier, and a cozy vanilla scent to match.","If it feels too thick to scoop straight from the fridge in winter, leave the jar on a warm windowsill or radiator shelf for a few minutes first."],"safety_note":null,"keywords":["body butter","winter","vanilla","illipe butter","shea butter","whipped","rich","dry skin"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"whipped-kokum-butter-grapeseed-eucalyptus","title":"Whipped Kokum Butter with Grapeseed Oil & Eucalyptus","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"6-12 months at room temperature, away from direct heat. This is a water-free (anhydrous) recipe, so it doesn't need a preservative.","ingredients":[{"item":"Kokum butter, chopped","amount":"115 g (4.1 oz)"},{"item":"Grapeseed oil","amount":"58 g (2.0 oz)"},{"item":"Beeswax pellets","amount":"10 g (0.35 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Eucalyptus essential oil","amount":"22 drops"}],"method":["Melt the kokum butter, grapeseed oil and beeswax together in a double boiler until clear (7-9 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 25-30 min, until firm at the edges.","Whip on medium-high for 6-8 min, until light and fluffy.","Add the eucalyptus essential oil in the last minute of whipping.","Spoon into a jar."],"tips":["A single clean scent (just eucalyptus) keeps this one simple — good for a gym bag or a congested-feeling morning.","Grapeseed oil is light enough that this whip still feels non-greasy even with kokum butter's density."],"safety_note":null,"keywords":["kokum butter","body butter","eucalyptus","grapeseed oil","whipped","fresh","anhydrous"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"whipped-cocoa-butter-pink-clay-rose","title":"Whipped Cocoa Butter with Pink Clay & Rose","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"Up to 1 year at room temperature, away from direct sunlight. This recipe has no water in it, so it doesn't need a preservative — just keep water (wet fingers, steam) out of the jar.","ingredients":[{"item":"Cocoa butter, chopped","amount":"115 g (4.1 oz)"},{"item":"Jojoba oil","amount":"55 g (1.9 oz)"},{"item":"Beeswax pellets","amount":"8 g (0.28 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"French pink cosmetic clay","amount":"3 g (about 3/4 tsp) — for a soft tint only"},{"item":"Rose fragrance oil","amount":"18 drops"}],"method":["Melt the cocoa butter, jojoba oil and beeswax together in a double boiler until fully clear (8-10 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 25-30 min, until the edges turn pale.","Whip on medium-high for 6-8 min, until light and mousse-like.","Add the rose fragrance oil in the last minute of whipping.","Sift the pink clay over the top and fold in by hand just until streaky, for a marbled rose-and-cream look.","Spoon into a jar."],"tips":["Cocoa butter's pale yellow base mutes pink clay into more of a dusty rose than a bright pink — that's expected with this butter.","If the marbling blends too evenly and goes flat pink, fold more gently and for less time next round."],"safety_note":null,"keywords":["cocoa butter","body butter","rose","pink clay","whipped","floral","marbled"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"grapefruit-bergamot-mango-butter-bar","title":"Grapefruit Bergamot Mango Butter Bar","cat":"body-butter","time":"15 min active, plus 30 min to set","batch_size":"six 2 oz (55 g) bars, about 12 oz (340 g) total","shelf_life":"6-12 months at room temperature in a sealed tin or jar. Anhydrous, so no preservative is needed — just keep the bar dry between uses.","ingredients":[{"item":"Mango butter","amount":"100 g (3.5 oz)"},{"item":"Avocado oil","amount":"65 g (2.3 oz)"},{"item":"Beeswax pellets","amount":"95 g (3.3 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Grapefruit essential oil","amount":"20 drops"},{"item":"Bergamot essential oil (bergapten-free / FCF, non-phototoxic type)","amount":"10 drops"}],"method":["Melt the mango butter, avocado oil and beeswax together in a double boiler until fully clear (9-11 min).","Remove from heat and stir in the vitamin E oil.","Let it cool for 3-4 min, just until it stops steaming, then stir in the grapefruit and bergamot.","Pour into six silicone bar molds.","Refrigerate 20-30 min, or room temperature 2-3 hours, until fully solid.","Pop out of the molds and store in a tin."],"tips":["A bright, uplifting citrus bar — good for a morning shower routine rather than a bedtime one.","If the citrus scent fades within a few weeks, that's normal for essential oils; add a drop or two directly to a bar you're actively using to refresh it."],"safety_note":"Standard bergamot essential oil can cause skin damage in sunlight (phototoxicity). Use only a bergapten-free / FCF bergamot oil in this leave-on product, and avoid direct sun on treated skin for 12-18 hours if unsure of the type.","keywords":["body butter bar","grapefruit","bergamot","mango butter","solid","citrus","morning"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"holiday-cinnamon-vanilla-shea-kokum-minis","title":"Holiday Cinnamon Vanilla Shea-Kokum Butter Minis","cat":"body-butter","time":"15 min active, plus 30 min to set","batch_size":"eight 1.5 oz (40 g) mini bars, about 12 oz (340 g) total","shelf_life":"6-12 months at room temperature in a sealed tin or jar. Anhydrous, so no preservative is needed — just keep the bar dry between uses.","ingredients":[{"item":"Shea butter","amount":"90 g (3.2 oz)"},{"item":"Kokum butter, chopped","amount":"90 g (3.2 oz)"},{"item":"Sweet almond oil","amount":"55 g (1.9 oz)"},{"item":"Beeswax pellets","amount":"100 g (3.5 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Vanilla fragrance oil","amount":"25 drops"},{"item":"Cinnamon essential oil","amount":"5 drops — keep this low, see safety note"}],"method":["Melt the shea butter, kokum butter, almond oil and beeswax together in a double boiler until fully clear (10-12 min).","Remove from heat and stir in the vitamin E oil.","Let it cool for 3-4 min, just until it stops steaming, then stir in the vanilla and cinnamon.","Pour into eight small mini-bar silicone molds.","Refrigerate 15-20 min, or room temperature 1.5-2 hours, until fully solid.","Pop out of the molds and box or wrap individually."],"tips":["This smells like a snickerdoodle cookie — vanilla leads, cinnamon just adds warmth at a low, skin-safe dose.","Mini bars like these are an easy low-cost line to make in a big batch for a holiday market table."],"safety_note":"Cinnamon essential oil is a known skin sensitizer even in small amounts. This recipe uses a low, leave-on-safe dose spread across eight bars — don't add more, and patch test before full use.","keywords":["body butter bar","holiday gift","cinnamon","vanilla","shea butter","kokum butter","mini bars"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"whipped-illipe-butter-rosehip-jasmine","title":"Whipped Illipe Butter with Rosehip Oil & Jasmine","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"Up to 1 year at room temperature, away from direct sunlight. This recipe has no water in it, so it doesn't need a preservative — just keep water (wet fingers, steam) out of the jar.","ingredients":[{"item":"Illipe butter, chopped","amount":"115 g (4.1 oz)"},{"item":"Rosehip seed oil","amount":"60 g (2.1 oz)"},{"item":"Beeswax pellets","amount":"10 g (0.35 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Jasmine fragrance oil","amount":"20 drops"}],"method":["Melt the illipe butter, rosehip oil and beeswax together in a double boiler until clear (8-10 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 30 min, until the edges firm up.","Whip on medium-high for 6-8 min, until light and silky.","Add the jasmine fragrance oil in the last minute of whipping.","Spoon into a jar."],"tips":["Illipe's firm structure holds the whip's peaks well, so this one looks especially good if you're piping it into jars rather than just spooning it.","Jasmine is strong; if you prefer it lighter, cut the amount to 10-12 drops and top up with a neutral carrier like extra rosehip oil."],"safety_note":null,"keywords":["illipe butter","body butter","jasmine","rosehip oil","whipped","floral","elegant"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"summer-orange-whipped-cocoa-butter","title":"Summer Orange Whipped Cocoa Butter","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 4 oz (115 g), a travel-size tin","shelf_life":"6-12 months at room temperature, away from direct heat. This is a water-free (anhydrous) recipe, so it doesn't need a preservative.","ingredients":[{"item":"Cocoa butter, chopped","amount":"30 g (1.1 oz)"},{"item":"Sunflower oil","amount":"50 g (1.8 oz)"},{"item":"Beeswax pellets","amount":"5 g (0.18 oz)"},{"item":"Vitamin E oil","amount":"1.5 g (about 1/4 tsp)"},{"item":"Sweet orange essential oil","amount":"15 drops"}],"method":["Melt the cocoa butter, sunflower oil and beeswax together in a double boiler until clear (6-8 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 15-20 min.","Whip on medium-high for 4-6 min, until light and fluffy.","Add the sweet orange essential oil in the last minute of whipping.","Spoon into a 4 oz travel tin."],"tips":["A light cocoa-orange scent that reads more like a creamsicle than a rich chocolate dessert, thanks to the higher oil ratio.","Sweet orange essential oil is generally not considered phototoxic at normal leave-on doses, unlike cold-pressed bergamot or lime — a reasonable citrus pick for daytime summer use."],"safety_note":null,"keywords":["cocoa butter","body butter","summer","orange","travel size","whipped","light","citrus"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"turmeric-cardamom-shea-butter-bar","title":"Turmeric Cardamom Shea Butter Bar","cat":"body-butter","time":"15 min active, plus 30 min to set","batch_size":"six 2 oz (55 g) bars, about 12 oz (340 g) total","shelf_life":"6-12 months at room temperature in a sealed tin or jar. Anhydrous, so no preservative is needed — just keep the bar dry between uses.","ingredients":[{"item":"Shea butter","amount":"110 g (3.9 oz)"},{"item":"Sweet almond oil","amount":"65 g (2.3 oz)"},{"item":"Beeswax pellets","amount":"95 g (3.3 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Turmeric powder (for color)","amount":"2 g (about 1/3 tsp)"},{"item":"Cardamom essential oil","amount":"8 drops"}],"method":["Melt the shea butter, almond oil and beeswax together in a double boiler until fully clear (9-11 min).","Remove from heat and stir in the vitamin E oil.","Let it cool for 3-4 min, just until it stops steaming. Whisk the turmeric into a teaspoon of the warm mixture first to form a smooth paste, then stir that paste back into the batch along with the cardamom.","Pour into six silicone bar molds.","Refrigerate 20-30 min, or room temperature 2-3 hours, until fully solid.","Pop out of the molds and store in a dark tin, away from light fabric."],"tips":["Pre-mixing turmeric into a small amount of warm base before adding it to the whole batch avoids yellow clumps or streaks.","This spiced golden bar makes a nice gift paired with the Golden Turmeric Whipped Cocoa Butter for a matching 'golden spice' set."],"safety_note":"Turmeric can stain light fabric and may temporarily tint very fair skin. Let bars absorb fully before dressing, and keep them away from light-colored towels and linens while they're new.","keywords":["body butter bar","turmeric","cardamom","shea butter","solid","golden","spiced"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"spa-night-lavender-mango-illipe-whip","title":"Spa Night Lavender Mango-Illipe Whip","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 10 oz (280 g)","shelf_life":"Up to 1 year at room temperature. No water, no preservative needed — this richer, double-butter blend is especially stable.","ingredients":[{"item":"Mango butter","amount":"75 g (2.6 oz)"},{"item":"Illipe butter, chopped","amount":"70 g (2.5 oz)"},{"item":"Grapeseed oil","amount":"45 g (1.6 oz)"},{"item":"Beeswax pellets","amount":"16 g (0.56 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Lavender essential oil","amount":"28 drops"}],"method":["Melt the mango butter, illipe butter, grapeseed oil and beeswax together in a double boiler until fully clear (9-11 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 30-35 min, checking at 20 min.","Whip on medium-high for 5-7 min, until light but denser than a single-butter whip.","Add the lavender essential oil in the last minute of whipping.","Spoon into a 10 oz jar."],"tips":["A single, generous dose of lavender (no blending with other oils) keeps this one purely calming — ideal right before bed.","The mango-illipe combination gives a silkier glide than an all-illipe whip, while staying firmer than an all-mango one."],"safety_note":null,"keywords":["body butter","spa night","lavender","mango butter","illipe butter","whipped","relaxing"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"fragrance-free-whipped-kokum-butter","title":"Fragrance-Free Whipped Kokum Butter","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"6-12 months at room temperature, away from direct heat. This is a water-free (anhydrous) recipe, so it doesn't need a preservative.","ingredients":[{"item":"Kokum butter, chopped","amount":"120 g (4.2 oz)"},{"item":"Argan oil","amount":"55 g (1.9 oz)"},{"item":"Beeswax pellets","amount":"10 g (0.35 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"}],"method":["Melt the kokum butter, argan oil and beeswax together in a double boiler until clear (7-9 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 25-30 min, until firm at the edges.","Whip on medium-high for 6-8 min, until light and fluffy.","Spoon into a jar without tapping it down."],"tips":["Argan oil's naturally nutty smell is faint enough that this still reads as 'unscented' to most noses once whipped.","A dependable option for anyone who finds even mild essential oil blends too strong for daily, all-over use."],"safety_note":null,"keywords":["kokum butter","body butter","unscented","fragrance-free","argan oil","whipped","anhydrous"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"whipped-cocoa-butter-avocado-rose-vanilla","title":"Whipped Cocoa Butter with Avocado Oil, Rose & Vanilla","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"Up to 1 year at room temperature, away from direct sunlight. This recipe has no water in it, so it doesn't need a preservative — just keep water (wet fingers, steam) out of the jar.","ingredients":[{"item":"Cocoa butter, chopped","amount":"110 g (3.9 oz)"},{"item":"Avocado oil","amount":"65 g (2.3 oz)"},{"item":"Beeswax pellets","amount":"8 g (0.28 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Rose fragrance oil","amount":"12 drops"},{"item":"Vanilla fragrance oil","amount":"12 drops"}],"method":["Melt the cocoa butter, avocado oil and beeswax together in a double boiler until fully clear (8-10 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 25-30 min, until the edges turn pale.","Whip on medium-high for 6-8 min, until light and mousse-like.","Add the rose and vanilla fragrance oils in the last minute of whipping.","Spoon into a jar."],"tips":["Avocado oil is heavier than almond or jojoba, which makes this a good pick for very dry skin despite the lighter floral scent on top.","The rose-vanilla blend over a cocoa butter base smells closer to a bakery-floral perfume than a straightforward dessert scent."],"safety_note":null,"keywords":["cocoa butter","body butter","rose","vanilla","avocado oil","whipped","floral","rich"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"whipped-shea-butter-almond-rosemary-peppermint","title":"Whipped Shea Butter with Almond Oil & Rosemary Peppermint","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"Up to 1 year at room temperature, away from direct sunlight. This recipe has no water in it, so it doesn't need a preservative — just keep water (wet fingers, steam) out of the jar.","ingredients":[{"item":"Shea butter","amount":"120 g (4.2 oz)"},{"item":"Sweet almond oil","amount":"58 g (2.0 oz)"},{"item":"Beeswax pellets","amount":"10 g (0.35 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Rosemary essential oil","amount":"18 drops"},{"item":"Peppermint essential oil","amount":"7 drops"}],"method":["Melt the shea butter, almond oil and beeswax together in a double boiler until clear (5-7 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 20-30 min, until cloudy and firm at the edges.","Whip on medium-high for 5-7 min, until light and fluffy.","Add the rosemary and peppermint essential oils in the last minute of whipping.","Spoon into a jar."],"tips":["This is an energizing morning blend — rub a small amount into calves and forearms before a workout or a long day on your feet.","Rosemary essential oil has a strong, medicinal-herbal smell on its own; the small amount of peppermint here brightens it instead of making it sharper."],"safety_note":"Peppermint essential oil can tingle strongly on skin. Keep use to arms and legs, avoid the face and broken skin, and patch test if you haven't used peppermint on your body before.","keywords":["shea butter","body butter","rosemary","peppermint","whipped","herbal","energizing"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"holiday-bergamot-cardamom-illipe-mango-bars","title":"Holiday Bergamot Cardamom Illipe-Mango Butter Bars","cat":"body-butter","time":"15 min active, plus 30 min to set","batch_size":"six 2 oz (55 g) bars, about 12 oz (340 g) total","shelf_life":"6-12 months at room temperature in a sealed tin or jar. Anhydrous, so no preservative is needed — just keep the bar dry between uses.","ingredients":[{"item":"Illipe butter, chopped","amount":"90 g (3.2 oz)"},{"item":"Mango butter","amount":"90 g (3.2 oz)"},{"item":"Sweet almond oil","amount":"50 g (1.8 oz)"},{"item":"Beeswax pellets","amount":"100 g (3.5 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Bergamot essential oil (bergapten-free / FCF, non-phototoxic type)","amount":"15 drops"},{"item":"Cardamom essential oil","amount":"6 drops"}],"method":["Melt the illipe butter, mango butter, almond oil and beeswax together in a double boiler until fully clear (10-12 min).","Remove from heat and stir in the vitamin E oil.","Let it cool for 3-4 min, just until it stops steaming, then stir in the bergamot and cardamom.","Pour into six silicone bar molds.","Refrigerate 20-30 min, or room temperature 2-3 hours, until fully solid.","Pop out of the molds and wrap for gifting."],"tips":["Bergamot and cardamom together smell closer to a spiced tea than a straightforward citrus — a distinctive option for a holiday bundle.","The illipe-mango blend gives a bar that's sturdy for shipping but still glides on smoothly, splitting the difference between the two butters' textures."],"safety_note":"Standard bergamot essential oil can cause skin damage in sunlight (phototoxicity). Use only a bergapten-free / FCF bergamot oil in this leave-on product, and avoid direct sun on treated skin for 12-18 hours if unsure of the type.","keywords":["body butter bar","holiday gift","bergamot","cardamom","illipe butter","mango butter","solid"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"whipped-kokum-butter-charcoal-eucalyptus","title":"Whipped Kokum Butter with Activated Charcoal & Eucalyptus","cat":"body-butter","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"6-12 months at room temperature, away from direct heat. This is a water-free (anhydrous) recipe, so it doesn't need a preservative.","ingredients":[{"item":"Kokum butter, chopped","amount":"115 g (4.1 oz)"},{"item":"Rosehip seed oil","amount":"55 g (1.9 oz)"},{"item":"Beeswax pellets","amount":"10 g (0.35 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp)"},{"item":"Food-grade activated charcoal powder","amount":"2 g (about 1/2 tsp) — for a soft grey tint only"},{"item":"Eucalyptus essential oil","amount":"20 drops"}],"method":["Melt the kokum butter, rosehip oil and beeswax together in a double boiler until clear (7-9 min).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 25-30 min, until firm at the edges.","Whip on medium-high for 6-8 min, until light and fluffy.","Add the eucalyptus essential oil in the last minute of whipping.","Sprinkle the activated charcoal over the top and fold it in gently by hand for a marbled look — don't whip it in or the color goes flat grey.","Spoon into a jar."],"tips":["Kokum butter's density holds the charcoal marbling in distinct streaks rather than letting it sink, so the jar still looks good weeks later.","This pairs well as a post-workout foot and leg butter: eucalyptus feels fresh, and the grey tone hides the kind of light staining other pale whips might show from socks or shoes."],"safety_note":null,"keywords":["kokum butter","body butter","activated charcoal","eucalyptus","whipped","marbled","detox feel"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"winter-spice-vanilla-cinnamon-cocoa-shea-whip","title":"Winter Spice Vanilla Cinnamon Cocoa-Shea Whip","cat":"body-butter","time":"20 min active, no cook time","batch_size":"about 12 oz (340 g)","shelf_life":"Up to 1 year at room temperature. No water, no preservative needed — this richer, double-butter blend is especially stable.","ingredients":[{"item":"Cocoa butter, chopped","amount":"100 g (3.5 oz)"},{"item":"Shea butter","amount":"90 g (3.2 oz)"},{"item":"Sunflower oil","amount":"60 g (2.1 oz)"},{"item":"Beeswax pellets","amount":"20 g (0.7 oz)"},{"item":"Vitamin E oil","amount":"4 g (about 3/4 tsp)"},{"item":"Vanilla fragrance oil","amount":"35 drops"},{"item":"Cinnamon essential oil","amount":"8 drops — keep this low, see safety note"}],"method":["Melt the cocoa butter, shea butter, sunflower oil and beeswax together in a double boiler until fully clear (10-13 min — this is the largest batch in the lineup, so give it extra time).","Remove from heat and stir in the vitamin E oil.","Cool at room temperature for 35-40 min, checking at 25 min since the double-butter base and larger volume firm up unevenly if rushed.","Whip on medium-high for 7-9 min, until light but noticeably denser than a single-butter whip — this size needs a stand mixer more than a hand mixer.","Add the vanilla and cinnamon in the last minute of whipping.","Spoon into a 12 oz jar, pressing gently to avoid large air pockets given the bigger batch."],"tips":["This is the biggest jar in the collection — a good 'family size' or refill option for whoever goes through body butter fastest.","Because it's a larger batch, cool it in a single wide bowl rather than a narrow one so the center doesn't stay warm while the edges are already firm."],"safety_note":"Cinnamon essential oil is a known skin sensitizer even in small amounts. This recipe uses a low, leave-on-safe dose across a 340 g batch — don't add more, and patch test before full-body use.","keywords":["cocoa butter","shea butter","body butter","winter","vanilla","cinnamon","whipped","large batch"],"pdf":"../../body-butter-recipes/96ldax70c8/body-butter-recipes.pdf"},{"slug":"lavender-fields-whipped-soap","title":"Lavender Fields Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (clear glycerin)","amount":"180 g (6.3 oz)"},{"item":"Liquid foaming bath base","amount":"30 g (1 oz)"},{"item":"Dried lavender buds, lightly crushed","amount":"8 g (1 tbsp)"},{"item":"Lavender essential oil","amount":"4 g (about 35-40 drops)"}],"method":["Cut the glycerin soap base into small cubes and melt in a double boiler or microwave in 20-second bursts, stirring between, until fully liquid.","Let it cool 2-3 min, just until it starts to thicken slightly at the edges.","Whip with a hand mixer on high for 3-5 min, until light, opaque and fluffy.","Add the foaming bath base and whip 1-2 min more to combine.","Fold in half the lavender buds and all the essential oil with a spatula (don't whip — you'd knock the air back out).","Spoon into jars right away and scatter the remaining lavender buds on top.","Leave uncovered overnight to fully set, then cap."],"tips":["This is a melt-and-pour recipe — it never touches raw lye, so none of the ventilation or protective gear that from-scratch soap making needs applies here.","If it deflates instead of staying fluffy, the base cooled too much before you started whipping — work a little faster next time."],"safety_note":null,"keywords":["whipped soap","lavender","melt and pour","floral","gift","relaxing","spring"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"citrus-sunrise-swirl-soap","title":"Citrus Sunrise Swirl Soap","cat":"whipped-soap","time":"30 min active, plus overnight to firm","batch_size":"about 10 oz (280 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (clear glycerin)","amount":"210 g (7.4 oz)"},{"item":"Liquid foaming bath base","amount":"40 g (1.4 oz)"},{"item":"Sweet orange essential oil","amount":"3 g (about 30 drops)"},{"item":"Grapefruit essential oil","amount":"2 g (about 20 drops)"},{"item":"Orange cosmetic mica","amount":"1 g (1/8 tsp)"},{"item":"Yellow cosmetic mica","amount":"1 g (1/8 tsp)"}],"method":["Cut the soap base into cubes and melt completely in a double boiler.","Pour the liquid base into two separate heatproof bowls, split roughly evenly.","Stir the orange mica into the first bowl and the yellow mica into the second, until each is evenly colored.","Let both bowls cool 2-3 min until they start to thicken at the edges.","Whip each bowl separately on high for 3-4 min until fluffy, then whip half the foaming bath base into each.","Fold the orange essential oil into the orange bowl and the grapefruit essential oil into the yellow bowl.","Spoon alternating dollops of each color into a jar, then run a skewer through once or twice to swirl — stop before the colors blend into one shade.","Leave uncovered overnight to fully set."],"tips":["One pass with the skewer gives bold ribbons; more passes blur the swirl toward a single muddy color — less is more.","Work on both colors at close to the same pace so neither one sets up stiffer than the other before you swirl them together."],"safety_note":null,"keywords":["whipped soap","swirl soap","citrus","orange","grapefruit","summer","melt and pour"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"toasted-coconut-whipped-soap","title":"Toasted Coconut Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (goat's milk)","amount":"185 g (6.5 oz)"},{"item":"Liquid foaming bath base","amount":"30 g (1 oz)"},{"item":"Finely shredded unsweetened coconut","amount":"7 g (1 tbsp)"},{"item":"Coconut fragrance oil","amount":"3 g (about 1/2 tsp)"}],"method":["Cut the goat's milk soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until pale, opaque and fluffy.","Add the foaming bath base and whip 1-2 min more.","Fold in the shredded coconut and fragrance oil by hand with a spatula.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["Toast the shredded coconut in a dry pan for 1-2 min before using it if you want flecks of golden color and a deeper aroma — let it cool fully before folding it in.","Goat's milk soap bases can scorch faster than clear glycerin — keep the heat low and stir often."],"safety_note":null,"keywords":["whipped soap","coconut","goat's milk soap","summer","beach","melt and pour","gourmand"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"gentle-oat-chamomile-baby-soap","title":"Gentle Oat & Chamomile Baby Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (fragrance-free, hypoallergenic)","amount":"190 g (6.7 oz)"},{"item":"Liquid foaming bath base (fragrance-free)","amount":"30 g (1 oz)"},{"item":"Colloidal (finely ground) oatmeal","amount":"8 g (2 tsp)"},{"item":"Dried chamomile flowers, crushed","amount":"5 g (1 tsp)"}],"method":["Cut the fragrance-free soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until light and fluffy.","Add the foaming bath base and whip 1-2 min more.","Fold in the colloidal oatmeal and crushed chamomile flowers by hand — no fragrance oil in this one, so it stays gentle for sensitive or young skin.","Spoon into small jars and leave uncovered overnight to fully set."],"tips":["This version skips fragrance oil on purpose — unscented is the safest starting point for a child's skin; add it later only if the family tolerates fragrance well.","Keep the chamomile pieces small so they don't feel scratchy on delicate skin."],"safety_note":null,"keywords":["whipped soap","baby soap","oatmeal","chamomile","fragrance-free","sensitive skin","kids"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"morning-espresso-scrub-soap","title":"Morning Espresso Scrub Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (goat's milk)","amount":"180 g (6.3 oz)"},{"item":"Liquid foaming bath base","amount":"30 g (1 oz)"},{"item":"Finely ground coffee","amount":"10 g (1 tbsp)"},{"item":"Vanilla fragrance oil","amount":"3 g (about 1/2 tsp)"}],"method":["Cut the soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until fluffy and pale.","Add the foaming bath base and whip 1-2 min more.","Fold in the ground coffee and vanilla fragrance oil by hand.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["Use a fine or medium coffee grind, not whole beans or a coarse grind — coarse grounds can feel scratchy rather than gently exfoliating.","Coffee grounds settle if the base is too thin when you fold them in — wait until the whipped soap holds stiff peaks first."],"safety_note":null,"keywords":["whipped soap","coffee scrub","espresso","exfoliating","goat's milk soap","everyday"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"rose-garden-whipped-soap","title":"Rose Garden Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (shea butter)","amount":"185 g (6.5 oz)"},{"item":"Liquid foaming bath base","amount":"28 g (1 oz)"},{"item":"Dried rose petals, crushed","amount":"8 g (2 tbsp)"},{"item":"Rose geranium essential oil","amount":"4 g (about 35 drops)"}],"method":["Cut the shea butter soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until fluffy.","Add the foaming bath base and whip 1-2 min more.","Fold in half the rose petals and all the essential oil.","Spoon into jars and scatter the rest of the rose petals on top for a finished look.","Leave uncovered overnight to fully set."],"tips":["True rose essential oil is very expensive — rose geranium gives a similar floral note at a fraction of the cost and works well here.","Shea butter soap base can smell faintly nutty on its own; a slightly stronger fragrance dose than usual helps it come through."],"safety_note":null,"keywords":["whipped soap","rose","shea butter soap","floral","gift","valentine's day","romantic"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"eucalyptus-spa-whipped-soap","title":"Eucalyptus Spa Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (clear glycerin)","amount":"182 g (6.4 oz)"},{"item":"Liquid foaming bath base","amount":"30 g (1 oz)"},{"item":"Dried eucalyptus or mint leaf bits","amount":"6 g (1 tbsp)"},{"item":"Eucalyptus essential oil","amount":"2.5 g (about 25 drops)"},{"item":"Peppermint essential oil","amount":"1.5 g (about 15 drops)"}],"method":["Cut the soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until fluffy and glossy.","Add the foaming bath base and whip 1-2 min more.","Fold in the dried leaf bits and both essential oils by hand.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["This combination works well next to the shower where steam can lift the aroma — a little goes a long way.","Crush the dried leaves between your fingers before adding them so they distribute evenly instead of clumping."],"safety_note":null,"keywords":["whipped soap","eucalyptus","peppermint","spa","self-care","invigorating","melt and pour"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"vanilla-bean-whipped-soap","title":"Vanilla Bean Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (cocoa butter)","amount":"186 g (6.6 oz)"},{"item":"Liquid foaming bath base","amount":"28 g (1 oz)"},{"item":"Ground vanilla bean pod (vanilla bean specks)","amount":"3 g (1/2 tsp)"},{"item":"Vanilla fragrance oil","amount":"4 g (about 1/2 tsp + a little)"}],"method":["Cut the cocoa butter soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until pale and fluffy.","Add the foaming bath base and whip 1-2 min more.","Fold in the vanilla bean specks and fragrance oil by hand.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["Real vanilla bean specks can darken slightly over weeks in a light-colored soap — that's cosmetic, not a sign of spoilage.","Cocoa butter soap base has a natural chocolate-cream scent that pairs beautifully under vanilla without fighting it."],"safety_note":null,"keywords":["whipped soap","vanilla","cocoa butter soap","gourmand","winter","gift","melt and pour"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"pumpkin-spice-whipped-soap","title":"Pumpkin Spice Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (goat's milk)","amount":"185 g (6.5 oz)"},{"item":"Liquid foaming bath base","amount":"28 g (1 oz)"},{"item":"Ground cinnamon","amount":"2 g (1/2 tsp)"},{"item":"Ground ginger","amount":"1 g (1/4 tsp)"},{"item":"Ground nutmeg","amount":"1 g (1/4 tsp)"},{"item":"Orange cosmetic mica (color only, no pumpkin puree used)","amount":"1 g (1/8 tsp)"},{"item":"Pumpkin-spice-type fragrance oil","amount":"4 g (about 1/2 tsp)"}],"method":["Cut the soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until fluffy.","Add the foaming bath base and whip 1-2 min more.","Fold in the spices, mica and fragrance oil by hand, until the color is even.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["This recipe uses spices and fragrance for a pumpkin-spice feel only — no actual pumpkin or food ingredient goes in, which keeps it stable and mold-free.","Ground spices can feel gritty in larger amounts — the quantities here are for scent and flecks of color, not exfoliation."],"safety_note":null,"keywords":["whipped soap","pumpkin spice","fall","autumn","cinnamon","goat's milk soap","seasonal"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"charcoal-detox-whipped-soap","title":"Charcoal Detox Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (white glycerin)","amount":"185 g (6.5 oz)"},{"item":"Liquid foaming bath base","amount":"28 g (1 oz)"},{"item":"Activated charcoal powder","amount":"2 g (1/2 tsp)"},{"item":"Kaolin clay","amount":"5 g (1 tsp)"},{"item":"Tea tree essential oil","amount":"2 g (about 20 drops)"},{"item":"Peppermint essential oil","amount":"1 g (about 10 drops)"}],"method":["Cut the soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until fluffy.","Add the foaming bath base and whip 1-2 min more.","Fold in the activated charcoal and kaolin clay a little at a time until the gray color is even — charcoal is potent and goes further than it looks.","Fold in both essential oils.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["Add charcoal gradually — it's easy to oversaturate the color, and it can stain light-colored towels if used in excess.","Wipe your work surface right after you're done; charcoal powder tracks easily while it's still dry."],"safety_note":null,"keywords":["whipped soap","activated charcoal","clay soap","tea tree","men's soap","everyday","detox"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"calendula-clay-whipped-soap","title":"Calendula Clay Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (aloe vera)","amount":"185 g (6.5 oz)"},{"item":"Liquid foaming bath base","amount":"28 g (1 oz)"},{"item":"Dried calendula petals","amount":"5 g (1 tbsp)"},{"item":"French green clay","amount":"5 g (1 tsp)"},{"item":"Lavender essential oil (optional, light amount)","amount":"2 g (about 20 drops)"}],"method":["Cut the aloe vera soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until fluffy.","Add the foaming bath base and whip 1-2 min more.","Fold in the calendula petals and french green clay until evenly colored pale green.","Fold in the lavender essential oil if using, or leave unscented for the most sensitive skin.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["Calendula is one of the gentlest dried flowers to use on reactive skin — this combination is a good one to offer fragrance-free.","French green clay can feel drying in high amounts; this recipe keeps it light, mainly for color and a soft mineral feel."],"safety_note":null,"keywords":["whipped soap","calendula","clay soap","aloe vera soap","sensitive skin","gentle","gift"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"lemon-poppy-seed-whipped-soap","title":"Lemon Poppy Seed Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (clear glycerin)","amount":"187 g (6.6 oz)"},{"item":"Liquid foaming bath base","amount":"28 g (1 oz)"},{"item":"Poppy seeds","amount":"6 g (1 tbsp)"},{"item":"Lemon essential oil","amount":"4 g (about 40 drops)"}],"method":["Cut the soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until fluffy and glossy.","Add the foaming bath base and whip 1-2 min more.","Fold in the poppy seeds and lemon essential oil by hand.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["Poppy seeds stay put nicely in clear glycerin bases because the whipped texture thickens fast — fold them in as soon as the soap holds peaks.","Citrus essential oils fade faster than floral ones — use this one within its shelf life for the brightest scent."],"safety_note":null,"keywords":["whipped soap","lemon","poppy seed","citrus","exfoliating","summer","melt and pour"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"loofah-scrub-whipped-soap","title":"Loofah Scrub Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (white glycerin)","amount":"188 g (6.6 oz)"},{"item":"Liquid foaming bath base","amount":"28 g (1 oz)"},{"item":"Dried loofah, cut into small pieces","amount":"7 g (2 tbsp)"},{"item":"Rosemary essential oil (optional)","amount":"2 g (about 20 drops)"}],"method":["Cut the soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until fluffy.","Add the foaming bath base and whip 1-2 min more.","Fold in the chopped loofah pieces and rosemary essential oil, if using.","Spoon into jars, pressing lightly so the loofah pieces stay distributed instead of sinking.","Leave uncovered overnight to fully set."],"tips":["Cut the loofah pieces small (pea-sized or smaller) — large chunks feel rough rather than gently exfoliating.","This one is nice left unscented too, since the loofah itself does the work; the rosemary oil is optional."],"safety_note":null,"keywords":["whipped soap","loofah","exfoliating scrub","white glycerin soap","everyday","melt and pour"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"hot-cocoa-whipped-soap","title":"Hot Cocoa Whipped Soap","cat":"whipped-soap","time":"35 min active, plus overnight to firm","batch_size":"about 10 oz (280 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (cocoa butter)","amount":"220 g (7.8 oz)"},{"item":"Liquid foaming bath base","amount":"40 g (1.4 oz)"},{"item":"Cocoa powder (bottom layer only)","amount":"8 g (1 tbsp)"},{"item":"Vanilla fragrance oil","amount":"4 g (about 1/2 tsp)"},{"item":"Cocoa or chocolate fragrance oil","amount":"4 g (about 1/2 tsp)"}],"method":["Cut the soap base into cubes and melt completely in a double boiler.","Pour about half the liquid base into a second bowl.","Stir the cocoa powder and cocoa fragrance oil into one bowl; this is the brown 'cocoa' layer.","Let both bowls cool 2-3 min until they start to thicken, then whip each separately on high for 3-4 min until fluffy.","Whip half the foaming bath base into each bowl.","Spoon the brown cocoa whip into jars first as the bottom layer and smooth the top; let it firm for 15-20 min until set to the touch.","Stir the vanilla fragrance oil into the remaining white whipped base, then spoon it on top as the 'marshmallow' layer.","Leave uncovered overnight to fully set."],"tips":["Letting the bottom layer firm up before adding the top is what keeps the two layers distinct instead of blending into one color.","If the top layer sinks into the bottom, the first layer wasn't set enough yet — give it a few more minutes next time."],"safety_note":null,"keywords":["whipped soap","layered soap","cocoa","chocolate","vanilla","winter","gourmand"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"himalayan-pink-salt-whipped-soap","title":"Himalayan Pink Salt Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (shea butter)","amount":"187 g (6.6 oz)"},{"item":"Liquid foaming bath base","amount":"28 g (1 oz)"},{"item":"Finely ground pink Himalayan salt","amount":"7 g (1 tbsp)"},{"item":"Geranium essential oil","amount":"3 g (about 30 drops)"}],"method":["Cut the shea butter soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until fluffy.","Add the foaming bath base and whip 1-2 min more.","Fold in the finely ground salt and geranium essential oil by hand.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["Grind the salt finer than table salt — coarse crystals in a whipped soap can feel sharp rather than smooth.","Use this one as a light polish, not a heavy-duty scrub; it's meant to be gentle enough for daily use."],"safety_note":null,"keywords":["whipped soap","himalayan salt","shea butter soap","geranium","spa","gift","gentle scrub"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"rosemary-mint-whipped-soap","title":"Rosemary Mint Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (olive oil, Castile-style)","amount":"185 g (6.5 oz)"},{"item":"Liquid foaming bath base","amount":"28 g (1 oz)"},{"item":"Dried rosemary, crumbled","amount":"5 g (1 tbsp)"},{"item":"Rosemary essential oil","amount":"2 g (about 20 drops)"},{"item":"Peppermint essential oil","amount":"2 g (about 20 drops)"}],"method":["Cut the Castile-style soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until fluffy — olive oil bases can take slightly longer to turn light than glycerin.","Add the foaming bath base and whip 1-2 min more.","Fold in the dried rosemary and both essential oils.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["Crumble the rosemary between your fingers so you get soft flecks, not stiff stems that poke through the surface.","This herbal pairing works well as a unisex bar — a good one to offer alongside the more floral scents."],"safety_note":null,"keywords":["whipped soap","rosemary","mint","castile soap","herbal","unisex","men's soap"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"earl-grey-bergamot-whipped-soap","title":"Earl Grey Bergamot Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (clear glycerin)","amount":"187 g (6.6 oz)"},{"item":"Liquid foaming bath base","amount":"28 g (1 oz)"},{"item":"Finely ground black tea leaves (from a tea bag)","amount":"4 g (1 tsp)"},{"item":"Bergamot essential oil","amount":"4 g (about 40 drops)"}],"method":["Cut the soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until fluffy and glossy.","Add the foaming bath base and whip 1-2 min more.","Fold in the ground tea leaves and bergamot essential oil.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["Use the loose tea from inside a tea bag rather than steeped leaves — dry tea distributes much more evenly than wet.","Bergamot essential oil can be photosensitizing on skin in sunlight in leave-on products, but since this soap is rinsed off right away that isn't a concern here."],"safety_note":null,"keywords":["whipped soap","earl grey","bergamot","black tea","glycerin soap","gift","unique"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"cucumber-melon-swirl-soap","title":"Cucumber Melon Swirl Soap","cat":"whipped-soap","time":"30 min active, plus overnight to firm","batch_size":"about 10 oz (280 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (aloe vera)","amount":"215 g (7.6 oz)"},{"item":"Liquid foaming bath base","amount":"40 g (1.4 oz)"},{"item":"Green cosmetic mica or a pinch of spirulina powder (for the green half)","amount":"1 g (1/8 tsp)"},{"item":"Cucumber melon fragrance oil","amount":"5 g (about 1 tsp)"}],"method":["Cut the aloe vera soap base into cubes and melt completely in a double boiler.","Pour the liquid base into two bowls, split roughly evenly.","Stir the green mica (or spirulina) into one bowl only; leave the other bowl clear white.","Let both bowls cool 2-3 min until they start to thicken, then whip each separately on high for 3-4 min until fluffy.","Whip half the foaming bath base into each bowl, then fold half the fragrance oil into each.","Spoon alternating dollops of each color into a jar and swirl once with a skewer.","Leave uncovered overnight to fully set."],"tips":["Spirulina gives a softer, more natural green than mica, but use it sparingly — a little tints a lot.","This fragrance is a crowd-pleaser for summer gift sets; pair it with the Citrus Sunrise Swirl Soap for a matching set."],"safety_note":null,"keywords":["whipped soap","cucumber melon","swirl soap","aloe vera soap","summer","fresh scent"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"gingerbread-whipped-soap","title":"Gingerbread Whipped Soap","cat":"whipped-soap","time":"35 min active, plus overnight to firm","batch_size":"about 10 oz (280 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (goat's milk)","amount":"216 g (7.6 oz)"},{"item":"Liquid foaming bath base","amount":"40 g (1.4 oz)"},{"item":"Ground cinnamon, clove and ginger blend (bottom layer only)","amount":"4 g (1 tsp)"},{"item":"Cocoa powder, for color (bottom layer only)","amount":"4 g (1 tsp)"},{"item":"Gingerbread-type fragrance oil (or a cinnamon/clove/ginger essential oil blend)","amount":"6 g (about 1.25 tsp)"}],"method":["Cut the soap base into cubes and melt completely in a double boiler.","Pour the liquid base into two bowls, split roughly evenly.","Stir the spice blend and cocoa powder into one bowl only, for the brown 'gingerbread' layer.","Let both bowls cool 2-3 min until they start to thicken, then whip each separately on high for 3-4 min until fluffy.","Whip half the foaming bath base into each bowl, then fold half the fragrance into each.","Spoon the brown layer into jars first, smooth the top, and let it firm for 15-20 min until set to the touch.","Spoon the plain white layer on top.","Leave uncovered overnight to fully set."],"tips":["Let the spiced bottom layer firm fully before adding the white top — this keeps the two-tone look crisp.","Ground spices can darken over time in a light base; that's cosmetic and expected, not a sign the soap has gone bad."],"safety_note":null,"keywords":["whipped soap","gingerbread","layered soap","winter","holiday","spiced","goat's milk soap"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"jasmine-petal-whipped-soap","title":"Jasmine Petal Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (clear glycerin)","amount":"182 g (6.4 oz)"},{"item":"Liquid foaming bath base","amount":"28 g (1 oz)"},{"item":"Sweet almond oil (adds a touch of silkiness)","amount":"5 g (1 tsp)"},{"item":"Dried jasmine tea flowers, crushed","amount":"5 g (1 tbsp)"},{"item":"Jasmine fragrance oil","amount":"5 g (about 1 tsp)"}],"method":["Cut the soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until fluffy.","Add the foaming bath base and whip 1-2 min more.","Whip in the sweet almond oil for the last 30 seconds.","Fold in the crushed jasmine flowers and fragrance oil by hand.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["Dried jasmine tea flowers (sold for brewing tea) are an easy, food-grade-adjacent source of real jasmine petals for crafting.","A small amount of almond oil whipped in gives the lather a slightly silkier feel without making the bar too soft to hold its shape."],"safety_note":null,"keywords":["whipped soap","jasmine","floral","glycerin soap","wedding favors","gift","elegant"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"honeysuckle-whipped-soap","title":"Honeysuckle Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (shea butter)","amount":"187 g (6.6 oz)"},{"item":"Liquid foaming bath base","amount":"28 g (1 oz)"},{"item":"Dried calendula petals (for a soft yellow fleck)","amount":"4 g (1 tsp)"},{"item":"Honeysuckle-type fragrance oil","amount":"6 g (about 1.25 tsp)"}],"method":["Cut the shea butter soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until fluffy.","Add the foaming bath base and whip 1-2 min more.","Fold in the calendula petals and fragrance oil by hand.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["True honeysuckle essential oil isn't commercially extracted — a skin-safe fragrance oil is the standard, reliable way to get this scent.","This one is a nice everyday spring scent that isn't as heavy as rose or jasmine."],"safety_note":null,"keywords":["whipped soap","honeysuckle","floral","shea butter soap","spring","light scent","everyday"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"lavender-clay-marbled-soap","title":"Lavender Clay Marbled Soap","cat":"whipped-soap","time":"30 min active, plus overnight to firm","batch_size":"about 10 oz (280 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (white glycerin)","amount":"212 g (7.5 oz)"},{"item":"Liquid foaming bath base","amount":"40 g (1.4 oz)"},{"item":"Rhassoul clay (for the purple-gray half)","amount":"5 g (1 tsp)"},{"item":"Purple cosmetic mica (for the purple-gray half)","amount":"1 g (1/8 tsp)"},{"item":"Dried lavender buds","amount":"6 g (1 tbsp)"},{"item":"Lavender essential oil","amount":"6 g (about 55 drops)"}],"method":["Cut the soap base into cubes and melt completely in a double boiler.","Pour the liquid base into two bowls, split roughly evenly.","Stir the rhassoul clay and purple mica into one bowl only, until it turns an even lavender-gray.","Let both bowls cool 2-3 min until they start to thicken, then whip each separately on high for 3-4 min until fluffy.","Whip half the foaming bath base into each bowl, then fold half the lavender buds and essential oil into each.","Spoon small, random dollops of each color into a jar, alternating as you go, then drag a skewer through in a few loose figure-eight motions for a soft, feathered marble (don't aim for neat stripes).","Leave uncovered overnight to fully set."],"tips":["A marbled look uses more, lighter skewer passes than a bold swirl — the goal is a soft blend at the edges, not sharp ribbons.","Rhassoul clay can thicken the mixture slightly faster than plain soap — whip that bowl just a touch less than the plain one so both are ready to spoon at the same time."],"safety_note":null,"keywords":["whipped soap","marbled soap","lavender","clay soap","spa","purple soap","gift"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"matcha-green-tea-whipped-soap","title":"Matcha Green Tea Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (white glycerin)","amount":"188 g (6.6 oz)"},{"item":"Liquid foaming bath base","amount":"28 g (1 oz)"},{"item":"Matcha (green tea) powder","amount":"4 g (1 tsp)"},{"item":"Light green tea or herbal-type fragrance oil","amount":"5 g (about 1 tsp)"}],"method":["Cut the soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until fluffy.","Add the foaming bath base and whip 1-2 min more.","Fold in the matcha powder a little at a time until the green color is even, then fold in the fragrance oil.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["Sift the matcha before adding it if it's clumpy — this keeps the green from streaking unevenly through the soap.","Matcha's color mellows to a softer sage tone after a few weeks; that fading is normal and not a quality issue."],"safety_note":null,"keywords":["whipped soap","matcha","green tea","glycerin soap","earthy","everyday","detox"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"golden-turmeric-whipped-soap","title":"Golden Turmeric Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (honey)","amount":"190 g (6.7 oz)"},{"item":"Liquid foaming bath base","amount":"28 g (1 oz)"},{"item":"Ground turmeric","amount":"1.5 g (1/4 tsp) — a little goes a long way"},{"item":"Honey-and-spice-type fragrance oil","amount":"5.5 g (about 1 tsp)"}],"method":["Cut the honey soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until fluffy.","Add the foaming bath base and whip 1-2 min more.","Fold in the turmeric a pinch at a time, checking the color as you go, then fold in the fragrance oil.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["Turmeric stains light-colored washcloths and bathtubs — use a dark washcloth or rinse the tub right after use.","Start with less turmeric than you think you need; you can always fold in a bit more, but you can't take it back out."],"safety_note":null,"keywords":["whipped soap","turmeric","honey soap","golden soap","spice","gift","warm tones"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"champagne-rose-swirl-soap","title":"Champagne Rose Swirl Soap","cat":"whipped-soap","time":"30 min active, plus overnight to firm","batch_size":"about 10 oz (280 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (clear glycerin)","amount":"216 g (7.6 oz)"},{"item":"Liquid foaming bath base","amount":"40 g (1.4 oz)"},{"item":"Cosmetic shimmer mica, champagne or pink gold","amount":"1.5 g (1/4 tsp)"},{"item":"Dried rose petals, crushed","amount":"5 g (1 tbsp)"},{"item":"Rose fragrance oil","amount":"5.5 g (about 1 tsp)"}],"method":["Cut the soap base into cubes and melt completely in a double boiler.","Pour the liquid base into two bowls, split roughly evenly.","Stir the shimmer mica into one bowl only, for the pale pink-gold half; leave the other clear white.","Let both bowls cool 2-3 min until they start to thicken, then whip each separately on high for 3-4 min until fluffy.","Whip half the foaming bath base into each bowl, then fold half the rose petals and fragrance oil into each.","Spoon alternating dollops of each color into a jar and swirl once with a skewer.","Leave uncovered overnight to fully set."],"tips":["Cosmetic-grade mica only — regular craft or art glitter is not made for skin contact and should never go in a soap recipe.","This one makes an elegant wedding favor; pour into small 2 oz (56 g) jars instead of one large one if you're gifting individually."],"safety_note":null,"keywords":["whipped soap","swirl soap","rose","shimmer","wedding favors","gift","elegant"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"spearmint-confetti-soap","title":"Spearmint Confetti Soap","cat":"whipped-soap","time":"25 min active (plus time to prep confetti ahead), plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (clear glycerin)","amount":"190 g (6.7 oz)"},{"item":"Liquid foaming bath base","amount":"28 g (1 oz)"},{"item":"Soap confetti (small cut pieces of leftover colored melt-and-pour soap, cooled and firm)","amount":"12 g (about 2 tbsp)"},{"item":"Spearmint essential oil","amount":"3 g (about 30 drops)"}],"method":["If you don't already have soap confetti on hand, melt and pour a small amount of colored scrap soap into a thin layer, let it set fully, then dice it into small cubes.","Cut the main soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until fluffy.","Add the foaming bath base and whip 1-2 min more.","Fold in the spearmint essential oil, then gently fold in the soap confetti pieces last, just until distributed.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["This is a great way to use up small leftover pieces from other batches instead of throwing them away.","Fold the confetti in last and gently — over-mixing will start to melt the small pieces into the whipped base and blur the color pop."],"safety_note":null,"keywords":["whipped soap","confetti soap","spearmint","glycerin soap","upcycled","fun","spa"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"cranberry-orange-holiday-soap","title":"Cranberry Orange Holiday Soap","cat":"whipped-soap","time":"35 min active, plus overnight to firm","batch_size":"about 10 oz (280 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (white glycerin)","amount":"216 g (7.6 oz)"},{"item":"Liquid foaming bath base","amount":"40 g (1.4 oz)"},{"item":"Dried cranberries, finely chopped (bottom layer only)","amount":"6 g (1 tbsp)"},{"item":"Dried orange zest powder","amount":"3 g (1 tsp)"},{"item":"Red cosmetic mica (bottom layer only)","amount":"1 g (1/8 tsp)"},{"item":"Sweet orange essential oil","amount":"5 g (about 50 drops)"}],"method":["Cut the soap base into cubes and melt completely in a double boiler.","Pour the liquid base into two bowls, split roughly evenly.","Stir the chopped cranberries and red mica into one bowl only, for the red bottom layer.","Let both bowls cool 2-3 min until they start to thicken, then whip each separately on high for 3-4 min until fluffy.","Whip half the foaming bath base into each bowl, then fold the orange zest and half the orange essential oil into each.","Spoon the red cranberry layer into jars first, smooth the top, and let it firm for 15-20 min until set to the touch.","Spoon the plain white layer on top.","Leave uncovered overnight to fully set."],"tips":["Chop the dried cranberries small and make sure they're fully dehydrated (not the chewy, moist kind) so they don't introduce extra moisture into the soap.","This layered red-and-white look makes a nice holiday gift set alongside the Gingerbread Whipped Soap."],"safety_note":null,"keywords":["whipped soap","cranberry","orange","layered soap","holiday","winter","gift set"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"sandalwood-cedarwood-whipped-soap","title":"Sandalwood Cedarwood Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (shea butter)","amount":"190 g (6.7 oz)"},{"item":"Liquid foaming bath base","amount":"30 g (1 oz)"},{"item":"Sandalwood fragrance oil","amount":"3 g (about 1/2 tsp)"},{"item":"Cedarwood essential oil","amount":"2 g (about 20 drops)"}],"method":["Cut the shea butter soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until fluffy.","Add the foaming bath base and whip 1-2 min more.","Fold in both fragrances by hand.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["This one has no exfoliant inclusion by design — a smooth whipped bar with a woodsy scent reads as more unisex and gift-ready.","If you want a deeper color, fold in a pinch of cocoa powder — a little goes a long way in a light base."],"safety_note":null,"keywords":["whipped soap","sandalwood","cedarwood","woodsy","men's soap","unisex","shea butter soap"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"pink-grapefruit-whipped-soap","title":"Pink Grapefruit Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (clear glycerin)","amount":"187 g (6.6 oz)"},{"item":"Liquid foaming bath base","amount":"28 g (1 oz)"},{"item":"Poppy seeds","amount":"6 g (1 tbsp)"},{"item":"Pink grapefruit essential oil","amount":"4 g (about 40 drops)"}],"method":["Cut the soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until fluffy and glossy.","Add the foaming bath base and whip 1-2 min more.","Fold in the poppy seeds and grapefruit essential oil.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["Grapefruit essential oil fades a little faster than other citrus oils — store this one away from direct sunlight to keep the scent fresh longer.","Add a tiny drop of pink mica if you want visual color to match the name; it's optional and purely cosmetic."],"safety_note":null,"keywords":["whipped soap","grapefruit","poppy seed","citrus","summer","glycerin soap","bright scent"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"lily-blossom-pastel-swirl-soap","title":"Lily Blossom Pastel Swirl Soap","cat":"whipped-soap","time":"30 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (clear glycerin)","amount":"180 g (6.3 oz)"},{"item":"Liquid foaming bath base","amount":"35 g (1.2 oz)"},{"item":"Pink cosmetic mica (for one half)","amount":"0.5 g (a small pinch)"},{"item":"Lily-type floral fragrance oil","amount":"5 g (about 1 tsp)"}],"method":["Cut the soap base into cubes and melt completely in a double boiler.","Pour the liquid base into two bowls, split roughly evenly.","Stir the pink mica into one bowl only, for a soft pastel pink; leave the other clear white.","Let both bowls cool 2-3 min until they start to thicken, then whip each separately on high for 3-4 min until fluffy.","Whip half the foaming bath base into each bowl, then fold half the fragrance oil into each.","Spoon alternating small dollops of each color into a jar and swirl once with a skewer for a soft pastel marble.","Leave uncovered overnight to fully set."],"tips":["Keep the pink very pale — a tiny pinch of mica goes further than you'd expect in a white base.","This pastel look is popular for baby showers and spring gifts; pair it with a floral or very light fragrance."],"safety_note":null,"keywords":["whipped soap","swirl soap","floral","pastel","spring","gift","glycerin soap"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"honey-almond-whipped-soap","title":"Honey Almond Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (honey)","amount":"187 g (6.6 oz)"},{"item":"Liquid foaming bath base","amount":"28 g (1 oz)"},{"item":"Finely ground almond meal","amount":"6 g (1 tbsp)"},{"item":"Almond and vanilla fragrance oil","amount":"4 g (about 1/2 tsp)"}],"method":["Cut the honey soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until fluffy.","Add the foaming bath base and whip 1-2 min more.","Fold in the ground almond meal and fragrance oil by hand.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["Grind the almond meal fine — coarse chunks of nut meal can feel abrasive rather than gently polishing.","Note for gifting: let recipients with tree nut allergies know this one contains almond meal, even though it's rinsed off rather than eaten."],"safety_note":null,"keywords":["whipped soap","honey","almond","gourmand","honey soap","gift","exfoliating"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"chocolate-mint-swirl-soap","title":"Chocolate Mint Swirl Soap","cat":"whipped-soap","time":"30 min active, plus overnight to firm","batch_size":"about 10 oz (280 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (cocoa butter)","amount":"212 g (7.5 oz)"},{"item":"Liquid foaming bath base","amount":"40 g (1.4 oz)"},{"item":"Cocoa powder (for the brown half)","amount":"6 g (1 tbsp)"},{"item":"Peppermint essential oil","amount":"4 g (about 40 drops)"},{"item":"Cocoa or chocolate fragrance oil","amount":"4 g (about 1/2 tsp)"}],"method":["Cut the soap base into cubes and melt completely in a double boiler.","Pour the liquid base into two bowls, split roughly evenly.","Stir the cocoa powder into one bowl only, for the brown half; leave the other bowl white.","Let both bowls cool 2-3 min until they start to thicken, then whip each separately on high for 3-4 min until fluffy.","Whip half the foaming bath base into each bowl, then fold the cocoa fragrance into the brown bowl and the peppermint oil into the white bowl.","Spoon alternating dollops of each color into a jar and swirl once with a skewer.","Leave uncovered overnight to fully set."],"tips":["Keeping the two fragrances in separate halves until the last fold-in step keeps the chocolate and mint notes distinct instead of muddy.","This one is popular around the winter holidays — package it with a ribbon in brown and white twine."],"safety_note":null,"keywords":["whipped soap","chocolate mint","swirl soap","cocoa butter soap","winter","gourmand"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"coffee-cardamom-scrub-soap","title":"Coffee Cardamom Scrub Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (goat's milk)","amount":"185 g (6.5 oz)"},{"item":"Liquid foaming bath base","amount":"28 g (1 oz)"},{"item":"Finely ground coffee","amount":"8 g (1 tbsp)"},{"item":"Ground cardamom","amount":"1 g (1/4 tsp)"},{"item":"Vanilla fragrance oil (optional, light amount)","amount":"3 g (about 1/2 tsp)"}],"method":["Cut the soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until fluffy.","Add the foaming bath base and whip 1-2 min more.","Fold in the ground coffee, cardamom and vanilla fragrance oil, if using.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["Cardamom is a warm, slightly citrusy spice that pairs well with coffee without pushing the scent toward dessert — use it sparingly, it's potent.","This makes a good fall scrub bar alongside a classic Pumpkin Spice or Gingerbread soap."],"safety_note":null,"keywords":["whipped soap","coffee","cardamom","scrub soap","fall","goat's milk soap","everyday"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"fresh-linen-whipped-soap","title":"Fresh Linen Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (fragrance-free, hypoallergenic)","amount":"192 g (6.8 oz)"},{"item":"Liquid foaming bath base (fragrance-free)","amount":"28 g (1 oz)"},{"item":"Clean cotton / fresh linen-type cosmetic fragrance oil","amount":"5 g (about 1 tsp)"}],"method":["Cut the fragrance-free soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until light and fluffy.","Add the foaming bath base and whip 1-2 min more.","Fold in the fragrance oil by hand.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["No inclusions or color in this one on purpose — it's meant as a clean, simple everyday bar for people who find floral or spiced scents overwhelming.","If a buyer needs it completely scent-free too, simply leave out the fragrance oil; the base itself has almost no smell."],"safety_note":null,"keywords":["whipped soap","fresh linen","clean scent","fragrance-free base","everyday","unisex","simple"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"pine-forest-whipped-soap","title":"Pine Forest Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (hemp seed oil)","amount":"188 g (6.6 oz)"},{"item":"Liquid foaming bath base","amount":"28 g (1 oz)"},{"item":"Dried rosemary, crumbled (optional, for texture)","amount":"4 g (1 tsp)"},{"item":"Pine or fir needle essential oil","amount":"5 g (about 1 tsp)"}],"method":["Cut the hemp seed oil soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until fluffy — hemp seed oil bases often whip to a slightly green-tinted white.","Add the foaming bath base and whip 1-2 min more.","Fold in the rosemary, if using, and the pine essential oil.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["This scent is a good seasonal rotation for a winter gift set alongside the Gingerbread and Cranberry Orange soaps.","Hemp seed oil soap base has a naturally earthy undertone that works with woodsy and herbal scents better than with light florals."],"safety_note":null,"keywords":["whipped soap","pine","forest","hemp seed oil soap","winter","men's soap","woodsy"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"strawberry-cream-layered-soap","title":"Strawberry Cream Layered Soap","cat":"whipped-soap","time":"35 min active, plus overnight to firm","batch_size":"about 10 oz (280 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (cocoa butter)","amount":"216 g (7.6 oz)"},{"item":"Liquid foaming bath base","amount":"40 g (1.4 oz)"},{"item":"Pink cosmetic mica (bottom layer only)","amount":"1 g (1/8 tsp)"},{"item":"Strawberry fragrance oil","amount":"6 g (about 1.25 tsp)"}],"method":["Cut the soap base into cubes and melt completely in a double boiler.","Pour the liquid base into two bowls, split roughly evenly.","Stir the pink mica into one bowl only, for the pink bottom layer.","Let both bowls cool 2-3 min until they start to thicken, then whip each separately on high for 3-4 min until fluffy.","Whip half the foaming bath base into each bowl, then fold half the fragrance oil into each.","Spoon the pink layer into jars first, smooth the top, and let it firm for 15-20 min until set to the touch.","Spoon the white 'cream' layer on top.","Leave uncovered overnight to fully set."],"tips":["This dessert-style look sells well as a gift set — a glass jar shows off the two layers clearly.","If the layers blend at the seam instead of staying crisp, the bottom layer needed more firming time before you added the top."],"safety_note":null,"keywords":["whipped soap","strawberry","layered soap","cocoa butter soap","gourmand","gift","dessert-style"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"kids-bubblegum-swirl-soap","title":"Kids' Bubblegum Swirl Soap","cat":"whipped-soap","time":"30 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (fragrance-free, hypoallergenic)","amount":"182 g (6.4 oz)"},{"item":"Liquid foaming bath base (fragrance-free)","amount":"35 g (1.2 oz)"},{"item":"Pink cosmetic mica (for one half)","amount":"0.5 g (a small pinch)"},{"item":"Blue cosmetic mica (for the other half)","amount":"0.5 g (a small pinch)"},{"item":"Bubblegum-type cosmetic fragrance oil, formulated for children's products","amount":"4 g (about 1/2 tsp), used at a lower-than-adult rate"}],"method":["Cut the soap base into cubes and melt completely in a double boiler.","Pour the liquid base into two bowls, split roughly evenly.","Stir the pink mica into one bowl and the blue mica into the other.","Let both bowls cool 2-3 min until they start to thicken, then whip each separately on high for 3-4 min until fluffy.","Whip half the foaming bath base into each bowl, then fold half the fragrance oil into each.","Spoon alternating dollops of pink and blue into a jar and swirl once with a skewer.","Leave uncovered overnight to fully set."],"tips":["Use a fragrance oil specifically formulated and rated for children's bath products, at the lower end of its suggested rate — kids' skin is more reactive than adult skin.","Patch test any new fragrance on a small area first, and skip fragrance entirely for a child with known sensitivities — the plain swirl still looks fun with color alone."],"safety_note":null,"keywords":["whipped soap","kids soap","bubblegum","swirl soap","fun soap","birthday","fragrance-free base"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"oatmeal-milk-whipped-soap","title":"Oatmeal Milk Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (goat's milk)","amount":"188 g (6.6 oz)"},{"item":"Liquid foaming bath base","amount":"28 g (1 oz)"},{"item":"Finely ground oats","amount":"6 g (1 tbsp)"},{"item":"Light vanilla fragrance oil","amount":"3 g (about 1/2 tsp)"}],"method":["Cut the goat's milk soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until pale and fluffy.","Add the foaming bath base and whip 1-2 min more.","Fold in the finely ground oats and vanilla fragrance oil.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["This is a gentler, milder cousin to a dessert-style oat soap — a good everyday bar for anyone with slightly reactive skin who still wants light exfoliation.","Grind the oats in a coffee or spice grinder until they're a fine powder, not whole flakes, for the softest feel."],"safety_note":null,"keywords":["whipped soap","oatmeal","goat's milk soap","gentle exfoliant","everyday","sensitive skin"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"rhubarb-rose-swirl-soap","title":"Rhubarb Rose Swirl Soap","cat":"whipped-soap","time":"30 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (clear glycerin)","amount":"180 g (6.3 oz)"},{"item":"Liquid foaming bath base","amount":"35 g (1.2 oz)"},{"item":"Red cosmetic mica (for one half)","amount":"0.5 g (a small pinch)"},{"item":"Dried rose petals, crushed","amount":"5 g (1 tbsp)"},{"item":"Rhubarb-rose fragrance oil","amount":"5 g (about 1 tsp)"}],"method":["Cut the soap base into cubes and melt completely in a double boiler.","Pour the liquid base into two bowls, split roughly evenly.","Stir the red mica into one bowl only, for a deep rose-red half; leave the other clear white.","Let both bowls cool 2-3 min until they start to thicken, then whip each separately on high for 3-4 min until fluffy.","Whip half the foaming bath base into each bowl, then fold the rose petals and half the fragrance oil into each.","Spoon alternating dollops of each color into a jar and swirl once with a skewer.","Leave uncovered overnight to fully set."],"tips":["This tart-floral fragrance pairing is a nice change of pace from straight rose — it reads less 'old-fashioned perfume' and more modern.","Keep the red mica proportion low to start; it's easy to oversaturate a whipped base to a much darker shade than intended."],"safety_note":null,"keywords":["whipped soap","rhubarb","rose","swirl soap","spring","glycerin soap","floral"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"autumn-apple-cinnamon-whipped-soap","title":"Autumn Apple Cinnamon Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (goat's milk)","amount":"184 g (6.5 oz)"},{"item":"Liquid foaming bath base","amount":"28 g (1 oz)"},{"item":"Ground cinnamon","amount":"2 g (1/2 tsp)"},{"item":"Dehydrated apple bits, finely chopped","amount":"4 g (1 tbsp)"},{"item":"Apple cinnamon fragrance oil","amount":"7 g (about 1.5 tsp)"}],"method":["Cut the soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until fluffy.","Add the foaming bath base and whip 1-2 min more.","Fold in the cinnamon, dehydrated apple bits and fragrance oil.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["Use fully dehydrated, crisp-dry apple pieces, not fresh or soft-dried fruit — any trapped moisture doesn't belong in a melt-and-pour soap.","Chop the apple bits small; large pieces can stick out of the surface and go stale-looking faster than the soap itself ages."],"safety_note":null,"keywords":["whipped soap","apple cinnamon","fall","autumn","goat's milk soap","spiced","seasonal"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"candy-cane-stripe-whipped-soap","title":"Candy Cane Stripe Whipped Soap","cat":"whipped-soap","time":"35 min active, plus overnight to firm","batch_size":"about 10 oz (280 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (clear glycerin)","amount":"220 g (7.8 oz)"},{"item":"Liquid foaming bath base","amount":"40 g (1.4 oz)"},{"item":"Red cosmetic mica (for the red stripe layer)","amount":"1 g (1/8 tsp)"},{"item":"Peppermint essential oil","amount":"6 g (about 55 drops)"}],"method":["Cut the soap base into cubes and melt completely in a double boiler.","Pour the liquid base into two bowls, split roughly evenly.","Stir the red mica into one bowl only, for the red stripe; leave the other bowl clear white.","Let both bowls cool 2-3 min until they start to thicken, then whip each separately on high for 3-4 min until fluffy.","Whip half the foaming bath base into each bowl, then fold half the peppermint oil into each.","Spoon a layer of white into the jar, let it firm for 10-15 min, then add a layer of red, then white again, repeating to build thin stripes.","Leave uncovered overnight to fully set."],"tips":["The name and color here are inspired by the classic candy's look and peppermint scent only — no actual candy or sugar goes into this soap.","Thin layers that firm between pours give the cleanest stripes; thick layers poured too fast tend to bleed into each other."],"safety_note":null,"keywords":["whipped soap","candy cane","peppermint","layered soap","winter holiday","striped","gift"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"desert-sage-whipped-soap","title":"Desert Sage Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (olive oil, Castile-style)","amount":"188 g (6.6 oz)"},{"item":"Liquid foaming bath base","amount":"28 g (1 oz)"},{"item":"Dried sage leaves, crumbled","amount":"4 g (1 tsp)"},{"item":"Clary sage essential oil","amount":"3 g (about 30 drops)"},{"item":"Lavender essential oil","amount":"2 g (about 20 drops)"}],"method":["Cut the Castile-style soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until fluffy.","Add the foaming bath base and whip 1-2 min more.","Fold in the sage leaves and both essential oils.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["A touch of lavender softens clary sage's herbal edge without turning the scent floral.","This earthy, herbal bar works well marketed as a unisex or men's option alongside Rosemary Mint and Pine Forest."],"safety_note":null,"keywords":["whipped soap","sage","clary sage","herbal","castile soap","unisex","men's soap"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"blackberry-sage-marbled-soap","title":"Blackberry Sage Marbled Soap","cat":"whipped-soap","time":"30 min active, plus overnight to firm","batch_size":"about 10 oz (280 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (clear glycerin)","amount":"212 g (7.5 oz)"},{"item":"Liquid foaming bath base","amount":"40 g (1.4 oz)"},{"item":"Purple cosmetic mica (for the berry half)","amount":"1 g (1/8 tsp)"},{"item":"Dried sage leaves, crumbled (for the green half)","amount":"3 g (1 tsp)"},{"item":"Blackberry fragrance oil","amount":"4 g (about 1/2 tsp)"},{"item":"Clary sage essential oil","amount":"3 g (about 30 drops)"}],"method":["Cut the soap base into cubes and melt completely in a double boiler.","Pour the liquid base into two bowls, split roughly evenly.","Stir the purple mica into one bowl and the crumbled sage into the other.","Let both bowls cool 2-3 min until they start to thicken, then whip each separately on high for 3-4 min until fluffy.","Whip half the foaming bath base into each bowl, then fold the blackberry fragrance into the purple bowl and the clary sage oil into the green-flecked bowl.","Spoon small, random dollops of each color into a jar, alternating as you go, then drag a skewer through in loose figure-eight motions for a soft marbled look.","Leave uncovered overnight to fully set."],"tips":["Fruity-herbal combinations like this one are a nice change for fall gift sets alongside more classic spice scents.","A marbled finish is forgiving for beginners — even an uneven skewer pass still looks intentional, unlike a bold swirl that needs cleaner technique."],"safety_note":null,"keywords":["whipped soap","blackberry","sage","marbled soap","fall","fruity herbal","glycerin soap"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"vanilla-chai-whipped-soap","title":"Vanilla Chai Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (honey)","amount":"184 g (6.5 oz)"},{"item":"Liquid foaming bath base","amount":"28 g (1 oz)"},{"item":"Chai spice blend (cinnamon, cardamom, clove, ground black tea)","amount":"3 g (3/4 tsp)"},{"item":"Vanilla fragrance oil","amount":"7 g (about 1.5 tsp)"}],"method":["Cut the honey soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until fluffy.","Add the foaming bath base and whip 1-2 min more.","Fold in the chai spice blend and vanilla fragrance oil.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["Mix your own chai blend from pantry spices in equal small parts, or use a pre-mixed chai spice blend sold for baking — either works fine here since it's for scent and fleck, not consumption.","This is a cozy option to rotate in for fall and winter alongside Pumpkin Spice and Gingerbread."],"safety_note":null,"keywords":["whipped soap","vanilla chai","honey soap","spiced","fall","winter","gourmand"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"coconut-lime-swirl-soap","title":"Coconut Lime Swirl Soap","cat":"whipped-soap","time":"30 min active, plus overnight to firm","batch_size":"about 10 oz (280 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (goat's milk)","amount":"212 g (7.5 oz)"},{"item":"Liquid foaming bath base","amount":"40 g (1.4 oz)"},{"item":"Green cosmetic mica (for one half)","amount":"0.5 g (a small pinch)"},{"item":"Dried lime zest powder","amount":"3 g (1 tsp)"},{"item":"Coconut fragrance oil","amount":"4 g (about 1/2 tsp)"},{"item":"Lime essential oil","amount":"3 g (about 30 drops)"}],"method":["Cut the soap base into cubes and melt completely in a double boiler.","Pour the liquid base into two bowls, split roughly evenly.","Stir the green mica and lime zest into one bowl only; leave the other bowl plain white.","Let both bowls cool 2-3 min until they start to thicken, then whip each separately on high for 3-4 min until fluffy.","Whip half the foaming bath base into each bowl, then fold the coconut fragrance into the white bowl and the lime essential oil into the green bowl.","Spoon alternating dollops of each color into a jar and swirl once with a skewer.","Leave uncovered overnight to fully set."],"tips":["Lime essential oil can be phototoxic in leave-on products in direct sun, but since this soap rinses off in the shower, that risk doesn't apply here.","This tropical pairing is a strong seller for summer and beach-themed gift sets."],"safety_note":null,"keywords":["whipped soap","coconut lime","swirl soap","tropical","summer","beach","goat's milk soap"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"pink-clay-rose-whipped-soap","title":"Pink Clay Rose Whipped Soap","cat":"whipped-soap","time":"20 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (aloe vera)","amount":"186 g (6.6 oz)"},{"item":"Liquid foaming bath base","amount":"28 g (1 oz)"},{"item":"Pink Brazilian clay","amount":"6 g (1.5 tsp)"},{"item":"Dried rose petals, crushed","amount":"4 g (1 tsp)"},{"item":"Rose geranium essential oil","amount":"4 g (about 35 drops)"}],"method":["Cut the aloe vera soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until fluffy.","Add the foaming bath base and whip 1-2 min more.","Fold in the pink clay a little at a time until the color is even, then fold in the rose petals and essential oil.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["Pink clay gives a true dusty-rose color naturally, without needing added mica — a nice option if you prefer mineral colorants over cosmetic shimmer.","This soft, clay-based bar pairs well as a gift alongside a glass dish or soap tray, since clay bars can soften faster if left sitting in standing water."],"safety_note":null,"keywords":["whipped soap","pink clay","rose","clay soap","aloe vera soap","gift","floral"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"unscented-sensitive-skin-whipped-soap","title":"Unscented Sensitive Skin Whipped Soap","cat":"whipped-soap","time":"15 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (fragrance-free, hypoallergenic)","amount":"197 g (6.9 oz)"},{"item":"Liquid foaming bath base (fragrance-free)","amount":"28 g (1 oz)"}],"method":["Cut the fragrance-free soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until light and fluffy.","Add the foaming bath base and whip 1-2 min more to combine.","Spoon into jars right away and smooth the top with a spatula.","Leave uncovered overnight to fully set."],"tips":["This is the simplest formula in the whole collection on purpose — no color, no fragrance, no inclusions — for skin that reacts to almost everything else.","If you want to personalize it later, add fragrance or a gentle inclusion like colloidal oatmeal in small test batches first."],"safety_note":null,"keywords":["whipped soap","unscented","fragrance-free","sensitive skin","hypoallergenic","baby-safe","simple"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"birthday-confetti-whipped-soap","title":"Birthday Confetti Whipped Soap","cat":"whipped-soap","time":"25 min active (plus time to prep confetti ahead), plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (clear glycerin)","amount":"188 g (6.6 oz)"},{"item":"Liquid foaming bath base","amount":"28 g (1 oz)"},{"item":"Rainbow soap confetti (small cut pieces of leftover colored melt-and-pour soap, cooled and firm)","amount":"12 g (about 2 tbsp)"},{"item":"Mild sweet-type cosmetic fragrance oil (cake-scented, not a food ingredient)","amount":"4 g (about 1/2 tsp)"}],"method":["If you don't already have soap confetti on hand, melt small amounts of a few different colored scraps, pour thin and let set fully, then dice into small cubes.","Cut the main soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 3-5 min until fluffy.","Add the foaming bath base and whip 1-2 min more.","Fold in the fragrance oil, then gently fold in the soap confetti pieces last.","Spoon into jars and leave uncovered overnight to fully set."],"tips":["The fragrance here is a skin-safe cosmetic fragrance oil with a sweet, cake-like smell — it is not a food item and shouldn't be marketed or treated as one.","This is a fun option for kids' birthday party favors; keep the confetti pieces small so they don't feel chunky in the lather."],"safety_note":null,"keywords":["whipped soap","confetti soap","birthday","kids","fun soap","party favor","glycerin soap"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"autumn-harvest-piped-soap","title":"Autumn Harvest Piped Soap","cat":"whipped-soap","time":"30 min active, plus overnight to firm","batch_size":"about 8 oz (225 g)","shelf_life":"6-9 months at room temperature in a sealed container, away from humidity.","ingredients":[{"item":"Melt-and-pour soap base (goat's milk)","amount":"188 g (6.6 oz)"},{"item":"Liquid foaming bath base","amount":"22 g (0.8 oz)"},{"item":"Orange cosmetic mica (swirled through, not a solid color)","amount":"1 g (1/8 tsp)"},{"item":"Cinnamon, clove and nutmeg spice blend fragrance oil","amount":"6 g (about 1.25 tsp)"}],"method":["Cut the soap base into cubes and melt in a double boiler until fully liquid.","Let it cool 2-3 min until it starts to thicken at the edges.","Whip on high for 4-6 min — slightly longer and with a little less foaming base than usual — until it holds stiff peaks like whipped frosting.","Whip in the foaming bath base.","Drizzle the orange mica over the top and fold just once or twice, so it streaks rather than blends evenly.","Fold in the fragrance oil.","Transfer to a piping bag fitted with a large star tip and pipe rosettes directly into jars or onto a parchment-lined tray.","Leave uncovered overnight to fully set before moving piped rosettes into their final container."],"tips":["A stiffer whip (less liquid foaming base, a bit more whip time) is what lets the soap hold a piped rosette shape instead of slumping flat.","If the rosettes lose their shape before they set, the mixture was whipped too loose — next time reduce the foaming base slightly or whip 1-2 min longer."],"safety_note":null,"keywords":["whipped soap","piped soap","rosette","fall","spiced","goat's milk soap","gift"],"pdf":"../../whipped-soap-recipes/6f88m9jlxa/whipped-soap-recipes.pdf"},{"slug":"vanilla-bean-lip-oil","title":"Vanilla Bean Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Castor oil","amount":"6 g"},{"item":"Sweet almond oil","amount":"3 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Vanilla flavor oil (food-grade, not extract)","amount":"4-5 drops"}],"method":["Combine the castor oil and almond oil in a small cup.","Add the vitamin E oil and stir.","Add the vanilla flavor oil and stir well.","Use a dropper or small funnel to fill clean lip oil tubes."],"tips":["Vanilla flavor oil is food-grade and safe at higher drop counts than essential oils — taste a dab to judge strength before adding more.","This one skips essential oils entirely, so it's a good base for anyone with a sensitive mouth."],"safety_note":null,"keywords":["lip oil","vanilla","lip gloss","sweet","gift","anhydrous","no essential oil"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"rosy-tint-lip-oil","title":"Rosy Tint Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Castor oil","amount":"7 g"},{"item":"Jojoba oil","amount":"2 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Cosmetic-grade red iron oxide powder","amount":"a scant pinch, about 0.05 g (1/16 tsp or less)"}],"method":["Put the iron oxide powder in a small cup first and add 1 g of the castor oil.","Stir and mash with the back of a spoon for a full minute until no gritty specks remain — this prevents a speckled, uneven tint.","Add the rest of the castor oil, the jojoba oil, and the vitamin E oil, stirring well.","Let it sit for 10 minutes and check for settled grit at the bottom; strain through a fine mesh if needed.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["Start with less iron oxide than you think — a little gives a sheer rosy wash, too much looks like a muddy stain.","This is a tint, not full coverage like a lipstick; it's meant to look like your lips, just a shade warmer."],"safety_note":null,"keywords":["lip oil","tinted lip oil","rose","iron oxide","sheer color","gift"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"peppermint-cocoa-lip-oil","title":"Peppermint Cocoa Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Castor oil","amount":"5 g"},{"item":"Refined cocoa butter, melted","amount":"2 g"},{"item":"Sweet almond oil","amount":"2.5 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Peppermint essential oil","amount":"2 drops"}],"method":["Melt the cocoa butter in a small cup set in warm water for 1-2 minutes, until liquid.","Stir in the castor oil and almond oil.","Add the vitamin E oil and peppermint essential oil, stirring well.","Fill clean lip oil tubes right away, before the cocoa butter starts to set."],"tips":["Cocoa butter adds a faint chocolate smell on its own — it pairs naturally with the mint.","If it firms up in the tube on cool days, that's normal; warm the tube between your palms before using."],"safety_note":"Mint essential oils are strong and can tingle more than expected on lips. Do a patch test on your inner arm and wait 24 hours before trying a new blend on your lips, and start with the lower end of the drop range.","keywords":["lip oil","peppermint","cocoa butter","chocolate mint","winter","gift"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"sweet-almond-everyday-lip-oil","title":"Sweet Almond Everyday Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Sweet almond oil","amount":"7 g"},{"item":"Castor oil","amount":"2 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"}],"method":["Combine the almond oil and castor oil in a small cup.","Stir in the vitamin E oil.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["No added scent or flavor here, by design — this is the one to recommend to anyone with fragrance sensitivities.","Almond oil absorbs fast, so this feels lighter than the castor-heavy recipes; add an extra gram of castor oil if you prefer more shine."],"safety_note":null,"keywords":["lip oil","unscented","fragrance-free","sensitive","everyday","anhydrous"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"strawberry-shortcake-lip-oil","title":"Strawberry Shortcake Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Castor oil","amount":"6 g"},{"item":"Fractionated coconut oil","amount":"3 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Strawberry flavor oil (food-grade)","amount":"5-6 drops"}],"method":["Combine the castor oil and fractionated coconut oil in a small cup.","Add the vitamin E oil and stir.","Add the strawberry flavor oil and stir until fully blended.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["Fractionated coconut oil stays liquid at any room temperature, so this pours easily even in winter.","Taste-test the flavor strength on a fingertip before filling tubes — food flavor oils vary a lot in intensity by brand."],"safety_note":null,"keywords":["lip oil","strawberry","flavor oil","fruity","kids-friendly scent","gift"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"jojoba-glass-skin-lip-oil","title":"Jojoba Glass Skin Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Jojoba oil","amount":"6 g"},{"item":"Castor oil","amount":"3 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"}],"method":["Combine the jojoba oil and castor oil in a small cup.","Stir in the vitamin E oil.","Fill clean lip oil tubes or a small glass bottle with a wand applicator."],"tips":["Jojoba oil is technically a liquid wax, close to skin's own oils — this version feels the least greasy of all the base oils.","This is a great plain base to split into small batches and scent differently for a sampler gift set."],"safety_note":null,"keywords":["lip oil","jojoba","glossy","non-greasy","unscented","clean beauty"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"candy-cane-lip-oil","title":"Candy Cane Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Castor oil","amount":"6 g"},{"item":"Sweet almond oil","amount":"3 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Peppermint essential oil","amount":"1 drop"},{"item":"Vanilla flavor oil (food-grade)","amount":"3 drops"}],"method":["Combine the castor oil and almond oil in a small cup.","Stir in the vitamin E oil.","Add the peppermint essential oil and vanilla flavor oil, stirring well.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["This is a holiday gift favorite — the mint is kept very light so the vanilla comes through as the main note.","Package in a small red or green box for a stocking-stuffer look."],"safety_note":"Mint essential oils are strong and can tingle more than expected on lips. Do a patch test on your inner arm and wait 24 hours before trying a new blend on your lips, and start with the lower end of the drop range.","keywords":["lip oil","holiday","christmas","peppermint vanilla","stocking stuffer","gift"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"grapeseed-summer-glow-lip-oil","title":"Grapeseed Summer Glow Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Grapeseed oil","amount":"5 g"},{"item":"Castor oil","amount":"4 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Sweet orange essential oil","amount":"2 drops"}],"method":["Combine the grapeseed oil and castor oil in a small cup.","Stir in the vitamin E oil.","Add the sweet orange essential oil and stir well.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["Grapeseed oil is very light and thin, which makes this one of the glossiest, least sticky blends in the lineup.","Keep it out of direct sun in a hot car — thin oils like grapeseed oxidize a little faster than heavier ones."],"safety_note":"This recipe uses a cold-pressed citrus essential oil, which can make skin more sensitive to sunlight. The amount here is small and it's going on lips, not a large skin area, so the risk is low — but avoid sun exposure and tanning beds on treated lips for a few hours after applying, and do a patch test on your inner arm first if it's a new oil for you.","keywords":["lip oil","grapeseed","orange","citrus","summer","glossy"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"coconut-pina-colada-lip-oil","title":"Coconut Pina Colada Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Fractionated coconut oil","amount":"6 g"},{"item":"Castor oil","amount":"3 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Pineapple-coconut flavor oil (food-grade)","amount":"5-6 drops"}],"method":["Combine the fractionated coconut oil and castor oil in a small cup.","Stir in the vitamin E oil.","Add the flavor oil and stir until fully blended.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["Fractionated coconut oil doesn't smell like coconut on its own — all the tropical scent comes from the flavor oil, so you control the strength.","A fun one for a summer or vacation-themed gift set."],"safety_note":null,"keywords":["lip oil","coconut","pina colada","tropical","summer","flavor oil"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"winter-repair-lip-balm","title":"Winter Repair Lip Balm","cat":"lip-oil","time":"10 min active, 2 min melt time","batch_size":"about 1 oz (28 g), fills about 6 standard lip balm tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Castor oil","amount":"12 g (0.4 oz)"},{"item":"Shea butter","amount":"6 g (0.2 oz)"},{"item":"Beeswax pellets","amount":"8 g (0.3 oz)"},{"item":"Vitamin E oil","amount":"1 g (about 20 drops)"},{"item":"Sweet orange essential oil","amount":"3 drops"}],"method":["Set up a double boiler: a heatproof cup in a small pot with 1 in (2-3 cm) of simmering water.","Melt the beeswax and shea butter together, stirring until fully liquid (3-5 min).","Remove from heat and stir in the castor oil.","Add the vitamin E oil and sweet orange essential oil, stirring well.","Pour into empty lip balm tubes or small tins right away, before it starts to set.","Let cool undisturbed at room temperature for 20-30 min before capping."],"tips":["This is a solid balm, not a liquid oil — the extra beeswax is exactly what makes it stiff enough to twist up in a tube.","For chapped, cracked winter lips, apply a thicker layer at night and let it work while you sleep."],"safety_note":"This recipe uses a cold-pressed citrus essential oil, which can make skin more sensitive to sunlight. The amount here is small and it's going on lips, not a large skin area, so the risk is low — but avoid sun exposure and tanning beds on treated lips for a few hours after applying, and do a patch test on your inner arm first if it's a new oil for you.","keywords":["lip balm","winter","chapped lips","solid balm","repair","shea butter"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"lavender-dream-lip-oil","title":"Lavender Dream Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Sweet almond oil","amount":"6 g"},{"item":"Castor oil","amount":"3 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Lavender essential oil","amount":"2 drops"}],"method":["Combine the almond oil and castor oil in a small cup.","Stir in the vitamin E oil.","Add the lavender essential oil and stir well.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["Lavender is one of the gentler essential oils for lips, but it's still concentrated — keep to the drop count given.","A calming bedtime option; pair it with a lavender body oil for a matching set."],"safety_note":"Lavender essential oil is generally well tolerated, but it's still concentrated. Do a patch test on your inner arm and wait 24 hours before trying a new blend on your lips.","keywords":["lip oil","lavender","calming","night","gift","relaxing"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"honey-almond-lip-oil","title":"Honey Almond Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Sweet almond oil","amount":"7 g"},{"item":"Castor oil","amount":"2 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Honey flavor oil (food-grade)","amount":"4-5 drops"}],"method":["Combine the almond oil and castor oil in a small cup.","Stir in the vitamin E oil.","Add the honey flavor oil and stir until blended.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["Use a food-grade honey flavor oil, not real honey — real honey is water-based and will spoil in an oil blend.","This one reads as 'lip balm classic' flavor-wise, a safe pick for gift sets aimed at a wide range of people."],"safety_note":null,"keywords":["lip oil","honey","sweet","classic","gift","flavor oil"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"blood-orange-tint-lip-oil","title":"Blood Orange Tint Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Castor oil","amount":"7 g"},{"item":"Fractionated coconut oil","amount":"1.5 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Cosmetic-grade red iron oxide powder","amount":"a scant pinch, about 0.05 g"},{"item":"Sweet orange essential oil","amount":"1 drop"}],"method":["Put the iron oxide powder in a small cup with 1 g of the castor oil and mash with the back of a spoon for a full minute until smooth.","Add the rest of the castor oil and the fractionated coconut oil, stirring well.","Add the vitamin E oil and sweet orange essential oil.","Let sit 10 minutes, strain through a fine mesh if any grit settles, then fill clean lip oil tubes."],"tips":["The orange oil is kept to a single drop here since this is meant to be a subtle color-and-shine product, not a strong citrus scent.","If the tint looks too orange-red for your taste, that's the iron oxide batch — try a slightly smaller pinch next time."],"safety_note":"This recipe uses a cold-pressed citrus essential oil, which can make skin more sensitive to sunlight. The amount here is small and it's going on lips, not a large skin area, so the risk is low — but avoid sun exposure and tanning beds on treated lips for a few hours after applying, and do a patch test on your inner arm first if it's a new oil for you.","keywords":["lip oil","tinted","orange","iron oxide","sheer color","citrus"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"fragrance-free-sensitive-lip-oil","title":"Fragrance-Free Sensitive Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Fractionated coconut oil","amount":"6 g"},{"item":"Castor oil","amount":"3 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"}],"method":["Combine the fractionated coconut oil and castor oil in a small cup.","Stir in the vitamin E oil.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["No essential oils, no flavor oils, no color — this is the one to reach for on chapped, irritated, or reactive lips.","Fractionated coconut oil has almost no scent of its own, so this stays truly neutral."],"safety_note":null,"keywords":["lip oil","fragrance-free","sensitive skin","hypoallergenic","unscented","simple"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"cinnamon-spice-lip-oil","title":"Cinnamon Spice Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Castor oil","amount":"7 g"},{"item":"Sweet almond oil","amount":"2 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Cinnamon essential oil","amount":"1 drop, no more"}],"method":["Combine the castor oil and almond oil in a small cup.","Stir in the vitamin E oil.","Add the single drop of cinnamon essential oil and stir thoroughly so it's fully diluted through the whole blend.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["Cinnamon is one of the few essential oils where more is genuinely dangerous on lips — one drop in this batch size is already a warming, spicy effect.","If you want a milder spice without any heat risk, swap the cinnamon essential oil for a cinnamon flavor oil instead."],"safety_note":"Cinnamon essential oil is a strong skin irritant even in small amounts and can cause real burning on lips if overdosed. Do a patch test on your inner arm 24 hours before applying to lips, and never exceed the drop count given here.","keywords":["lip oil","cinnamon","spice","warming","fall","gift"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"macadamia-rose-lip-oil","title":"Macadamia Rose Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Macadamia nut oil","amount":"6 g"},{"item":"Castor oil","amount":"3 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Rose flavor oil or rose fragrance oil (skin-safe, food- or cosmetic-grade)","amount":"4-5 drops"}],"method":["Combine the macadamia oil and castor oil in a small cup.","Stir in the vitamin E oil.","Add the rose flavor or fragrance oil and stir well.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["Macadamia oil is rich and slightly heavier than almond oil, which makes this feel more cushiony on dry lips.","Use a rose fragrance oil formulated for cosmetics rather than a candle fragrance oil — not all fragrance oils are skin-safe."],"safety_note":null,"keywords":["lip oil","rose","macadamia","floral","romantic","gift"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"mint-chocolate-lip-oil","title":"Mint Chocolate Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Castor oil","amount":"5 g"},{"item":"Refined cocoa butter, melted","amount":"2 g"},{"item":"Fractionated coconut oil","amount":"2.5 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Peppermint essential oil","amount":"2 drops"}],"method":["Melt the cocoa butter in a small cup set in warm water for 1-2 minutes.","Stir in the castor oil and fractionated coconut oil.","Add the vitamin E oil and peppermint essential oil, stirring well.","Fill clean lip oil tubes right away, before the cocoa butter starts to set."],"tips":["This is a slightly richer cousin of the Peppermint Cocoa Lip Oil, with more coconut oil for a softer, less waxy pour.","Store in a cool spot — cocoa butter blends can soften in a hot car or direct sun."],"safety_note":"Mint essential oils are strong and can tingle more than expected on lips. Do a patch test on your inner arm and wait 24 hours before trying a new blend on your lips, and start with the lower end of the drop range.","keywords":["lip oil","mint chocolate","cocoa butter","winter","gift","dessert scent"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"coral-sunset-tint-lip-oil","title":"Coral Sunset Tint Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Castor oil","amount":"6 g"},{"item":"Sweet almond oil","amount":"2.5 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Cosmetic-grade red iron oxide powder","amount":"a scant pinch, about 0.04 g"},{"item":"Cosmetic-grade yellow iron oxide powder","amount":"a tiny pinch, about 0.02 g"}],"method":["Put both iron oxide powders in a small cup with 1 g of the castor oil and mash with the back of a spoon until smooth, about a minute.","Add the rest of the castor oil and the almond oil, stirring well.","Add the vitamin E oil and stir again.","Let sit 10 minutes, strain through a fine mesh if needed, then fill clean lip oil tubes."],"tips":["Mixing red and yellow iron oxide gives a warmer coral tone than red alone — adjust the ratio slightly to shift it more pink or more orange.","Test the tint on the back of your hand first; lip skin can show color a shade darker than it looks in the tube."],"safety_note":null,"keywords":["lip oil","tinted","coral","iron oxide","sheer color","summer"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"oatmeal-milk-lip-balm","title":"Oatmeal Milk Lip Balm","cat":"lip-oil","time":"10 min active, 2 min melt time","batch_size":"about 1 oz (28 g), fills about 6 standard lip balm tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Sweet almond oil","amount":"11 g (0.4 oz)"},{"item":"Shea butter","amount":"5 g (0.18 oz)"},{"item":"Beeswax pellets","amount":"8 g (0.3 oz)"},{"item":"Vitamin E oil","amount":"1 g (about 20 drops)"},{"item":"Oatmeal milk flavor oil (food-grade)","amount":"6-8 drops"}],"method":["Set up a double boiler and melt the beeswax and shea butter together, stirring until liquid (3-5 min).","Remove from heat and stir in the almond oil.","Add the vitamin E oil and oatmeal milk flavor oil, stirring well.","Pour into empty lip balm tubes or small tins right away, before it sets.","Let cool undisturbed for 20-30 min before capping."],"tips":["This flavor profile is mild and cozy, a good choice for a comfort-themed or 'bakery' style gift set.","If it doesn't release cleanly from a tube mold, chill it in the fridge for 10 minutes before twisting it down."],"safety_note":null,"keywords":["lip balm","solid balm","oatmeal milk","cozy","gift","flavor oil"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"bergamot-earl-grey-lip-oil","title":"Bergamot Earl Grey Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Sweet almond oil","amount":"6 g"},{"item":"Castor oil","amount":"3 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Bergamot essential oil (bergapten-free / FCF, non-phototoxic grade preferred)","amount":"2 drops"}],"method":["Combine the almond oil and castor oil in a small cup.","Stir in the vitamin E oil.","Add the bergamot essential oil and stir well.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["Regular (non-FCF) bergamot oil is one of the most phototoxic essential oils that exists — use a bergapten-free (FCF) version if you can find one, which removes most of that risk.","This gives a sophisticated, tea-like scent rather than a straightforward citrus smell."],"safety_note":"Bergamot is a cold-pressed citrus oil and, unless you're using a bergapten-free (FCF) version, it's one of the more phototoxic essential oils available — it can cause real skin reactions in direct sun. Do a patch test on your inner arm first, and avoid sun or tanning beds on treated lips for several hours after use.","keywords":["lip oil","bergamot","earl grey","citrus","phototoxic caution","sophisticated scent"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"avocado-vanilla-lip-oil","title":"Avocado Vanilla Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Avocado oil","amount":"5 g"},{"item":"Castor oil","amount":"4 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Vanilla flavor oil (food-grade)","amount":"4 drops"}],"method":["Combine the avocado oil and castor oil in a small cup.","Stir in the vitamin E oil.","Add the vanilla flavor oil and stir well.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["Avocado oil is thicker and greener in color than most light carrier oils, so this blend can look faintly golden-green — that's normal.","It's also heavier on the lips, which makes it a good pick for very dry climates."],"safety_note":null,"keywords":["lip oil","avocado","vanilla","nourishing","dry lips","gift"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"watermelon-fizz-lip-oil","title":"Watermelon Fizz Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Fractionated coconut oil","amount":"6 g"},{"item":"Castor oil","amount":"3 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Watermelon flavor oil (food-grade)","amount":"5-6 drops"}],"method":["Combine the fractionated coconut oil and castor oil in a small cup.","Stir in the vitamin E oil.","Add the watermelon flavor oil and stir until fully blended.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["This is one of the brightest, most playful scents in the lineup — great for a summer or back-to-school batch.","Pair with a pink-tinted version (see the tinted recipes) if you want color to match the fruity scent."],"safety_note":null,"keywords":["lip oil","watermelon","fruity","summer","kids-friendly scent","flavor oil"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"frankincense-calm-lip-oil","title":"Frankincense Calm Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Sweet almond oil","amount":"6 g"},{"item":"Castor oil","amount":"3 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Frankincense essential oil","amount":"2 drops"}],"method":["Combine the almond oil and castor oil in a small cup.","Stir in the vitamin E oil.","Add the frankincense essential oil and stir well.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["Frankincense has a resinous, grounding scent that reads more 'spa' than 'sweet' — a nice option for an adult gift set.","This essential oil is mild for most people, but still worth a patch test if it's new to your routine."],"safety_note":"Frankincense essential oil is gentle for most people, but it's still concentrated. Do a patch test on your inner arm and wait 24 hours before trying a new blend on your lips.","keywords":["lip oil","frankincense","spa","calming","grounding scent","gift"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"grapefruit-wake-up-lip-oil","title":"Grapefruit Wake-Up Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Grapeseed oil","amount":"6 g"},{"item":"Castor oil","amount":"3 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Grapefruit essential oil","amount":"2 drops"}],"method":["Combine the grapeseed oil and castor oil in a small cup.","Stir in the vitamin E oil.","Add the grapefruit essential oil and stir well.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["Grapefruit is a brighter, less sweet citrus than orange — a good match for a morning routine kit.","Keep this one in a bag out of direct sun; cold-pressed citrus oils fade and oxidize faster in heat and light."],"safety_note":"This recipe uses a cold-pressed citrus essential oil, which can make skin more sensitive to sunlight. The amount here is small and it's going on lips, not a large skin area, so the risk is low — but avoid sun exposure and tanning beds on treated lips for a few hours after applying, and do a patch test on your inner arm first if it's a new oil for you.","keywords":["lip oil","grapefruit","citrus","morning","energizing scent","gift"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"rose-gold-shimmer-lip-oil","title":"Rose Gold Shimmer Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Castor oil","amount":"6 g"},{"item":"Jojoba oil","amount":"2.5 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Cosmetic-grade mica powder, warm gold shade (skin-safe, labeled for cosmetic use)","amount":"a scant pinch, about 0.05 g"}],"method":["Put the mica powder in a small cup with 1 g of the castor oil and stir until fully dispersed, with no clumps.","Add the rest of the castor oil and the jojoba oil, stirring well.","Add the vitamin E oil and stir again.","Fill clean lip oil tubes with a dropper or small funnel, shaking before each use since mica can settle."],"tips":["Only use mica labeled for cosmetic/lip use — craft-grade glitter and mica are not safe for lips or skin.","Shake the tube before each application; the shimmer will settle to the bottom between uses."],"safety_note":null,"keywords":["lip oil","shimmer","mica","rose gold","night out","gift"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"ginger-citrus-lip-oil","title":"Ginger Citrus Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Sweet almond oil","amount":"6 g"},{"item":"Castor oil","amount":"3 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Ginger essential oil","amount":"1 drop"},{"item":"Sweet orange essential oil","amount":"1 drop"}],"method":["Combine the almond oil and castor oil in a small cup.","Stir in the vitamin E oil.","Add the ginger and sweet orange essential oils and stir well.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["Ginger essential oil can warm the skin slightly — one drop in this batch size keeps it pleasant rather than hot.","A good autumn-leaning scent that's spicier than straight citrus but milder than cinnamon."],"safety_note":"This recipe uses a cold-pressed citrus essential oil, which can make skin more sensitive to sunlight. The amount here is small and it's going on lips, not a large skin area, so the risk is low — but avoid sun exposure and tanning beds on treated lips for a few hours after applying, and do a patch test on your inner arm first if it's a new oil for you.","keywords":["lip oil","ginger","citrus","fall","spiced","warming scent"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"cucumber-melon-lip-oil","title":"Cucumber Melon Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Fractionated coconut oil","amount":"6 g"},{"item":"Castor oil","amount":"3 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Cucumber melon flavor oil (food-grade)","amount":"5-6 drops"}],"method":["Combine the fractionated coconut oil and castor oil in a small cup.","Stir in the vitamin E oil.","Add the cucumber melon flavor oil and stir until blended.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["A cool, fresh scent that doesn't skew as sweet as the other fruit flavor oils — nice for a 'spa day' gift set.","This base is interchangeable with any other flavor oil at the same drop count if you want to riff on it."],"safety_note":null,"keywords":["lip oil","cucumber melon","fresh scent","spa","summer","flavor oil"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"berry-stain-tint-lip-oil","title":"Berry Stain Tint Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Castor oil","amount":"6.5 g"},{"item":"Sweet almond oil","amount":"2 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Cosmetic-grade red iron oxide powder","amount":"a pinch, about 0.08 g"},{"item":"Berry flavor oil (food-grade)","amount":"4-5 drops"}],"method":["Put the iron oxide powder in a small cup with 1 g of the castor oil and mash with the back of a spoon until smooth, about a minute.","Add the rest of the castor oil and the almond oil, stirring well.","Add the vitamin E oil and berry flavor oil, stirring again.","Let sit 10 minutes, strain through a fine mesh if any grit settles, then fill clean lip oil tubes."],"tips":["This uses more iron oxide than the sheer tints for a deeper, stained-lip look — still a wash of color, not opaque coverage.","Shake before each use since pigment can settle to the bottom of the tube over time."],"safety_note":null,"keywords":["lip oil","tinted","berry","stain","iron oxide","deeper color"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"apricot-kernel-rose-lip-oil","title":"Apricot Kernel Rose Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Apricot kernel oil","amount":"6 g"},{"item":"Castor oil","amount":"3 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Rose geranium essential oil","amount":"2 drops"}],"method":["Combine the apricot kernel oil and castor oil in a small cup.","Stir in the vitamin E oil.","Add the rose geranium essential oil and stir well.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["Apricot kernel oil is light and fast-absorbing, similar to almond oil but slightly thinner.","Rose geranium smells closer to true rose than most essential oils and costs less than rose otto."],"safety_note":"Rose geranium essential oil is mild for most people, but it's still concentrated. Do a patch test on your inner arm and wait 24 hours before trying a new blend on your lips.","keywords":["lip oil","apricot kernel","rose geranium","floral","light oil","gift"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"s-mores-lip-oil","title":"S'mores Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Castor oil","amount":"5 g"},{"item":"Refined cocoa butter, melted","amount":"2 g"},{"item":"Fractionated coconut oil","amount":"2.5 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Toasted marshmallow flavor oil (food-grade)","amount":"4-5 drops"}],"method":["Melt the cocoa butter in a small cup set in warm water for 1-2 minutes.","Stir in the castor oil and fractionated coconut oil.","Add the vitamin E oil and marshmallow flavor oil, stirring well.","Fill clean lip oil tubes right away, before the cocoa butter starts to set."],"tips":["This pairs chocolate (cocoa butter) with toasted marshmallow for a campfire-dessert scent, no graham needed.","A fun option for a fall or camping-themed gift set."],"safety_note":null,"keywords":["lip oil","s'mores","cocoa butter","marshmallow","dessert scent","fall"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"sunflower-chamomile-lip-oil","title":"Sunflower Chamomile Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"High-oleic sunflower oil","amount":"6 g"},{"item":"Castor oil","amount":"3 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Roman chamomile essential oil","amount":"2 drops"}],"method":["Combine the sunflower oil and castor oil in a small cup.","Stir in the vitamin E oil.","Add the chamomile essential oil and stir well.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["High-oleic sunflower oil is lighter and more stable than regular sunflower oil, which helps this last its full shelf life.","Chamomile is one of the calmest-smelling essential oils; a good one for sensitive-skin gift sets alongside the patch test note."],"safety_note":"Chamomile essential oil is gentle for most people, but it's still concentrated, and rarely some people with ragweed allergies react to it. Do a patch test on your inner arm and wait 24 hours before trying a new blend on your lips.","keywords":["lip oil","chamomile","sunflower oil","calming","gentle","gift"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"lime-mojito-lip-oil","title":"Lime Mojito Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Sweet almond oil","amount":"6 g"},{"item":"Castor oil","amount":"3 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Lime essential oil (cold-pressed)","amount":"1 drop"},{"item":"Spearmint essential oil","amount":"1 drop"}],"method":["Combine the almond oil and castor oil in a small cup.","Stir in the vitamin E oil.","Add the lime and spearmint essential oils and stir well.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["Cold-pressed lime is phototoxic like other citrus-peel oils — steam-distilled lime is a gentler substitute if you'd rather skip the sun caution.","Spearmint is milder than peppermint, so this stays refreshing without a strong tingle."],"safety_note":"This recipe uses cold-pressed lime, which can make skin more sensitive to sunlight. The amount here is small and going on lips rather than a large skin area, so the risk is low — but avoid sun exposure on treated lips for a few hours after applying, and patch test first if it's a new oil for you.","keywords":["lip oil","lime","spearmint","mojito","summer","citrus"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"pumpkin-spice-lip-oil","title":"Pumpkin Spice Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Castor oil","amount":"6 g"},{"item":"Sweet almond oil","amount":"2.5 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Pumpkin spice flavor oil (food-grade)","amount":"5-6 drops"}],"method":["Combine the castor oil and almond oil in a small cup.","Stir in the vitamin E oil.","Add the pumpkin spice flavor oil and stir until blended.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["Using a pre-blended food-grade flavor oil here avoids the overdose risk of stacking cinnamon and clove essential oils.","A seasonal best-seller for fall markets and gift boxes."],"safety_note":null,"keywords":["lip oil","pumpkin spice","fall","seasonal","flavor oil","gift"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"tea-tree-cooling-lip-oil","title":"Tea Tree Cooling Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Jojoba oil","amount":"6 g"},{"item":"Castor oil","amount":"3 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Tea tree essential oil","amount":"1 drop"},{"item":"Peppermint essential oil","amount":"1 drop"}],"method":["Combine the jojoba oil and castor oil in a small cup.","Stir in the vitamin E oil.","Add the tea tree and peppermint essential oils and stir well.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["Tea tree has a sharp, medicinal smell on its own — pairing it with a touch of peppermint makes it more pleasant without losing the cooling effect.","Marketed as an after-sun or dry-cracked-lip option, not a treatment claim — avoid saying it 'heals' anything."],"safety_note":"Mint essential oils are strong and can tingle more than expected on lips. Do a patch test on your inner arm and wait 24 hours before trying a new blend on your lips, and start with the lower end of the drop range.","keywords":["lip oil","tea tree","peppermint","cooling","dry lips","fresh scent"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"coconut-cream-lip-oil","title":"Coconut Cream Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Fractionated coconut oil","amount":"7 g"},{"item":"Castor oil","amount":"2 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Coconut flavor oil (food-grade)","amount":"5-6 drops"}],"method":["Combine the fractionated coconut oil and castor oil in a small cup.","Stir in the vitamin E oil.","Add the coconut flavor oil and stir until fully blended.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["Fractionated coconut oil doesn't smell like coconut, so the flavor oil does all the work here — a straightforward, crowd-pleasing scent.","Pairs naturally with the Watermelon Fizz or Pineapple-Coconut recipes for a tropical gift set."],"safety_note":null,"keywords":["lip oil","coconut","cream","tropical","summer","flavor oil"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"eucalyptus-mint-lip-oil","title":"Eucalyptus Mint Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Sweet almond oil","amount":"6 g"},{"item":"Castor oil","amount":"3 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Eucalyptus essential oil","amount":"1 drop"},{"item":"Peppermint essential oil","amount":"1 drop"}],"method":["Combine the almond oil and castor oil in a small cup.","Stir in the vitamin E oil.","Add the eucalyptus and peppermint essential oils and stir well.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["This combination is intensely fresh — great for a winter 'clear the senses' product, but start with just the amounts given.","Not recommended as a base to add more mint to; both oils here are already strong."],"safety_note":"Mint essential oils are strong and can tingle more than expected on lips. Do a patch test on your inner arm and wait 24 hours before trying a new blend on your lips, and start with the lower end of the drop range.","keywords":["lip oil","eucalyptus","peppermint","cooling","winter","fresh scent"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"golden-honey-tint-lip-oil","title":"Golden Honey Tint Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Castor oil","amount":"7 g"},{"item":"Sweet almond oil","amount":"1.5 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Cosmetic-grade yellow iron oxide powder","amount":"a scant pinch, about 0.03 g"},{"item":"Honey flavor oil (food-grade)","amount":"3-4 drops"}],"method":["Put the iron oxide powder in a small cup with 1 g of the castor oil and stir until fully smooth, about a minute.","Add the rest of the castor oil and the almond oil, stirring well.","Add the vitamin E oil and honey flavor oil, stirring again.","Let sit 10 minutes, strain through a fine mesh if needed, then fill clean lip oil tubes."],"tips":["Yellow iron oxide alone gives a warm golden cast rather than a pink or red tint — a nice neutral option for warmer skin tones.","Shake before each use since pigment can settle over time."],"safety_note":null,"keywords":["lip oil","tinted","golden","honey","iron oxide","warm tone"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"peach-bellini-lip-oil","title":"Peach Bellini Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Fractionated coconut oil","amount":"6 g"},{"item":"Castor oil","amount":"3 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Peach flavor oil (food-grade)","amount":"5-6 drops"}],"method":["Combine the fractionated coconut oil and castor oil in a small cup.","Stir in the vitamin E oil.","Add the peach flavor oil and stir until fully blended.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["A soft, not-too-sweet fruit scent that tests well for both teens and adults in gift sets.","Works nicely as the 'fourth flavor' alongside strawberry, watermelon and cucumber melon in a sampler pack."],"safety_note":null,"keywords":["lip oil","peach","fruity","summer","gift","flavor oil"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"vanilla-lavender-lip-balm","title":"Vanilla Lavender Lip Balm","cat":"lip-oil","time":"10 min active, 2 min melt time","batch_size":"about 1 oz (28 g), fills about 6 standard lip balm tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Sweet almond oil","amount":"11 g (0.4 oz)"},{"item":"Shea butter","amount":"5 g (0.18 oz)"},{"item":"Beeswax pellets","amount":"8 g (0.3 oz)"},{"item":"Vitamin E oil","amount":"1 g (about 20 drops)"},{"item":"Vanilla flavor oil (food-grade)","amount":"4 drops"},{"item":"Lavender essential oil","amount":"3 drops"}],"method":["Set up a double boiler and melt the beeswax and shea butter together, stirring until liquid (3-5 min).","Remove from heat and stir in the almond oil.","Add the vitamin E oil, vanilla flavor oil and lavender essential oil, stirring well.","Pour into empty lip balm tubes or small tins right away, before it sets.","Let cool undisturbed for 20-30 min before capping."],"tips":["A solid balm holds up better than a liquid oil for travel or a gym bag — nothing to spill.","If you want it firmer for a hot climate, add another 1-2 g of beeswax."],"safety_note":"Lavender essential oil is generally well tolerated, but it's still concentrated. Do a patch test on your inner arm and wait 24 hours before trying a new blend on your lips.","keywords":["lip balm","solid balm","vanilla","lavender","travel","gift"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"espresso-cream-lip-oil","title":"Espresso Cream Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Castor oil","amount":"5 g"},{"item":"Fractionated coconut oil","amount":"4 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Coffee flavor oil (food-grade)","amount":"5-6 drops"}],"method":["Combine the castor oil and fractionated coconut oil in a small cup.","Stir in the vitamin E oil.","Add the coffee flavor oil and stir until fully blended.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["A fun novelty scent for coffee lovers — pair with the Vanilla Bean or Honey Almond recipe for a 'latte' gift duo.","Coffee flavor oils vary in strength by brand; start at 5 drops and taste-test before adding the sixth."],"safety_note":null,"keywords":["lip oil","coffee","espresso","novelty scent","gift","flavor oil"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"rosemary-mint-lip-oil","title":"Rosemary Mint Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Sweet almond oil","amount":"6 g"},{"item":"Castor oil","amount":"3 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Rosemary essential oil","amount":"1 drop"},{"item":"Spearmint essential oil","amount":"1 drop"}],"method":["Combine the almond oil and castor oil in a small cup.","Stir in the vitamin E oil.","Add the rosemary and spearmint essential oils and stir well.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["An herbal-fresh scent rather than a sweet or fruity one — good for a unisex gift set.","Spearmint keeps this gentler than a peppermint-forward blend would be."],"safety_note":"Mint essential oils are strong and can tingle more than expected on lips. Do a patch test on your inner arm and wait 24 hours before trying a new blend on your lips, and start with the lower end of the drop range.","keywords":["lip oil","rosemary","spearmint","herbal","unisex scent","fresh"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"mango-tango-lip-oil","title":"Mango Tango Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Fractionated coconut oil","amount":"6 g"},{"item":"Castor oil","amount":"3 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Mango flavor oil (food-grade)","amount":"5-6 drops"}],"method":["Combine the fractionated coconut oil and castor oil in a small cup.","Stir in the vitamin E oil.","Add the mango flavor oil and stir until fully blended.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["One of the more tropical, vacation-style scents — bundle it with Pineapple-Coconut and Watermelon Fizz as a summer trio.","If the scent fades after a few weeks, that's normal for flavor oils; make smaller batches more often rather than one giant jar."],"safety_note":null,"keywords":["lip oil","mango","tropical","summer","fruity","flavor oil"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"black-tea-bergamot-lip-oil","title":"Black Tea Bergamot Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Grapeseed oil","amount":"6 g"},{"item":"Castor oil","amount":"3 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Bergamot essential oil (bergapten-free / FCF)","amount":"2 drops"},{"item":"Black tea flavor oil (food-grade, optional)","amount":"2 drops"}],"method":["Combine the grapeseed oil and castor oil in a small cup.","Stir in the vitamin E oil.","Add the bergamot essential oil and the black tea flavor oil, if using, and stir well.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["As with the Bergamot Earl Grey recipe, use an FCF (bergapten-free) bergamot to cut most of the sun-sensitivity risk.","The black tea flavor oil is optional — bergamot alone already reads as 'Earl Grey' to most noses."],"safety_note":"Bergamot is a cold-pressed citrus oil and, unless you're using a bergapten-free (FCF) version, it's one of the more phototoxic essential oils available — it can cause real skin reactions in direct sun. Do a patch test on your inner arm first, and avoid sun or tanning beds on treated lips for several hours after use.","keywords":["lip oil","bergamot","black tea","citrus","phototoxic caution","sophisticated scent"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"bridal-sheer-shimmer-lip-oil","title":"Bridal Sheer Shimmer Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Jojoba oil","amount":"6 g"},{"item":"Castor oil","amount":"2.5 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Cosmetic-grade mica powder, pearl-white shade (skin-safe, labeled for cosmetic use)","amount":"a scant pinch, about 0.04 g"}],"method":["Put the mica powder in a small cup with 1 g of the castor oil and stir until fully dispersed, with no clumps.","Add the rest of the castor oil and the jojoba oil, stirring well.","Add the vitamin E oil and stir again.","Fill clean lip oil tubes or a small glass bottle with a wand applicator, shaking before each use."],"tips":["A barely-there shimmer designed to sit over a bride's own lip color rather than compete with it — no strong scent, by design.","Make a few days ahead so it's ready to tuck into a bridesmaid gift box."],"safety_note":null,"keywords":["lip oil","shimmer","mica","bridal","wedding","gift","unscented"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"sandalwood-vanilla-lip-oil","title":"Sandalwood Vanilla Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Sweet almond oil","amount":"6 g"},{"item":"Castor oil","amount":"3 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Sandalwood essential oil","amount":"1 drop"},{"item":"Vanilla flavor oil (food-grade)","amount":"3 drops"}],"method":["Combine the almond oil and castor oil in a small cup.","Stir in the vitamin E oil.","Add the sandalwood essential oil and vanilla flavor oil, stirring well.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["Sandalwood is mellow and woody; a single drop is enough to round out the sweetness of the vanilla without taking over.","A good 'date night' option — warm and soft rather than bright or fruity."],"safety_note":"Sandalwood essential oil is gentle for most people, but it's still concentrated. Do a patch test on your inner arm and wait 24 hours before trying a new blend on your lips.","keywords":["lip oil","sandalwood","vanilla","warm scent","date night","gift"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"grape-soda-lip-oil","title":"Grape Soda Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Fractionated coconut oil","amount":"6 g"},{"item":"Castor oil","amount":"3 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Grape flavor oil (food-grade)","amount":"5-6 drops"}],"method":["Combine the fractionated coconut oil and castor oil in a small cup.","Stir in the vitamin E oil.","Add the grape flavor oil and stir until fully blended.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["A nostalgic, candy-shop scent that tests especially well with teen and tween customers.","Consider a light purple-tinted version using a very small pinch of cosmetic mica if you want the color to match."],"safety_note":null,"keywords":["lip oil","grape","candy scent","nostalgic","gift","flavor oil"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"hazelnut-cocoa-lip-oil","title":"Hazelnut Cocoa Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Hazelnut oil","amount":"5 g"},{"item":"Refined cocoa butter, melted","amount":"2 g"},{"item":"Castor oil","amount":"2.5 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"}],"method":["Melt the cocoa butter in a small cup set in warm water for 1-2 minutes.","Stir in the hazelnut oil and castor oil.","Add the vitamin E oil and stir well.","Fill clean lip oil tubes right away, before the cocoa butter starts to set."],"tips":["Hazelnut oil naturally smells a little nutty and toasty, which pairs with the cocoa butter for a chocolate-hazelnut spread effect with no added flavor oil.","Skip this one for anyone with a tree nut allergy — hazelnut oil is cold-pressed from the nut itself."],"safety_note":null,"keywords":["lip oil","hazelnut","cocoa butter","chocolate","nutty scent","gift"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"aloe-fresh-mint-lip-oil","title":"Aloe Fresh Mint Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Fractionated coconut oil","amount":"6 g"},{"item":"Castor oil","amount":"3 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Spearmint essential oil","amount":"2 drops"}],"method":["Combine the fractionated coconut oil and castor oil in a small cup.","Stir in the vitamin E oil.","Add the spearmint essential oil and stir well.","Fill clean lip oil tubes with a dropper or small funnel."],"tips":["Spearmint reads as softer and sweeter than peppermint, so this is a gentler everyday mint option.","Despite the name, this recipe doesn't include liquid aloe — aloe is water-based and would need a preservative; it's named for the cool, fresh feel instead."],"safety_note":"Mint essential oils are strong and can tingle more than expected on lips. Do a patch test on your inner arm and wait 24 hours before trying a new blend on your lips, and start with the lower end of the drop range.","keywords":["lip oil","spearmint","fresh","cooling","everyday","mild mint"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"champagne-new-year-lip-oil","title":"Champagne New Year Lip Oil","cat":"lip-oil","time":"5 min active, no cook time","batch_size":"about 10 ml (0.3 fl oz), enough for 2-3 lip oil tubes","shelf_life":"Up to 1 year at room temperature. No water in this recipe, so no preservative is needed — just keep the applicator or cap clean and dry.","ingredients":[{"item":"Castor oil","amount":"6 g"},{"item":"Jojoba oil","amount":"2 g"},{"item":"Vitamin E oil","amount":"0.5 g (about 10 drops)"},{"item":"Cosmetic-grade gold mica powder (skin-safe, labeled for cosmetic use)","amount":"a scant pinch, about 0.04 g"},{"item":"Champagne or sparkling-grape flavor oil (food-grade)","amount":"3-4 drops"}],"method":["Put the mica powder in a small cup with 1 g of the castor oil and stir until fully dispersed, with no clumps.","Add the rest of the castor oil and the jojoba oil, stirring well.","Add the vitamin E oil and flavor oil, stirring again.","Fill clean lip oil tubes with a dropper or small funnel, shaking before each use."],"tips":["A celebratory, party-ready finish — the gold shimmer and sweet scent make this a popular New Year's Eve or birthday gift pick.","Shake well before each use since the mica settles between applications."],"safety_note":null,"keywords":["lip oil","shimmer","mica","champagne","new year","party","gift"],"pdf":"../../lip-oil-recipes/aluh99r48e/lip-oil-recipes.pdf"},{"slug":"citrus-grove-body-oil","title":"Citrus Grove Body Oil","cat":"body-oil","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"6-12 months at room temperature, away from direct sunlight. No water in this recipe, so no preservative is needed — just keep the bottle cap dry.","ingredients":[{"item":"Fractionated coconut oil","amount":"70 g (2.5 oz)"},{"item":"Sweet almond oil","amount":"30 g (1.1 oz)"},{"item":"Vitamin E oil","amount":"2 g (about 1/3 tsp), slows rancidity"},{"item":"Sweet orange essential oil","amount":"20 drops (about 1 g)"},{"item":"Grapefruit essential oil","amount":"15 drops (about 0.75 g)"}],"method":["Measure the fractionated coconut oil and almond oil into a clean glass bottle.","Add the vitamin E oil.","Add the orange and grapefruit essential oils.","Cap tightly and shake gently for 15-20 seconds to combine.","Label with the scent and the date you made it."],"tips":["Citrus essential oils are phototoxic — avoid direct sun on treated skin for several hours after applying, or use this one at night.","Shake before every use: the lighter and heavier oils can separate slightly on the shelf."],"safety_note":"Contains citrus essential oils, which can increase skin sensitivity to sunlight. Do a patch test on your inner arm and wait 24 hours before applying over your whole body, and avoid direct sun exposure on treated skin for several hours.","keywords":["body oil","citrus body oil","orange","grapefruit","dry oil","summer","anhydrous"],"pdf":"../../body-oil-recipes/g65gssg2kj/body-oil-recipes.pdf"},{"slug":"jojoba-rose-shimmer-oil","title":"Jojoba Rose Shimmer Oil","cat":"body-oil","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"6-12 months at room temperature. No water in this recipe, so no preservative is needed.","ingredients":[{"item":"Jojoba oil","amount":"80 g (2.8 oz)"},{"item":"Apricot kernel oil","amount":"20 g (0.7 oz)"},{"item":"Geranium essential oil","amount":"20 drops (about 1 g)"},{"item":"Cosmetic-grade mica powder, rose-gold shade (optional)","amount":"1 g (about 1/4 tsp)"}],"method":["Measure the jojoba and apricot kernel oils into a clean glass bottle.","Add the geranium essential oil and cap, shaking gently to combine.","If using mica, add it last and shake hard for 30 seconds — it won't fully dissolve, it suspends.","Label with the date made; shake before each use since the mica will settle."],"tips":["Use only mica labeled cosmetic-grade for skin, never craft or soap-dye mica — they're not held to the same purity standard.","If the shimmer looks patchy on skin, you added too much — a little mica goes a long way in a clear oil base."],"safety_note":"Essential oils are concentrated. Do a patch test on your inner arm and wait 24 hours before using a new blend on your whole body.","keywords":["body oil","shimmer oil","jojoba","geranium","highlighter oil","mica","gift"],"pdf":"../../body-oil-recipes/g65gssg2kj/body-oil-recipes.pdf"},{"slug":"warm-vanilla-almond-oil","title":"Warm Vanilla Almond Oil","cat":"body-oil","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"6-12 months at room temperature. No water in this recipe, so no preservative is needed.","ingredients":[{"item":"Sweet almond oil","amount":"100 g (3.5 oz)"},{"item":"Fractionated coconut oil","amount":"15 g (0.5 oz)"},{"item":"Vitamin E oil","amount":"2 g (about 1/3 tsp), slows rancidity"},{"item":"Skin-safe vanilla fragrance oil","amount":"5 g (1 tsp)"}],"method":["Measure the almond oil and fractionated coconut oil into a clean glass bottle.","Add the vitamin E oil and the vanilla fragrance oil.","Cap tightly and shake gently for 15-20 seconds to combine.","Let it rest for 24 hours before first use so the scent settles into the oil."],"tips":["Use a fragrance oil formulated for skin (not a candle-only fragrance oil) — candle fragrance isn't tested for leave-on skin use.","This blend has no essential oil, so it's a gentle starting point if you're new to DIY body oils."],"safety_note":null,"keywords":["body oil","vanilla body oil","almond oil","dry oil","warm scent","gift","anhydrous"],"pdf":"../../body-oil-recipes/g65gssg2kj/body-oil-recipes.pdf"},{"slug":"eucalyptus-mint-cooldown-oil","title":"Eucalyptus Mint Cooldown Oil","cat":"body-oil","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"6-12 months at room temperature. No water in this recipe, so no preservative is needed.","ingredients":[{"item":"Fractionated coconut oil","amount":"90 g (3.2 oz)"},{"item":"Grapeseed oil","amount":"25 g (0.9 oz)"},{"item":"Eucalyptus essential oil","amount":"20 drops (about 1 g)"},{"item":"Peppermint essential oil","amount":"10 drops (about 0.5 g)"}],"method":["Measure the fractionated coconut oil and grapeseed oil into a clean glass bottle.","Add the eucalyptus and peppermint essential oils.","Cap tightly and shake gently for 15-20 seconds to combine.","Label with the date made."],"tips":["Apply to arms and legs after a workout for a cooling effect — avoid the face and any broken skin, since both oils can tingle.","Keep away from pets: eucalyptus and peppermint essential oils are not safe for cats and dogs."],"safety_note":"Eucalyptus and peppermint are strong essential oils. Do a patch test on your inner arm and wait 24 hours before using on your whole body, and keep this oil away from young children's faces and hands.","keywords":["body oil","eucalyptus","peppermint","cooling oil","post-workout","menthol","dry oil"],"pdf":"../../body-oil-recipes/g65gssg2kj/body-oil-recipes.pdf"},{"slug":"argan-frankincense-night-oil","title":"Argan Frankincense Night Oil","cat":"body-oil","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"6-12 months at room temperature, away from direct sunlight.","ingredients":[{"item":"Argan oil","amount":"70 g (2.5 oz)"},{"item":"Sweet almond oil","amount":"30 g (1.1 oz)"},{"item":"Vitamin E oil","amount":"2 g (about 1/3 tsp), slows rancidity"},{"item":"Frankincense essential oil","amount":"15 drops (about 0.75 g)"}],"method":["Measure the argan and almond oils into a clean glass bottle.","Add the vitamin E oil and the frankincense essential oil.","Cap tightly and shake gently for 15-20 seconds to combine.","Label with the date made."],"tips":["Argan oil has a natural nutty smell of its own — frankincense layers well over it instead of fighting it.","Best used at night: argan oil can feel rich for daytime wear under clothing."],"safety_note":"Essential oils are concentrated. Do a patch test on your inner arm and wait 24 hours before using a new blend on your whole body.","keywords":["body oil","argan oil","frankincense","night routine","winter oil","dry oil","gift"],"pdf":"../../body-oil-recipes/g65gssg2kj/body-oil-recipes.pdf"},{"slug":"grapeseed-lemongrass-oil","title":"Grapeseed Lemongrass Body Oil","cat":"body-oil","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"6-12 months at room temperature, away from direct sunlight.","ingredients":[{"item":"Grapeseed oil","amount":"90 g (3.2 oz)"},{"item":"Fractionated coconut oil","amount":"25 g (0.9 oz)"},{"item":"Lemongrass essential oil","amount":"20 drops (about 1 g)"},{"item":"Lime essential oil","amount":"10 drops (about 0.5 g)"}],"method":["Measure the grapeseed and fractionated coconut oils into a clean glass bottle.","Add the lemongrass and lime essential oils.","Cap tightly and shake gently for 15-20 seconds to combine.","Label with the date made."],"tips":["Grapeseed oil is light and absorbs fast, which makes this a good pick for humid climates.","Lemongrass can irritate sensitive skin at full strength more than other oils — the dilution here is kept light on purpose; don't add extra drops."],"safety_note":"Contains lime essential oil, which is phototoxic. Do a patch test on your inner arm, wait 24 hours, and avoid direct sun exposure on treated skin for several hours after applying.","keywords":["body oil","lemongrass","lime","grapeseed oil","citrus herbal","dry oil","summer"],"pdf":"../../body-oil-recipes/g65gssg2kj/body-oil-recipes.pdf"},{"slug":"fragrance-free-sensitive-skin-oil","title":"Fragrance-Free Sensitive Skin Oil","cat":"body-oil","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"6-12 months at room temperature. No water in this recipe, so no preservative is needed.","ingredients":[{"item":"Sunflower oil","amount":"90 g (3.2 oz)"},{"item":"Jojoba oil","amount":"25 g (0.9 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp), slows rancidity"}],"method":["Measure the sunflower and jojoba oils into a clean glass bottle.","Add the vitamin E oil.","Cap tightly and shake gently for 15-20 seconds to combine.","Label with the date made."],"tips":["No essential oil or fragrance at all here — a good base to hand to anyone who reacts to scented products.","If you want a trace of scent later, you can add 5-10 drops of a gentle essential oil like chamomile to a small portion, rather than the whole bottle."],"safety_note":null,"keywords":["body oil","unscented","sensitive skin","fragrance-free","sunflower oil","jojoba","gentle"],"pdf":"../../body-oil-recipes/g65gssg2kj/body-oil-recipes.pdf"},{"slug":"spiced-chai-body-oil","title":"Spiced Chai Body Oil","cat":"body-oil","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"6-12 months at room temperature, away from direct sunlight.","ingredients":[{"item":"Sweet almond oil","amount":"95 g (3.3 oz)"},{"item":"Fractionated coconut oil","amount":"20 g (0.7 oz)"},{"item":"Vitamin E oil","amount":"2 g (about 1/3 tsp), slows rancidity"},{"item":"Cinnamon leaf essential oil","amount":"5 drops (about 0.25 g) — keep to this amount, cinnamon is a known skin irritant at higher doses"},{"item":"Clove bud essential oil","amount":"3 drops (about 0.15 g)"}],"method":["Measure the almond and fractionated coconut oils into a clean glass bottle.","Add the vitamin E oil.","Add the cinnamon leaf and clove bud essential oils last, counting drops carefully.","Cap tightly and shake gently for 15-20 seconds to combine.","Label clearly with the date made and that it contains cinnamon."],"tips":["Cinnamon leaf oil is one of the most irritating essential oils used on skin — don't be tempted to add more for a stronger scent.","If you still feel warmth or tingling after the patch test, cut the cinnamon to 2-3 drops next batch."],"safety_note":"Cinnamon leaf and clove bud essential oils are strong skin irritants even at small amounts. Do a patch test on your inner arm and wait 48 hours before using on your whole body, and never increase the drop counts above.","keywords":["body oil","spiced oil","cinnamon","clove","chai scent","fall","holiday"],"pdf":"../../body-oil-recipes/g65gssg2kj/body-oil-recipes.pdf"},{"slug":"rosehip-lavender-renewal-oil","title":"Rosehip Lavender Renewal Oil","cat":"body-oil","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"6-12 months at room temperature, away from direct sunlight — rosehip oil oxidizes a bit faster than other carrier oils, so use it up within this window for the best texture and smell.","ingredients":[{"item":"Rosehip seed oil","amount":"60 g (2.1 oz)"},{"item":"Sweet almond oil","amount":"50 g (1.8 oz)"},{"item":"Vitamin E oil","amount":"3 g (about 1/2 tsp), slows rancidity"},{"item":"Lavender essential oil","amount":"20 drops (about 1 g)"}],"method":["Measure the rosehip and almond oils into a clean glass bottle.","Add the vitamin E oil and the lavender essential oil.","Cap tightly and shake gently for 15-20 seconds to combine.","Store in a dark or amber bottle if you have one — rosehip oil is sensitive to light."],"tips":["Rosehip oil has a natural earthy-nutty smell; lavender softens it without masking it completely.","If the oil starts smelling sharp or like crayons, it has gone rancid — toss it and make a fresh batch."],"safety_note":"Essential oils are concentrated. Do a patch test on your inner arm and wait 24 hours before using a new blend on your whole body.","keywords":["body oil","rosehip oil","lavender","dry oil","evening routine","gift","anhydrous"],"pdf":"../../body-oil-recipes/g65gssg2kj/body-oil-recipes.pdf"},{"slug":"coconut-vanilla-summer-glow-oil","title":"Coconut Vanilla Summer Glow Oil","cat":"body-oil","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"6-12 months at room temperature. No water in this recipe, so no preservative is needed.","ingredients":[{"item":"Fractionated coconut oil","amount":"100 g (3.5 oz)"},{"item":"Vitamin E oil","amount":"2 g (about 1/3 tsp), slows rancidity"},{"item":"Skin-safe vanilla fragrance oil","amount":"5 g (1 tsp)"},{"item":"Cosmetic-grade bronze mica powder (optional)","amount":"1 g (about 1/4 tsp)"}],"method":["Measure the fractionated coconut oil into a clean glass bottle.","Add the vitamin E oil and vanilla fragrance oil.","If using mica, add it last and shake hard for 30 seconds to suspend it.","Label with the date made; shake before each use."],"tips":["Fractionated coconut oil stays liquid at room temperature (unlike regular coconut oil), so this pours easily even in a cool bathroom.","Skip the mica for a plain glow-free version — the vanilla scent works either way."],"safety_note":null,"keywords":["body oil","coconut oil","vanilla","summer glow","shimmer","bronze","beach"],"pdf":"../../body-oil-recipes/g65gssg2kj/body-oil-recipes.pdf"},{"slug":"herbal-rosemary-mint-body-oil","title":"Herbal Rosemary Mint Body Oil","cat":"body-oil","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"6-12 months at room temperature, away from direct sunlight.","ingredients":[{"item":"Grapeseed oil","amount":"90 g (3.2 oz)"},{"item":"Sweet almond oil","amount":"20 g (0.7 oz)"},{"item":"Rosemary essential oil","amount":"15 drops (about 0.75 g)"},{"item":"Peppermint essential oil","amount":"10 drops (about 0.5 g)"}],"method":["Measure the grapeseed and almond oils into a clean glass bottle.","Add the rosemary and peppermint essential oils.","Cap tightly and shake gently for 15-20 seconds to combine.","Label with the date made."],"tips":["This blend is meant to feel invigorating, not sleepy — good for a midday application instead of bedtime.","Rosemary essential oil is one many people are advised to avoid in pregnancy or with seizure disorders — check with a doctor if either applies to you."],"safety_note":"Essential oils are concentrated. Do a patch test on your inner arm and wait 24 hours before using a new blend on your whole body.","keywords":["body oil","rosemary","peppermint","herbal oil","invigorating","midday","dry oil"],"pdf":"../../body-oil-recipes/g65gssg2kj/body-oil-recipes.pdf"},{"slug":"golden-shimmer-body-oil","title":"Golden Shimmer Body Oil","cat":"body-oil","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"6-12 months at room temperature. No water in this recipe, so no preservative is needed.","ingredients":[{"item":"Fractionated coconut oil","amount":"85 g (3 oz)"},{"item":"Sweet almond oil","amount":"25 g (0.9 oz)"},{"item":"Ylang ylang essential oil","amount":"10 drops (about 0.5 g)"},{"item":"Cosmetic-grade gold mica powder","amount":"2 g (about 1/2 tsp)"}],"method":["Measure the fractionated coconut oil and almond oil into a clean glass bottle.","Add the ylang ylang essential oil.","Add the gold mica and shake hard for 30-45 seconds until it's evenly suspended.","Label with the date made; shake before every use since the mica settles on the shelf."],"tips":["Use only mica labeled cosmetic-grade and meant for skin — never a craft or candle mica, which isn't tested for skin contact.","Pour a little into your palm first and rub hands together before applying, so the shimmer distributes evenly instead of landing in one streak."],"safety_note":"Essential oils are concentrated. Do a patch test on your inner arm and wait 24 hours before using a new blend on your whole body.","keywords":["body oil","shimmer","highlighter oil","gold mica","ylang ylang","special occasion","glow"],"pdf":"../../body-oil-recipes/g65gssg2kj/body-oil-recipes.pdf"},{"slug":"jasmine-silk-body-oil","title":"Jasmine Silk Body Oil","cat":"body-oil","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"6-12 months at room temperature, away from direct sunlight.","ingredients":[{"item":"Sweet almond oil","amount":"90 g (3.2 oz)"},{"item":"Jojoba oil","amount":"25 g (0.9 oz)"},{"item":"Vitamin E oil","amount":"2 g (about 1/3 tsp), slows rancidity"},{"item":"Jasmine absolute essential oil","amount":"8 drops (about 0.4 g) — jasmine is strong and expensive, a little goes a long way"}],"method":["Measure the almond and jojoba oils into a clean glass bottle.","Add the vitamin E oil.","Add the jasmine absolute, counting drops carefully.","Cap tightly and shake gently for 15-20 seconds to combine."],"tips":["Jasmine absolute is one of the more costly essential oils — this low drop count still gives a noticeable, rich floral scent.","Let the bottle rest a day before judging the scent strength; jasmine mellows and rounds out as it sits."],"safety_note":"Essential oils are concentrated. Do a patch test on your inner arm and wait 24 hours before using a new blend on your whole body.","keywords":["body oil","jasmine","floral oil","silk oil","evening scent","gift","luxury"],"pdf":"../../body-oil-recipes/g65gssg2kj/body-oil-recipes.pdf"},{"slug":"sandalwood-amyris-body-oil","title":"Sandalwood Amyris Body Oil","cat":"body-oil","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"6-12 months at room temperature, away from direct sunlight.","ingredients":[{"item":"Jojoba oil","amount":"90 g (3.2 oz)"},{"item":"Fractionated coconut oil","amount":"20 g (0.7 oz)"},{"item":"Sandalwood essential oil","amount":"15 drops (about 0.75 g)"},{"item":"Amyris essential oil","amount":"10 drops (about 0.5 g)"}],"method":["Measure the jojoba and fractionated coconut oils into a clean glass bottle.","Add the sandalwood and amyris essential oils.","Cap tightly and shake gently for 15-20 seconds to combine.","Label with the date made."],"tips":["Amyris is sometimes called 'poor man's sandalwood' — blending the two stretches a smaller amount of real sandalwood further without losing the woody base note.","This scent reads unisex — a good one to offer as a gift without guessing a recipient's preference."],"safety_note":"Essential oils are concentrated. Do a patch test on your inner arm and wait 24 hours before using a new blend on your whole body.","keywords":["body oil","sandalwood","amyris","woody scent","unisex","dry oil","gift"],"pdf":"../../body-oil-recipes/g65gssg2kj/body-oil-recipes.pdf"},{"slug":"winter-frankincense-myrrh-oil","title":"Winter Frankincense Myrrh Oil","cat":"body-oil","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"6-12 months at room temperature, away from direct sunlight.","ingredients":[{"item":"Argan oil","amount":"60 g (2.1 oz)"},{"item":"Sweet almond oil","amount":"40 g (1.4 oz)"},{"item":"Frankincense essential oil","amount":"15 drops (about 0.75 g)"},{"item":"Myrrh essential oil","amount":"10 drops (about 0.5 g)"}],"method":["Measure the argan and almond oils into a clean glass bottle.","Add the frankincense and myrrh essential oils.","Cap tightly and shake gently for 15-20 seconds to combine.","Label with the date made."],"tips":["This deep, resinous scent pairs well with the richer feel of argan oil — a good pick for the driest winter months.","Warm the bottle briefly between your palms before pouring in cold weather; both oils flow more easily at skin temperature."],"safety_note":"Essential oils are concentrated. Do a patch test on your inner arm and wait 24 hours before using a new blend on your whole body.","keywords":["body oil","frankincense","myrrh","winter oil","resinous scent","holiday gift","dry oil"],"pdf":"../../body-oil-recipes/g65gssg2kj/body-oil-recipes.pdf"},{"slug":"tropical-coconut-lime-body-oil","title":"Tropical Coconut Lime Body Oil","cat":"body-oil","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"6-12 months at room temperature, away from direct sunlight.","ingredients":[{"item":"Fractionated coconut oil","amount":"95 g (3.3 oz)"},{"item":"Sweet almond oil","amount":"20 g (0.7 oz)"},{"item":"Lime essential oil","amount":"15 drops (about 0.75 g)"},{"item":"Skin-safe coconut fragrance oil","amount":"2 g (about 1/3 tsp)"}],"method":["Measure the fractionated coconut oil and almond oil into a clean glass bottle.","Add the lime essential oil and coconut fragrance oil.","Cap tightly and shake gently for 15-20 seconds to combine.","Label with the date made."],"tips":["This one is built for travel-size bottles — fractionated coconut oil won't solidify in a cool bag like regular coconut oil would.","Apply the night before a beach day, or reapply in the evening, to work around the sun-sensitivity window from the lime oil."],"safety_note":"Contains lime essential oil, which is phototoxic. Do a patch test on your inner arm, wait 24 hours, and avoid direct sun exposure on treated skin for several hours after applying.","keywords":["body oil","coconut lime","tropical","summer oil","vacation","beach","dry oil"],"pdf":"../../body-oil-recipes/g65gssg2kj/body-oil-recipes.pdf"},{"slug":"calming-chamomile-infused-body-oil","title":"Calming Chamomile Infused Body Oil","cat":"body-oil","time":"25 min active (includes a gentle warm infusion), no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"6-12 months at room temperature, away from direct sunlight.","ingredients":[{"item":"Sunflower oil","amount":"90 g (3.2 oz)"},{"item":"Dried chamomile flowers","amount":"10 g (about 1/4 cup)"},{"item":"Jojoba oil","amount":"25 g (0.9 oz)"},{"item":"Lavender essential oil","amount":"10 drops (about 0.5 g)"}],"method":["Combine the sunflower oil and dried chamomile flowers in a heatproof glass jar.","Set the jar in a saucepan with 1-2 in (2-3 cm) of water over the lowest heat, water not touching the jar's rim, and let it infuse for 20 min, checking occasionally that the water hasn't boiled off.","Remove from heat and let cool to room temperature, about 20-30 min.","Strain through a fine mesh strainer or cheesecloth into a clean bottle, pressing the flowers to get the last of the oil out.","Stir in the jojoba oil and lavender essential oil.","Label with the date made."],"tips":["Keep the water at a bare simmer, not a boil — overheating the oil can scorch the chamomile and turn the scent bitter.","Strain thoroughly: any leftover plant material in the bottle can introduce moisture and shorten shelf life."],"safety_note":"Chamomile is in the ragweed family and can trigger a reaction in people with ragweed allergies. Do a patch test on your inner arm and wait 24 hours before using on your whole body.","keywords":["body oil","chamomile","infused oil","calming","lavender","sensitive skin","evening"],"pdf":"../../body-oil-recipes/g65gssg2kj/body-oil-recipes.pdf"},{"slug":"muscle-relief-massage-oil-blend","title":"Muscle Relief Massage Oil Blend","cat":"body-oil","time":"5 min active, no cook time","batch_size":"about 8 fl oz (240 ml)","shelf_life":"6-12 months at room temperature, away from direct sunlight.","ingredients":[{"item":"Grapeseed oil","amount":"160 g (5.6 oz)"},{"item":"Sweet almond oil","amount":"60 g (2.1 oz)"},{"item":"Eucalyptus essential oil","amount":"15 drops (about 0.75 g)"},{"item":"Marjoram essential oil","amount":"10 drops (about 0.5 g)"}],"method":["Measure the grapeseed and almond oils into a clean glass bottle or pump bottle.","Add the eucalyptus and marjoram essential oils.","Cap tightly and shake gently for 15-20 seconds to combine.","Label with the date made."],"tips":["Grapeseed oil has enough slip for massage work without feeling greasy, which is why it's the larger share of this blend.","Warm the bottle in a cup of warm (not hot) water for a few minutes before a massage — cold oil straight from storage can feel jarring on bare skin."],"safety_note":"Essential oils are concentrated. Do a patch test on your inner arm and wait 24 hours before using on your whole body, and avoid broken or irritated skin.","keywords":["massage oil","body oil","eucalyptus","marjoram","muscle relief","post-workout","large batch"],"pdf":"../../body-oil-recipes/g65gssg2kj/body-oil-recipes.pdf"},{"slug":"rose-mosqueta-geranium-glow-oil","title":"Rose Mosqueta Geranium Glow Oil","cat":"body-oil","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"6-12 months at room temperature, away from direct sunlight — rosehip (rosa mosqueta) oil oxidizes faster than more stable carrier oils, so use within this window.","ingredients":[{"item":"Rosehip seed oil (rosa mosqueta)","amount":"70 g (2.5 oz)"},{"item":"Apricot kernel oil","amount":"40 g (1.4 oz)"},{"item":"Geranium essential oil","amount":"20 drops (about 1 g)"},{"item":"Cosmetic-grade rose mica powder (optional)","amount":"1 g (about 1/4 tsp)"}],"method":["Measure the rosehip and apricot kernel oils into a clean glass bottle.","Add the geranium essential oil.","If using mica, add it last and shake hard for 30 seconds to suspend it.","Store in a dark or amber bottle if you have one; shake before each use."],"tips":["Apricot kernel oil is lighter than rosehip alone, which keeps this from feeling heavy despite the rich base oil.","Skip the mica for a clearer, faster-absorbing version — the geranium-rose scent still comes through."],"safety_note":"Essential oils are concentrated. Do a patch test on your inner arm and wait 24 hours before using a new blend on your whole body.","keywords":["body oil","rosehip oil","rosa mosqueta","geranium","glow oil","shimmer","gift"],"pdf":"../../body-oil-recipes/g65gssg2kj/body-oil-recipes.pdf"},{"slug":"bergamot-fig-body-oil","title":"Bergamot Fig Body Oil","cat":"body-oil","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"6-12 months at room temperature, away from direct sunlight.","ingredients":[{"item":"Sweet almond oil","amount":"90 g (3.2 oz)"},{"item":"Fractionated coconut oil","amount":"25 g (0.9 oz)"},{"item":"Bergamot essential oil (bergapten-free / FCF, if available, is the lower-risk choice)","amount":"12 drops (about 0.6 g)"},{"item":"Skin-safe fig fragrance oil","amount":"3 g (about 1/2 tsp)"}],"method":["Measure the almond and fractionated coconut oils into a clean glass bottle.","Add the bergamot essential oil and fig fragrance oil.","Cap tightly and shake gently for 15-20 seconds to combine.","Label clearly with the date made and a reminder to avoid sun after use."],"tips":["Bergamot is one of the most phototoxic essential oils used in skincare — an FCF (furanocoumarin-free) version removes most of that risk if you can find one.","This is best worn in the evening, when there's no risk of sun exposure before it fully absorbs."],"safety_note":"Bergamot essential oil is strongly phototoxic and can cause burns or dark spots on skin exposed to sunlight or tanning beds within 12-24 hours of application. Do a patch test on your inner arm, wait 24 hours, and avoid any sun exposure on treated skin during that window.","keywords":["body oil","bergamot","fig","evening scent","citrus woody","dry oil","gift"],"pdf":"../../body-oil-recipes/g65gssg2kj/body-oil-recipes.pdf"},{"slug":"milk-and-honey-dry-oil","title":"Milk and Honey Dry Oil","cat":"body-oil","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"6-12 months at room temperature. No water or real honey in this recipe — the scent comes from a fragrance oil — so no preservative is needed.","ingredients":[{"item":"Sunflower oil","amount":"90 g (3.2 oz)"},{"item":"Fractionated coconut oil","amount":"25 g (0.9 oz)"},{"item":"Vitamin E oil","amount":"2 g (about 1/3 tsp), slows rancidity"},{"item":"Skin-safe milk-and-honey type fragrance oil","amount":"5 g (1 tsp)"}],"method":["Measure the sunflower and fractionated coconut oils into a clean glass bottle.","Add the vitamin E oil and the fragrance oil.","Cap tightly and shake gently for 15-20 seconds to combine.","Let it rest for 24 hours before first use so the scent settles in."],"tips":["Real honey has enough water content that it doesn't belong in an anhydrous oil — this fragrance oil gives the same cozy scent without introducing water or needing a preservative.","This is a mild, gentle scent profile, a good one to offer alongside stronger essential-oil blends for people who prefer something softer."],"safety_note":null,"keywords":["body oil","milk and honey","dry oil","gentle scent","gift","fragrance oil","anhydrous"],"pdf":"../../body-oil-recipes/g65gssg2kj/body-oil-recipes.pdf"},{"slug":"patchouli-cedarwood-earth-oil","title":"Patchouli Cedarwood Earth Oil","cat":"body-oil","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"6-12 months at room temperature, away from direct sunlight.","ingredients":[{"item":"Jojoba oil","amount":"85 g (3 oz)"},{"item":"Grapeseed oil","amount":"25 g (0.9 oz)"},{"item":"Patchouli essential oil","amount":"15 drops (about 0.75 g)"},{"item":"Cedarwood essential oil","amount":"10 drops (about 0.5 g)"}],"method":["Measure the jojoba and grapeseed oils into a clean glass bottle.","Add the patchouli and cedarwood essential oils.","Cap tightly and shake gently for 15-20 seconds to combine.","Label with the date made."],"tips":["Patchouli actually improves with a little age — if you have time, let this sit for a week before using for a rounder, less sharp scent.","This earthy, grounding blend works well for an autumn-scented batch if you're organizing recipes by season."],"safety_note":"Essential oils are concentrated. Do a patch test on your inner arm and wait 24 hours before using a new blend on your whole body.","keywords":["body oil","patchouli","cedarwood","earthy scent","autumn","unisex","dry oil"],"pdf":"../../body-oil-recipes/g65gssg2kj/body-oil-recipes.pdf"},{"slug":"clary-sage-lavender-calm-oil","title":"Clary Sage Lavender Calm Oil","cat":"body-oil","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"6-12 months at room temperature, away from direct sunlight.","ingredients":[{"item":"Sweet almond oil","amount":"90 g (3.2 oz)"},{"item":"Sunflower oil","amount":"25 g (0.9 oz)"},{"item":"Clary sage essential oil","amount":"15 drops (about 0.75 g)"},{"item":"Lavender essential oil","amount":"10 drops (about 0.5 g)"}],"method":["Measure the almond and sunflower oils into a clean glass bottle.","Add the clary sage and lavender essential oils.","Cap tightly and shake gently for 15-20 seconds to combine.","Label with the date made."],"tips":["This blend leans calming rather than energizing — a good evening or wind-down oil rather than a morning one.","Clary sage is generally advised against during pregnancy — check with a doctor first if that applies to you."],"safety_note":"Essential oils are concentrated. Do a patch test on your inner arm and wait 24 hours before using a new blend on your whole body. Avoid clary sage essential oil during pregnancy unless a doctor has cleared it.","keywords":["body oil","clary sage","lavender","calming oil","evening routine","relax","dry oil"],"pdf":"../../body-oil-recipes/g65gssg2kj/body-oil-recipes.pdf"},{"slug":"cucumber-melon-cooling-body-oil","title":"Cucumber Melon Cooling Body Oil","cat":"body-oil","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"6-12 months at room temperature. No water in this recipe, so no preservative is needed.","ingredients":[{"item":"Fractionated coconut oil","amount":"95 g (3.3 oz)"},{"item":"Grapeseed oil","amount":"20 g (0.7 oz)"},{"item":"Vitamin E oil","amount":"2 g (about 1/3 tsp), slows rancidity"},{"item":"Skin-safe cucumber-melon fragrance oil","amount":"5 g (1 tsp)"}],"method":["Measure the fractionated coconut oil and grapeseed oil into a clean glass bottle.","Add the vitamin E oil and the cucumber-melon fragrance oil.","Cap tightly and shake gently for 15-20 seconds to combine.","Label with the date made."],"tips":["This light, fast-absorbing combination layers well under clothes without feeling sticky in warm weather.","No essential oil here, so this is a good summer option for anyone avoiding sun-sensitizing citrus oils."],"safety_note":null,"keywords":["body oil","cucumber melon","summer oil","light oil","fragrance oil","fresh scent","gift"],"pdf":"../../body-oil-recipes/g65gssg2kj/body-oil-recipes.pdf"},{"slug":"lavender-chamomile-sleep-mist","title":"Lavender Chamomile Sleep Mist","cat":"body-spray","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"About 6 months at room temperature. The high alcohol content helps keep it fresh, but it still contains water, so don't stretch it past 6 months, and stop using it if the smell changes.","ingredients":[{"item":"High-proof unflavored vodka or perfumer's alcohol (at least 80 proof / 40% alcohol)","amount":"65 g (2.3 oz)"},{"item":"Distilled water","amount":"45 g (1.6 oz)"},{"item":"Polysorbate 20 (helps the essential oils mix into the water instead of floating on top)","amount":"5 g (1 tsp)"},{"item":"Lavender essential oil","amount":"25 drops"},{"item":"Roman chamomile essential oil","amount":"10 drops"}],"method":["In a small bowl, mix the polysorbate 20 with the lavender and chamomile essential oils first, stirring until fully blended.","Add the alcohol and stir again.","Add the distilled water last, stirring gently.","Pour into a fine-mist spray bottle through a small funnel.","Shake before each use."],"tips":["Mixing the oils into the polysorbate before adding any liquid keeps the spray clear instead of cloudy with floating droplets.","Mist over pajamas or bedding rather than directly on skin close to the eyes."],"safety_note":"This spray contains alcohol: keep it away from open flame, and avoid spraying directly onto broken or irritated skin.","keywords":["body spray","sleep mist","lavender","chamomile","bedtime","relaxing","linen spray"],"pdf":"../../body-spray-recipes/352csvv5aw/body-spray-recipes.pdf"},{"slug":"rose-geranium-body-mist","title":"Rose Geranium Body Mist","cat":"body-spray","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"About 6 months at room temperature. The high alcohol content helps keep it fresh, but it still contains water, so don't stretch it past 6 months, and stop using it if the smell changes.","ingredients":[{"item":"High-proof unflavored vodka or perfumer's alcohol (at least 80 proof / 40% alcohol)","amount":"65 g (2.3 oz)"},{"item":"Distilled water","amount":"45 g (1.6 oz)"},{"item":"Polysorbate 20","amount":"5 g (1 tsp)"},{"item":"Geranium essential oil","amount":"25 drops"},{"item":"Palmarosa essential oil","amount":"10 drops"}],"method":["In a small bowl, mix the polysorbate 20 with the geranium and palmarosa essential oils, stirring until fully blended.","Add the alcohol and stir again.","Add the distilled water last, stirring gently.","Pour into a fine-mist spray bottle through a small funnel.","Shake before each use."],"tips":["Palmarosa has a rose-like note that stretches the scent without needing true rose oil, which is far more expensive.","Let the bottle sit for 24-48 hours before judging the scent — it mellows and blends as it rests."],"safety_note":"This spray contains alcohol: keep it away from open flame, and avoid spraying directly onto broken or irritated skin.","keywords":["body spray","body mist","rose","geranium","floral","everyday perfume","romantic"],"pdf":"../../body-spray-recipes/352csvv5aw/body-spray-recipes.pdf"},{"slug":"grapefruit-basil-body-spray","title":"Grapefruit Basil Body Spray","cat":"body-spray","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"About 6 months at room temperature. The high alcohol content helps keep it fresh, but it still contains water, so don't stretch it past 6 months, and stop using it if the smell changes.","ingredients":[{"item":"High-proof unflavored vodka or perfumer's alcohol (at least 80 proof / 40% alcohol)","amount":"65 g (2.3 oz)"},{"item":"Distilled water","amount":"45 g (1.6 oz)"},{"item":"Polysorbate 20","amount":"5 g (1 tsp)"},{"item":"Grapefruit essential oil","amount":"25 drops"},{"item":"Basil essential oil","amount":"10 drops"}],"method":["In a small bowl, mix the polysorbate 20 with the grapefruit and basil essential oils, stirring until fully blended.","Add the alcohol and stir again.","Add the distilled water last, stirring gently.","Pour into a fine-mist spray bottle through a small funnel.","Shake before each use."],"tips":["This bright, green-citrus combination works well as a morning pick-me-up sprayed on arms and chest before heading out.","Citrus essential oils fade faster than woody or floral ones — if the scent feels weak after a few months, that's normal, not spoilage."],"safety_note":"This spray contains alcohol and phototoxic citrus oil: keep it away from open flame, avoid spraying directly onto broken or irritated skin, and avoid direct sun exposure on treated skin for a few hours after use.","keywords":["body spray","grapefruit","basil","citrus mist","morning spray","fresh scent","summer"],"pdf":"../../body-spray-recipes/352csvv5aw/body-spray-recipes.pdf"},{"slug":"lemon-verbena-refresh-spray","title":"Lemon Verbena Refresh Spray","cat":"body-spray","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"About 6 months at room temperature. The high alcohol content helps keep it fresh, but it still contains water, so don't stretch it past 6 months, and stop using it if the smell changes.","ingredients":[{"item":"High-proof unflavored vodka or perfumer's alcohol (at least 80 proof / 40% alcohol)","amount":"65 g (2.3 oz)"},{"item":"Distilled water","amount":"45 g (1.6 oz)"},{"item":"Polysorbate 20","amount":"5 g (1 tsp)"},{"item":"Lemon verbena essential oil (or lemongrass as a substitute)","amount":"20 drops"},{"item":"Lemon essential oil","amount":"10 drops"}],"method":["In a small bowl, mix the polysorbate 20 with the lemon verbena and lemon essential oils, stirring until fully blended.","Add the alcohol and stir again.","Add the distilled water last, stirring gently.","Pour into a fine-mist spray bottle through a small funnel.","Shake before each use."],"tips":["This is a sharper, greener citrus than orange-based sprays — a good one to offer alongside a sweeter citrus option for variety.","Store away from a sunny windowsill: light speeds up how fast citrus top notes fade."],"safety_note":"This spray contains alcohol and phototoxic citrus oil: keep it away from open flame, avoid spraying directly onto broken or irritated skin, and avoid direct sun exposure on treated skin for a few hours after use.","keywords":["body spray","lemon verbena","lemon","citrus mist","refreshing","summer spray","clean scent"],"pdf":"../../body-spray-recipes/352csvv5aw/body-spray-recipes.pdf"},{"slug":"eucalyptus-peppermint-chill-spray","title":"Eucalyptus Peppermint Chill Spray","cat":"body-spray","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"About 6 months at room temperature. The high alcohol content helps keep it fresh, but it still contains water, so don't stretch it past 6 months, and stop using it if the smell changes.","ingredients":[{"item":"High-proof unflavored vodka or perfumer's alcohol (at least 80 proof / 40% alcohol)","amount":"65 g (2.3 oz)"},{"item":"Distilled water","amount":"45 g (1.6 oz)"},{"item":"Polysorbate 20","amount":"5 g (1 tsp)"},{"item":"Eucalyptus essential oil","amount":"20 drops"},{"item":"Peppermint essential oil","amount":"15 drops"}],"method":["In a small bowl, mix the polysorbate 20 with the eucalyptus and peppermint essential oils, stirring until fully blended.","Add the alcohol and stir again.","Add the distilled water last, stirring gently.","Pour into a fine-mist spray bottle through a small funnel.","Shake before each use."],"tips":["Mist onto arms, legs or the back of the neck after a workout for a cooling effect — avoid the face and eyes.","Keep away from pets: eucalyptus and peppermint essential oils are not safe for cats and dogs."],"safety_note":"This spray contains alcohol and strong essential oils: keep it away from open flame, avoid spraying directly onto broken or irritated skin, and keep away from the eyes.","keywords":["body spray","eucalyptus","peppermint","cooling mist","post-workout","menthol","gym bag"],"pdf":"../../body-spray-recipes/352csvv5aw/body-spray-recipes.pdf"},{"slug":"rosemary-spearmint-clarity-spray","title":"Rosemary Spearmint Clarity Spray","cat":"body-spray","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"About 6 months at room temperature. The high alcohol content helps keep it fresh, but it still contains water, so don't stretch it past 6 months, and stop using it if the smell changes.","ingredients":[{"item":"High-proof unflavored vodka or perfumer's alcohol (at least 80 proof / 40% alcohol)","amount":"65 g (2.3 oz)"},{"item":"Distilled water","amount":"45 g (1.6 oz)"},{"item":"Polysorbate 20","amount":"5 g (1 tsp)"},{"item":"Rosemary essential oil","amount":"20 drops"},{"item":"Spearmint essential oil","amount":"15 drops"}],"method":["In a small bowl, mix the polysorbate 20 with the rosemary and spearmint essential oils, stirring until fully blended.","Add the alcohol and stir again.","Add the distilled water last, stirring gently.","Pour into a fine-mist spray bottle through a small funnel.","Shake before each use."],"tips":["Spearmint reads softer and sweeter than peppermint, which keeps this from feeling as sharp as a straight mint spray.","A good desk-drawer spray for a midday refresh without a full shower."],"safety_note":"This spray contains alcohol: keep it away from open flame, and avoid spraying directly onto broken or irritated skin. Rosemary essential oil is generally advised against during pregnancy or with seizure disorders — check with a doctor if either applies to you.","keywords":["body spray","rosemary","spearmint","herbal mist","midday refresh","clarity","desk spray"],"pdf":"../../body-spray-recipes/352csvv5aw/body-spray-recipes.pdf"},{"slug":"cedarwood-sage-body-spray","title":"Cedarwood Sage Body Spray","cat":"body-spray","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"About 6 months at room temperature. The high alcohol content helps keep it fresh, but it still contains water, so don't stretch it past 6 months, and stop using it if the smell changes.","ingredients":[{"item":"High-proof unflavored vodka or perfumer's alcohol (at least 80 proof / 40% alcohol)","amount":"65 g (2.3 oz)"},{"item":"Distilled water","amount":"45 g (1.6 oz)"},{"item":"Polysorbate 20","amount":"5 g (1 tsp)"},{"item":"Cedarwood essential oil","amount":"20 drops"},{"item":"Clary sage essential oil","amount":"15 drops"}],"method":["In a small bowl, mix the polysorbate 20 with the cedarwood and clary sage essential oils, stirring until fully blended.","Add the alcohol and stir again.","Add the distilled water last, stirring gently.","Pour into a fine-mist spray bottle through a small funnel.","Shake before each use."],"tips":["This woody, herbal combination reads unisex and works well as an autumn seasonal offering.","Clary sage is generally advised against during pregnancy — check with a doctor first if that applies to you."],"safety_note":"This spray contains alcohol: keep it away from open flame, and avoid spraying directly onto broken or irritated skin.","keywords":["body spray","cedarwood","clary sage","woody mist","unisex","autumn scent","earthy"],"pdf":"../../body-spray-recipes/352csvv5aw/body-spray-recipes.pdf"},{"slug":"sandalwood-vanilla-body-spray","title":"Sandalwood Vanilla Body Spray","cat":"body-spray","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"About 6 months at room temperature. The high alcohol content helps keep it fresh, but it still contains water, so don't stretch it past 6 months, and stop using it if the smell changes.","ingredients":[{"item":"High-proof unflavored vodka or perfumer's alcohol (at least 80 proof / 40% alcohol)","amount":"65 g (2.3 oz)"},{"item":"Distilled water","amount":"45 g (1.6 oz)"},{"item":"Polysorbate 20","amount":"5 g (1 tsp)"},{"item":"Sandalwood essential oil","amount":"20 drops"},{"item":"Skin-safe vanilla fragrance oil","amount":"2 g (about 1/3 tsp)"}],"method":["In a small bowl, mix the polysorbate 20 with the sandalwood essential oil and vanilla fragrance oil, stirring until fully blended.","Add the alcohol and stir again.","Add the distilled water last, stirring gently.","Pour into a fine-mist spray bottle through a small funnel.","Shake before each use."],"tips":["This warm, slightly sweet blend works well as an evening or date-night scent layered over an unscented lotion.","Let the bottle rest for a day or two before judging the balance between sandalwood and vanilla — it settles as it sits."],"safety_note":"This spray contains alcohol: keep it away from open flame, and avoid spraying directly onto broken or irritated skin.","keywords":["body spray","sandalwood","vanilla","evening scent","date night","warm mist","gift"],"pdf":"../../body-spray-recipes/352csvv5aw/body-spray-recipes.pdf"},{"slug":"coconut-lime-beach-spray","title":"Coconut Lime Beach Spray","cat":"body-spray","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"About 6 months at room temperature. The high alcohol content helps keep it fresh, but it still contains water, so don't stretch it past 6 months, and stop using it if the smell changes.","ingredients":[{"item":"High-proof unflavored vodka or perfumer's alcohol (at least 80 proof / 40% alcohol)","amount":"65 g (2.3 oz)"},{"item":"Distilled water","amount":"45 g (1.6 oz)"},{"item":"Polysorbate 20","amount":"5 g (1 tsp)"},{"item":"Lime essential oil","amount":"15 drops"},{"item":"Skin-safe coconut fragrance oil","amount":"3 g (about 1/2 tsp)"}],"method":["In a small bowl, mix the polysorbate 20 with the lime essential oil and coconut fragrance oil, stirring until fully blended.","Add the alcohol and stir again.","Add the distilled water last, stirring gently.","Pour into a fine-mist spray bottle through a small funnel.","Shake before each use."],"tips":["Mist over already-applied sunscreen, not instead of it — this spray has no SPF of its own.","A good one to pack in a carry-on: it's under typical liquid limits in a 4 fl oz travel bottle."],"safety_note":"This spray contains alcohol and phototoxic lime oil: keep it away from open flame, avoid spraying directly onto broken or irritated skin, and avoid direct sun exposure on treated skin for a few hours after use.","keywords":["body spray","coconut lime","beach spray","tropical","summer mist","vacation","travel size"],"pdf":"../../body-spray-recipes/352csvv5aw/body-spray-recipes.pdf"},{"slug":"pineapple-coconut-cooler-spray","title":"Pineapple Coconut Cooler Spray","cat":"body-spray","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"About 6 months at room temperature. The high alcohol content helps keep it fresh, but it still contains water, so don't stretch it past 6 months, and stop using it if the smell changes.","ingredients":[{"item":"High-proof unflavored vodka or perfumer's alcohol (at least 80 proof / 40% alcohol)","amount":"65 g (2.3 oz)"},{"item":"Distilled water","amount":"45 g (1.6 oz)"},{"item":"Polysorbate 20","amount":"5 g (1 tsp)"},{"item":"Skin-safe pineapple-coconut fragrance oil","amount":"4 g (about 3/4 tsp)"},{"item":"Sweet orange essential oil","amount":"10 drops"}],"method":["In a small bowl, mix the polysorbate 20 with the pineapple-coconut fragrance oil and orange essential oil, stirring until fully blended.","Add the alcohol and stir again.","Add the distilled water last, stirring gently.","Pour into a fine-mist spray bottle through a small funnel.","Shake before each use."],"tips":["This one leans sweet and fruity rather than true citrus — the small amount of orange oil just brightens the fragrance oil's base.","A fun poolside or summer-party option alongside the more classic citrus sprays."],"safety_note":"This spray contains alcohol: keep it away from open flame, and avoid spraying directly onto broken or irritated skin.","keywords":["body spray","pineapple coconut","summer mist","poolside","fruity scent","tropical","fun scent"],"pdf":"../../body-spray-recipes/352csvv5aw/body-spray-recipes.pdf"},{"slug":"ylang-ylang-jasmine-night-spray","title":"Ylang Ylang Jasmine Night Spray","cat":"body-spray","time":"5 min active, no cook time","batch_size":"about 4 fl oz (120 ml)","shelf_life":"About 6 months at room temperature. The high alcohol content helps keep it fresh, but it still contains water, so don't stretch it past 6 months, and stop using it if the smell changes.","ingredients":[{"item":"High-proof unflavored vodka or perfumer's alcohol (at least 80 proof / 40% alcohol)","amount":"65 g (2.3 oz)"},{"item":"Distilled water","amount":"45 g (1.6 oz)"},{"item":"Polysorbate 20","amount":"5 g (1 tsp)"},{"item":"Ylang ylang essential oil","amount":"20 drops"},{"item":"Jasmine absolute essential oil","amount":"8 drops — jasmine is strong and expensive, a little goes a long way"}],"method":["In a small bowl, mix the polysorbate 20 with the ylang ylang and jasmine essential oils, stirring until fully blended.","Add the alcohol and stir again.","Add the distilled water last, stirring gently.","Pour into a fine-mist spray bottle through a small funnel.","Shake before each use."],"tips":["This rich floral blend is strong — one or two mists goes further than you'd expect, especially in a warm room.","A good special-occasion or date-night spray rather than an everyday one, both for intensity and cost of the jasmine."],"safety_note":"This spray contains alcohol: keep it away from open flame, and avoid spraying directly onto broken or irritated skin.","keywords":["body spray","ylang ylang","jasmine","floral mist","special occasion","date night","evening scent"],"pdf":"../../body-spray-recipes/352csvv5aw/body-spray-recipes.pdf"},{"slug":"brown-sugar-vanilla-bean-emulsified-scrub","title":"Brown Sugar Vanilla Bean Emulsified Scrub","cat":"emulsified-scrub","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"3 months at room temperature, needs a preservative. This recipe contains water, so it needs a broad-spectrum preservative (see ingredients). Without the correct preservative at the correct dose, a water-containing scrub like this can grow mold or bacteria within days — never skip it or substitute it with vitamin E, which is an antioxidant, not a preservative.","ingredients":[{"item":"Emulsifying wax NF","amount":"15 g (0.5 oz)"},{"item":"Sweet almond oil","amount":"60 g (2.1 oz)"},{"item":"Distilled water","amount":"40 g (1.4 oz)"},{"item":"Light brown sugar","amount":"100 g (3.5 oz)"},{"item":"Broad-spectrum preservative (a liquid preservative rated for water-containing scrubs, used at the rate its own label states)","amount":"per label — typically 0.5-1 g"},{"item":"Vanilla bean fragrance oil (or the scraped seeds of 1 vanilla bean for flecks)","amount":"3 g (about 1/2 tsp)"}],"method":["Set up a double boiler: a heatproof bowl over a pot with 1-2 in (2-3 cm) of simmering water, bowl not touching the water.","Melt the emulsifying wax and almond oil together, stirring, until fully clear (about 5 min).","In a separate cup, warm the distilled water to roughly the same temperature as the oil (aim for 160-170°F / 70-77°C on both, checked with a thermometer).","Pour the warm water into the oil mixture in a thin stream, stirring constantly, until it turns opaque and creamy.","Let it cool to under 110°F (43°C) before continuing — adding the preservative while too hot can break it down.","Stir in the preservative at the exact rate its label specifies, then the vanilla fragrance oil.","Fold in the brown sugar once the base is thick enough that the sugar won't sink.","Spoon into a jar and label with the date made."],"tips":["Brown sugar holds more moisture than white sugar, so the scrub will look slightly wetter at first — it firms up as it fully cools.","Always add the preservative after cooling, at the rate its own label states; more is not safer, it just follows what was tested to work."],"safety_note":"This scrub contains water and must be preserved correctly, used within its stated shelf life, and kept out of reach of children. Discontinue use if it changes smell, color or texture.","keywords":["brown sugar scrub","vanilla","emulsified scrub","body scrub","exfoliating","foaming scrub"],"pdf":"../../emulsified-body-scrub-recipes/ak8qdjexea/emulsified-body-scrub-recipes.pdf"},{"slug":"french-rose-clay-emulsified-scrub","title":"French Rose Clay Emulsified Scrub","cat":"emulsified-scrub","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"3 months at room temperature, needs a preservative. This recipe contains water, so it needs a broad-spectrum preservative (see ingredients). Without the correct preservative at the correct dose, it can grow mold or bacteria within days — never skip it.","ingredients":[{"item":"Emulsifying wax NF","amount":"15 g (0.5 oz)"},{"item":"Jojoba oil","amount":"60 g (2.1 oz)"},{"item":"Distilled water","amount":"40 g (1.4 oz)"},{"item":"White granulated sugar","amount":"90 g (3.2 oz)"},{"item":"French rose clay (or pink kaolin clay)","amount":"10 g (0.35 oz)"},{"item":"Broad-spectrum preservative (per its own label)","amount":"per label — typically 0.5-1 g"},{"item":"Rose geranium essential oil","amount":"15 drops"}],"method":["Set up a double boiler and melt the emulsifying wax and jojoba oil together until clear (about 5 min).","Warm the distilled water separately to about the same temperature (160-170°F / 70-77°C).","Pour the warm water into the oil mixture in a thin stream, stirring constantly, until creamy and opaque.","Cool the base to under 110°F (43°C), checking with a thermometer.","Stir in the preservative at the label's stated rate, then the rose geranium essential oil.","Sprinkle in the rose clay and whisk until the color is even, with no dry pockets.","Fold in the sugar once the base is thick enough to suspend it.","Spoon into a jar and label with the date made."],"tips":["Add the clay a little at a time and whisk well — it clumps fast if dumped in all at once.","Stir the jar's contents before each use if the clay settles toward the bottom over time."],"safety_note":"This scrub contains water and must be preserved correctly, used within its stated shelf life, and kept out of reach of children. Discontinue use if it changes smell, color or texture.","keywords":["rose clay scrub","french clay","sugar scrub","floral scrub","emulsified scrub","pink scrub"],"pdf":"../../emulsified-body-scrub-recipes/ak8qdjexea/emulsified-body-scrub-recipes.pdf"},{"slug":"coconut-lime-emulsified-scrub","title":"Coconut Lime Emulsified Scrub","cat":"emulsified-scrub","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"3 months at room temperature, needs a preservative. This recipe contains water, so it needs a broad-spectrum preservative (see ingredients). Without the correct preservative at the correct dose, it can grow mold or bacteria within days — never skip it.","ingredients":[{"item":"Emulsifying wax NF","amount":"15 g (0.5 oz)"},{"item":"Fractionated coconut oil","amount":"60 g (2.1 oz)"},{"item":"Distilled water","amount":"40 g (1.4 oz)"},{"item":"White granulated sugar","amount":"100 g (3.5 oz)"},{"item":"Broad-spectrum preservative (per its own label)","amount":"per label — typically 0.5-1 g"},{"item":"Coconut fragrance oil","amount":"2 g (about 1/3 tsp)"},{"item":"Steam-distilled lime essential oil (not cold-pressed, which is phototoxic)","amount":"10 drops"}],"method":["Set up a double boiler and melt the emulsifying wax and coconut oil together until clear (about 5 min).","Warm the distilled water separately to about 160-170°F (70-77°C).","Pour the warm water into the oil mixture in a thin stream, stirring constantly, until creamy.","Cool the base to under 110°F (43°C).","Stir in the preservative at the label's stated rate, then the coconut fragrance oil and lime essential oil.","Fold in the sugar once the base is thick enough to hold it.","Spoon into a jar and label with the date made."],"tips":["Use steam-distilled lime, not cold-pressed — cold-pressed citrus oils can make skin more sensitive to sunburn.","If the scent fades fast, fragrance and essential oils can evaporate a little in the warm pour — add them right after cooling, not before."],"safety_note":"This scrub contains water and must be preserved correctly, used within its stated shelf life, and kept out of reach of children. Discontinue use if it changes smell, color or texture.","keywords":["coconut scrub","lime scrub","tropical scrub","sugar scrub","emulsified scrub","summer scrub"],"pdf":"../../emulsified-body-scrub-recipes/ak8qdjexea/emulsified-body-scrub-recipes.pdf"},{"slug":"honey-oat-emulsified-scrub","title":"Honey Oat Emulsified Scrub","cat":"emulsified-scrub","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"3 months at room temperature, needs a preservative. This recipe contains water, so it needs a broad-spectrum preservative (see ingredients). Without the correct preservative at the correct dose, it can grow mold or bacteria within days — never skip it.","ingredients":[{"item":"Emulsifying wax NF","amount":"15 g (0.5 oz)"},{"item":"Sweet almond oil","amount":"55 g (1.9 oz)"},{"item":"Distilled water","amount":"40 g (1.4 oz)"},{"item":"White granulated sugar","amount":"70 g (2.5 oz)"},{"item":"Finely ground colloidal oatmeal","amount":"20 g (0.7 oz)"},{"item":"Broad-spectrum preservative (per its own label)","amount":"per label — typically 0.5-1 g"},{"item":"Honey fragrance oil (skin-safe cosmetic fragrance, not raw honey)","amount":"2 g (about 1/3 tsp)"}],"method":["Set up a double boiler and melt the emulsifying wax and almond oil together until clear (about 5 min).","Warm the distilled water separately to about 160-170°F (70-77°C).","Pour the warm water into the oil mixture in a thin stream, stirring constantly, until creamy.","Cool the base to under 110°F (43°C).","Stir in the preservative at the label's stated rate, then the honey fragrance oil.","Fold in the sugar and ground oatmeal once the base is thick enough to hold them.","Spoon into a jar and label with the date made."],"tips":["Grind the oatmeal fine (a coffee grinder works well) — whole oats feel scratchy instead of gently exfoliating.","This is a softer, gentler scrub than straight sugar — a good one to reach for on sensitive or dry skin."],"safety_note":"This scrub contains water and must be preserved correctly, used within its stated shelf life, and kept out of reach of children. Discontinue use if it changes smell, color or texture.","keywords":["oatmeal scrub","honey scrub","gentle scrub","sensitive skin","emulsified scrub","sugar scrub"],"pdf":"../../emulsified-body-scrub-recipes/ak8qdjexea/emulsified-body-scrub-recipes.pdf"},{"slug":"lavender-chamomile-emulsified-scrub","title":"Lavender Chamomile Emulsified Scrub","cat":"emulsified-scrub","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"3 months at room temperature, needs a preservative. This recipe contains water, so it needs a broad-spectrum preservative (see ingredients). Without the correct preservative at the correct dose, it can grow mold or bacteria within days — never skip it.","ingredients":[{"item":"Emulsifying wax NF","amount":"15 g (0.5 oz)"},{"item":"Sunflower oil","amount":"60 g (2.1 oz)"},{"item":"Distilled water","amount":"40 g (1.4 oz)"},{"item":"White granulated sugar","amount":"100 g (3.5 oz)"},{"item":"Broad-spectrum preservative (per its own label)","amount":"per label — typically 0.5-1 g"},{"item":"Lavender essential oil","amount":"15 drops"},{"item":"Roman chamomile essential oil","amount":"8 drops"}],"method":["Set up a double boiler and melt the emulsifying wax and sunflower oil together until clear (about 5 min).","Warm the distilled water separately to about 160-170°F (70-77°C).","Pour the warm water into the oil mixture in a thin stream, stirring constantly, until creamy.","Cool the base to under 110°F (43°C).","Stir in the preservative at the label's stated rate, then the lavender and chamomile essential oils.","Fold in the sugar once the base is thick enough to hold it.","Spoon into a jar and label with the date made."],"tips":["This calming blend is a good bedtime or after-bath scrub — the scent is meant to be soft, not sharp.","If you want a stronger floral note, add lavender in 5-drop increments and test before going higher."],"safety_note":"This scrub contains water and must be preserved correctly, used within its stated shelf life, and kept out of reach of children. Chamomile is related to ragweed — if you have a ragweed allergy, patch test before using this blend. Discontinue if it changes smell, color or texture.","keywords":["lavender scrub","chamomile scrub","calming scrub","sugar scrub","emulsified scrub","relaxing"],"pdf":"../../emulsified-body-scrub-recipes/ak8qdjexea/emulsified-body-scrub-recipes.pdf"},{"slug":"activated-charcoal-tea-tree-emulsified-scrub","title":"Activated Charcoal Tea Tree Emulsified Scrub","cat":"emulsified-scrub","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"3 months at room temperature, needs a preservative. This recipe contains water, so it needs a broad-spectrum preservative (see ingredients). Without the correct preservative at the correct dose, it can grow mold or bacteria within days — never skip it.","ingredients":[{"item":"Emulsifying wax NF","amount":"15 g (0.5 oz)"},{"item":"Grapeseed oil","amount":"60 g (2.1 oz)"},{"item":"Distilled water","amount":"40 g (1.4 oz)"},{"item":"White granulated sugar","amount":"95 g (3.4 oz)"},{"item":"Activated charcoal powder (cosmetic grade)","amount":"5 g (about 1 tsp) — a little goes a long way"},{"item":"Broad-spectrum preservative (per its own label)","amount":"per label — typically 0.5-1 g"},{"item":"Tea tree essential oil","amount":"12 drops"}],"method":["Set up a double boiler and melt the emulsifying wax and grapeseed oil together until clear (about 5 min).","Warm the distilled water separately to about 160-170°F (70-77°C).","Pour the warm water into the oil mixture in a thin stream, stirring constantly, until creamy.","Cool the base to under 110°F (43°C).","Stir in the preservative at the label's stated rate, then the tea tree essential oil.","Whisk in the activated charcoal until the color is even and there are no dark streaks.","Fold in the sugar once the base is thick enough to hold it.","Spoon into a jar and label with the date made."],"tips":["Use a dark towel the first few times — activated charcoal can temporarily tint light-colored towels and tub surfaces.","Keep the charcoal amount small: more doesn't clean better, it just makes rinsing messier."],"safety_note":"This scrub contains water and must be preserved correctly, used within its stated shelf life, and kept out of reach of children. Tea tree oil can irritate sensitive skin — patch test before full use. Discontinue if it changes smell, color or texture.","keywords":["charcoal scrub","tea tree scrub","detox scrub","clarifying scrub","emulsified scrub","sugar scrub"],"pdf":"../../emulsified-body-scrub-recipes/ak8qdjexea/emulsified-body-scrub-recipes.pdf"},{"slug":"pink-salt-sugar-grapefruit-emulsified-scrub","title":"Pink Salt & Sugar Grapefruit Emulsified Scrub","cat":"emulsified-scrub","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"3 months at room temperature, needs a preservative. This recipe contains water, so it needs a broad-spectrum preservative (see ingredients). Without the correct preservative at the correct dose, it can grow mold or bacteria within days — never skip it.","ingredients":[{"item":"Emulsifying wax NF","amount":"15 g (0.5 oz)"},{"item":"Sweet almond oil","amount":"60 g (2.1 oz)"},{"item":"Distilled water","amount":"40 g (1.4 oz)"},{"item":"White granulated sugar","amount":"50 g (1.8 oz)"},{"item":"Fine pink Himalayan salt","amount":"50 g (1.8 oz)"},{"item":"Broad-spectrum preservative (per its own label)","amount":"per label — typically 0.5-1 g"},{"item":"Grapefruit essential oil (cold-pressed)","amount":"15 drops"}],"method":["Set up a double boiler and melt the emulsifying wax and almond oil together until clear (about 5 min).","Warm the distilled water separately to about 160-170°F (70-77°C).","Pour the warm water into the oil mixture in a thin stream, stirring constantly, until creamy.","Cool the base to under 110°F (43°C).","Stir in the preservative at the label's stated rate, then the grapefruit essential oil.","Fold in the sugar and pink salt together once the base is thick enough to hold them.","Spoon into a jar and label with the date made."],"tips":["Combining sugar and fine salt gives two slightly different textures in one scrub — sugar dissolves softer, salt stays a bit grittier.","Because this recipe contains water, the salt will soften faster than it would in an anhydrous scrub — use it within the stated shelf life for the best texture."],"safety_note":"This scrub contains water and must be preserved correctly, used within its stated shelf life, and kept out of reach of children. Cold-pressed grapefruit oil can increase sun sensitivity — avoid direct sun on treated skin for about 12 hours after use. Discontinue if it changes smell, color or texture.","keywords":["pink salt scrub","grapefruit scrub","sugar salt scrub","citrus scrub","emulsified scrub","body scrub"],"pdf":"../../emulsified-body-scrub-recipes/ak8qdjexea/emulsified-body-scrub-recipes.pdf"},{"slug":"peppermint-mocha-holiday-emulsified-scrub","title":"Peppermint Mocha Holiday Emulsified Scrub","cat":"emulsified-scrub","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"3 months at room temperature, needs a preservative. This recipe contains water, so it needs a broad-spectrum preservative (see ingredients). Without the correct preservative at the correct dose, it can grow mold or bacteria within days — never skip it.","ingredients":[{"item":"Emulsifying wax NF","amount":"15 g (0.5 oz)"},{"item":"Sweet almond oil","amount":"60 g (2.1 oz)"},{"item":"Distilled water","amount":"40 g (1.4 oz)"},{"item":"Light brown sugar","amount":"90 g (3.2 oz)"},{"item":"Unsweetened cocoa powder","amount":"10 g (0.35 oz)"},{"item":"Broad-spectrum preservative (per its own label)","amount":"per label — typically 0.5-1 g"},{"item":"Peppermint essential oil","amount":"10 drops"},{"item":"Vanilla fragrance oil","amount":"1 g (about 1/4 tsp)"}],"method":["Set up a double boiler and melt the emulsifying wax and almond oil together until clear (about 5 min).","Warm the distilled water separately to about 160-170°F (70-77°C).","Pour the warm water into the oil mixture in a thin stream, stirring constantly, until creamy.","Cool the base to under 110°F (43°C).","Stir in the preservative at the label's stated rate, then the peppermint and vanilla fragrance oils.","Whisk in the cocoa powder until the color is even.","Fold in the brown sugar once the base is thick enough to hold it.","Spoon into a jar — a clear glass jar shows off the mocha color nicely for gifting — and label with the date made."],"tips":["Cocoa powder can settle a little at the bottom of the jar over time — give it a stir before each use.","This one is a popular holiday gift scrub; pair it with a simple ribbon and a handwritten batch date."],"safety_note":"This scrub contains water and must be preserved correctly, used within its stated shelf life, and kept out of reach of children. Discontinue use if it changes smell, color or texture.","keywords":["mocha scrub","peppermint scrub","holiday scrub","gift scrub","chocolate scrub","emulsified scrub"],"pdf":"../../emulsified-body-scrub-recipes/ak8qdjexea/emulsified-body-scrub-recipes.pdf"},{"slug":"cucumber-melon-emulsified-scrub","title":"Cucumber Melon Emulsified Scrub","cat":"emulsified-scrub","time":"15 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"3 months at room temperature, needs a preservative. This recipe contains water, so it needs a broad-spectrum preservative (see ingredients). Without the correct preservative at the correct dose, it can grow mold or bacteria within days — never skip it.","ingredients":[{"item":"Emulsifying wax NF","amount":"15 g (0.5 oz)"},{"item":"Grapeseed oil","amount":"60 g (2.1 oz)"},{"item":"Distilled water","amount":"40 g (1.4 oz)"},{"item":"White granulated sugar","amount":"100 g (3.5 oz)"},{"item":"Broad-spectrum preservative (per its own label)","amount":"per label — typically 0.5-1 g"},{"item":"Cucumber melon fragrance oil (skin-safe cosmetic fragrance)","amount":"3 g (about 1/2 tsp)"}],"method":["Set up a double boiler and melt the emulsifying wax and grapeseed oil together until clear (about 5 min).","Warm the distilled water separately to about 160-170°F (70-77°C).","Pour the warm water into the oil mixture in a thin stream, stirring constantly, until creamy.","Cool the base to under 110°F (43°C).","Stir in the preservative at the label's stated rate, then the cucumber melon fragrance oil.","Fold in the sugar once the base is thick enough to hold it.","Spoon into a jar and label with the date made."],"tips":["This light, fresh scent works well as a summer batch — pair it with a pale green or blue jar label.","If the scrub ever smells sour or off before its shelf-life date, stop using it and remake a fresh batch."],"safety_note":"This scrub contains water and must be preserved correctly, used within its stated shelf life, and kept out of reach of children. Discontinue use if it changes smell, color or texture.","keywords":["cucumber melon scrub","summer scrub","fresh scrub","sugar scrub","emulsified scrub","spa scrub"],"pdf":"../../emulsified-body-scrub-recipes/ak8qdjexea/emulsified-body-scrub-recipes.pdf"},{"slug":"coconut-vanilla-fine-salt-scrub","title":"Coconut Vanilla Fine Salt Scrub","cat":"salt-scrub","time":"10 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"6 months at room temperature. No water is added to this scrub — it only foams when it meets water in the shower — so it doesn't need a preservative. Keep the lid on tight between uses.","ingredients":[{"item":"Fine sea salt","amount":"150 g (5.3 oz)"},{"item":"Fractionated coconut oil","amount":"40 g (1.4 oz)"},{"item":"Polysorbate 80 (an emulsifier that lets the oil rinse off instead of clogging the shower)","amount":"15 g (0.5 oz)"},{"item":"Coconut fragrance oil","amount":"2 g (about 1/3 tsp)"},{"item":"Vanilla fragrance oil","amount":"1 g (about 1/4 tsp)"}],"method":["In a bowl, stir the fractionated coconut oil and polysorbate 80 together until fully blended.","Add the coconut and vanilla fragrance oils and stir again.","Pour the mixture over the fine sea salt and fold together until every grain is coated.","Spoon into a wide-mouth jar, pressing down gently to remove large air pockets."],"tips":["Fine salt dissolves a little faster under running water than coarse salt — good for a quicker, lighter exfoliation.","The polysorbate 80 is what makes this scrub foam instead of just sitting oily on the skin."],"safety_note":null,"keywords":["coconut salt scrub","vanilla scrub","fine salt scrub","foaming scrub","body scrub","exfoliating"],"pdf":"../../salt-based-emulsified-recipes/060n4zqnvd/salt-based-emulsified-recipes.pdf"},{"slug":"eucalyptus-spa-coarse-salt-scrub","title":"Eucalyptus Spa Coarse Salt Scrub","cat":"salt-scrub","time":"10 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"6 months at room temperature. No water is added to this scrub, so it doesn't need a preservative. Keep the lid on tight between uses.","ingredients":[{"item":"Coarse sea salt","amount":"150 g (5.3 oz)"},{"item":"Sweet almond oil","amount":"40 g (1.4 oz)"},{"item":"Polysorbate 80","amount":"15 g (0.5 oz)"},{"item":"Eucalyptus essential oil","amount":"20 drops"}],"method":["In a bowl, stir the sweet almond oil and polysorbate 80 together until fully blended.","Add the eucalyptus essential oil and stir again.","Pour the mixture over the coarse sea salt and fold together until every grain is coated.","Spoon into a wide-mouth jar, pressing down gently to remove large air pockets."],"tips":["Coarse salt is a strong, spa-style exfoliant — best for feet, elbows and knees rather than thinner, more sensitive skin.","Massage in slow circles; coarse crystals need less pressure than you'd think to do their job."],"safety_note":"Coarse salt is more abrasive than fine salt — avoid using it on the face or on freshly shaved or broken skin, and use a lighter hand on thinner areas.","keywords":["eucalyptus scrub","coarse salt scrub","spa scrub","foot scrub","body scrub","foaming scrub"],"pdf":"../../salt-based-emulsified-recipes/060n4zqnvd/salt-based-emulsified-recipes.pdf"},{"slug":"pink-himalayan-rose-fine-salt-scrub","title":"Pink Himalayan Rose Fine Salt Scrub","cat":"salt-scrub","time":"10 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"6 months at room temperature. No water is added to this scrub, so it doesn't need a preservative. Keep the lid on tight between uses.","ingredients":[{"item":"Fine pink Himalayan salt","amount":"150 g (5.3 oz)"},{"item":"Jojoba oil","amount":"40 g (1.4 oz)"},{"item":"Polysorbate 80","amount":"15 g (0.5 oz)"},{"item":"Rose fragrance oil","amount":"3 g (about 1/2 tsp)"}],"method":["In a bowl, stir the jojoba oil and polysorbate 80 together until fully blended.","Add the rose fragrance oil and stir again.","Pour the mixture over the pink Himalayan salt and fold together until every grain is coated.","Spoon into a wide-mouth jar, pressing down gently to remove large air pockets."],"tips":["Fine pink Himalayan salt gives a softer scrub than coarse sea salt, with a pretty blush color that's nice for gifting.","Jojoba oil closely resembles skin's natural oils, so this scrub leaves less of a greasy film than heavier oils."],"safety_note":null,"keywords":["pink salt scrub","himalayan salt scrub","rose scrub","gift scrub","body scrub","foaming scrub"],"pdf":"../../salt-based-emulsified-recipes/060n4zqnvd/salt-based-emulsified-recipes.pdf"},{"slug":"citrus-grove-coarse-salt-scrub","title":"Citrus Grove Coarse Salt Scrub","cat":"salt-scrub","time":"10 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"6 months at room temperature. No water is added to this scrub, so it doesn't need a preservative. Keep the lid on tight between uses.","ingredients":[{"item":"Coarse sea salt","amount":"150 g (5.3 oz)"},{"item":"Grapeseed oil","amount":"40 g (1.4 oz)"},{"item":"Polysorbate 80","amount":"15 g (0.5 oz)"},{"item":"Sweet orange essential oil","amount":"20 drops"},{"item":"Cold-pressed lemon essential oil","amount":"10 drops"}],"method":["In a bowl, stir the grapeseed oil and polysorbate 80 together until fully blended.","Add the orange and lemon essential oils and stir again.","Pour the mixture over the coarse sea salt and fold together until every grain is coated.","Spoon into a wide-mouth jar, pressing down gently to remove large air pockets."],"tips":["Rinse this scrub off fully rather than leaving residual oil on the skin, since the citrus oils in it are meant to be a rinse-off exposure, not a leave-on one.","Swap the lemon for steam-distilled lime or lemon if you plan to be in direct sun right after showering."],"safety_note":"Cold-pressed citrus oils can increase skin's sensitivity to sunburn. Rinse well, and avoid direct sun on treated skin for about 12 hours after use.","keywords":["citrus salt scrub","orange scrub","lemon scrub","coarse salt scrub","body scrub","foaming scrub"],"pdf":"../../salt-based-emulsified-recipes/060n4zqnvd/salt-based-emulsified-recipes.pdf"},{"slug":"chocolate-mint-fine-salt-scrub","title":"Chocolate Mint Fine Salt Scrub","cat":"salt-scrub","time":"10 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"6 months at room temperature. No water is added to this scrub, so it doesn't need a preservative. Keep the lid on tight between uses.","ingredients":[{"item":"Fine sea salt","amount":"140 g (4.9 oz)"},{"item":"Coconut oil, melted","amount":"40 g (1.4 oz)"},{"item":"Polysorbate 80","amount":"15 g (0.5 oz)"},{"item":"Unsweetened cocoa powder","amount":"10 g (0.35 oz)"},{"item":"Peppermint essential oil","amount":"15 drops"}],"method":["Melt the coconut oil gently if it's solid, then stir in the polysorbate 80 until fully blended.","Whisk in the cocoa powder until the color is even and there are no dry clumps.","Add the peppermint essential oil and stir again.","Pour the mixture over the fine sea salt and fold together until every grain is coated.","Spoon into a wide-mouth jar, pressing down gently to remove large air pockets."],"tips":["Cocoa powder can tint a light-colored tub — rinse the tub after use, the same as you would for a bath bomb.","If the coconut oil solidifies before you mix in the salt, warm the bowl briefly over hot water to loosen it back up."],"safety_note":null,"keywords":["chocolate mint scrub","cocoa scrub","peppermint scrub","salt scrub","body scrub","foaming scrub"],"pdf":"../../salt-based-emulsified-recipes/060n4zqnvd/salt-based-emulsified-recipes.pdf"},{"slug":"himalayan-pink-salt-lavender-coarse-scrub","title":"Himalayan Pink Salt Lavender Coarse Scrub","cat":"salt-scrub","time":"10 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"6 months at room temperature. No water is added to this scrub, so it doesn't need a preservative. Keep the lid on tight between uses.","ingredients":[{"item":"Coarse pink Himalayan salt","amount":"150 g (5.3 oz)"},{"item":"Sweet almond oil","amount":"40 g (1.4 oz)"},{"item":"Polysorbate 80","amount":"15 g (0.5 oz)"},{"item":"Lavender essential oil","amount":"20 drops"}],"method":["In a bowl, stir the sweet almond oil and polysorbate 80 together until fully blended.","Add the lavender essential oil and stir again.","Pour the mixture over the coarse pink Himalayan salt and fold together until every grain is coated.","Spoon into a wide-mouth jar, pressing down gently to remove large air pockets."],"tips":["The coarse crystals here are bigger than table salt — use on feet, elbows and knees, not on the face.","This blend works well as an evening, wind-down scrub right before a shower."],"safety_note":null,"keywords":["himalayan salt scrub","lavender scrub","coarse salt scrub","pink salt","body scrub","foaming scrub"],"pdf":"../../salt-based-emulsified-recipes/060n4zqnvd/salt-based-emulsified-recipes.pdf"},{"slug":"detox-charcoal-sea-salt-scrub","title":"Detox Charcoal Sea Salt Scrub","cat":"salt-scrub","time":"10 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"6 months at room temperature. No water is added to this scrub, so it doesn't need a preservative. Keep the lid on tight between uses.","ingredients":[{"item":"Coarse sea salt","amount":"145 g (5.1 oz)"},{"item":"Olive oil","amount":"40 g (1.4 oz)"},{"item":"Polysorbate 80","amount":"15 g (0.5 oz)"},{"item":"Activated charcoal powder (cosmetic grade)","amount":"5 g (about 1 tsp)"},{"item":"Tea tree essential oil","amount":"15 drops"}],"method":["In a bowl, stir the olive oil and polysorbate 80 together until fully blended.","Whisk in the activated charcoal until the color is even with no dark streaks.","Add the tea tree essential oil and stir again.","Pour the mixture over the coarse sea salt and fold together until every grain is coated.","Spoon into a wide-mouth jar, pressing down gently to remove large air pockets."],"tips":["Use a dark towel the first few times — charcoal can temporarily tint light fabric and tub surfaces.","This is a good back-and-shoulders scrub for oily or congested skin, not an everyday full-body one."],"safety_note":"Tea tree oil can irritate sensitive skin — patch test on your inner arm before using it over a large area for the first time.","keywords":["charcoal salt scrub","detox scrub","tea tree scrub","coarse salt scrub","body scrub","clarifying"],"pdf":"../../salt-based-emulsified-recipes/060n4zqnvd/salt-based-emulsified-recipes.pdf"},{"slug":"tropical-pineapple-coconut-salt-scrub","title":"Tropical Pineapple Coconut Salt Scrub","cat":"salt-scrub","time":"10 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"6 months at room temperature. No water is added to this scrub, so it doesn't need a preservative. Keep the lid on tight between uses.","ingredients":[{"item":"Fine sea salt","amount":"150 g (5.3 oz)"},{"item":"Fractionated coconut oil","amount":"40 g (1.4 oz)"},{"item":"Polysorbate 80","amount":"15 g (0.5 oz)"},{"item":"Pineapple coconut fragrance oil (skin-safe cosmetic fragrance)","amount":"3 g (about 1/2 tsp)"}],"method":["In a bowl, stir the fractionated coconut oil and polysorbate 80 together until fully blended.","Add the pineapple coconut fragrance oil and stir again.","Pour the mixture over the fine sea salt and fold together until every grain is coated.","Spoon into a wide-mouth jar, pressing down gently to remove large air pockets."],"tips":["This is a fun summer or vacation-themed batch — pack it in a small travel jar for the beach bag.","If the scent is too strong straight out of the bottle, cut the fragrance oil to 2 g and test again."],"safety_note":null,"keywords":["pineapple scrub","coconut salt scrub","tropical scrub","summer scrub","body scrub","foaming scrub"],"pdf":"../../salt-based-emulsified-recipes/060n4zqnvd/salt-based-emulsified-recipes.pdf"},{"slug":"unscented-sensitive-skin-salt-scrub","title":"Unscented Sensitive Skin Salt Scrub","cat":"salt-scrub","time":"10 min active, no cook time","batch_size":"about 8 oz (225 g)","shelf_life":"6 months at room temperature. No water is added to this scrub, so it doesn't need a preservative. Keep the lid on tight between uses.","ingredients":[{"item":"Fine sea salt","amount":"150 g (5.3 oz)"},{"item":"Sunflower oil","amount":"40 g (1.4 oz)"},{"item":"Polysorbate 80","amount":"15 g (0.5 oz)"}],"method":["In a bowl, stir the sunflower oil and polysorbate 80 together until fully blended.","Pour the mixture over the fine sea salt and fold together until every grain is coated.","Spoon into a wide-mouth jar, pressing down gently to remove large air pockets."],"tips":["Fragrance-free is a good choice for reactive or very sensitive skin, or for anyone who prefers unscented products.","If you'd like a light scent later, stir in 10-15 drops of a gentle essential oil per batch and test on a small area first."],"safety_note":null,"keywords":["unscented scrub","sensitive skin scrub","fragrance free","fine salt scrub","body scrub","gentle scrub"],"pdf":"../../salt-based-emulsified-recipes/060n4zqnvd/salt-based-emulsified-recipes.pdf"},{"slug":"citrus-sage-deodorant","title":"Citrus Sage Deodorant","cat":"deodorant","time":"10 min active, no cook time","batch_size":"about 2.5 oz (70 g), one standard deodorant tube","shelf_life":"Up to 6 months at room temperature. No water in this recipe, so no preservative is needed.","ingredients":[{"item":"Coconut oil","amount":"25 g (0.9 oz)"},{"item":"Shea butter","amount":"10 g (0.35 oz)"},{"item":"Beeswax pellets","amount":"8 g (0.3 oz)"},{"item":"Arrowroot powder (or cornstarch)","amount":"15 g (0.5 oz)"},{"item":"Baking soda","amount":"10 g (0.35 oz) — see the note below if your skin is sensitive"},{"item":"Sweet orange essential oil","amount":"10 drops"},{"item":"Clary sage essential oil","amount":"5 drops"}],"method":["Melt the coconut oil, shea butter and beeswax together in a double boiler until fully liquid.","Remove from heat and whisk in the arrowroot powder and baking soda until no lumps remain.","Let the mixture cool for 2-3 min, stirring once or twice so the powders don't settle to the bottom.","Stir in the orange and clary sage essential oils.","Pour into an empty deodorant tube or a small jar before it sets — it firms up fast.","Let it cool fully at room temperature (1-2 hours) before using."],"tips":["This bright, herbal-citrus blend layers well under a fragrance-free routine without clashing with perfume.","In hot weather, add an extra 2-3 g of beeswax so it stays solid."],"safety_note":"Baking soda is alkaline and irritates some people's underarm skin (redness, itching, a rash). Patch test on your arm for a few days first. If you react, cut the baking soda to 5 g, or replace it entirely with the same amount of magnesium hydroxide powder, which most people tolerate better.","keywords":["citrus deodorant","sage deodorant","natural deodorant","baking soda","diy deodorant","fresh scent"],"pdf":"../../deodorant-recipes/4jp9eupm6n/deodorant-recipes.pdf"},{"slug":"tea-tree-eucalyptus-vegan-deodorant","title":"Tea Tree Eucalyptus Vegan Deodorant","cat":"deodorant","time":"10 min active, no cook time","batch_size":"about 2.5 oz (70 g), one standard deodorant tube","shelf_life":"Up to 6 months at room temperature. No water in this recipe, so no preservative is needed.","ingredients":[{"item":"Coconut oil","amount":"25 g (0.9 oz)"},{"item":"Cocoa butter","amount":"10 g (0.35 oz)"},{"item":"Candelilla wax (vegan substitute for beeswax)","amount":"6 g (0.2 oz)"},{"item":"Arrowroot powder","amount":"15 g (0.5 oz)"},{"item":"Baking soda","amount":"9 g (0.3 oz) — see the note below if your skin is sensitive"},{"item":"Tea tree essential oil","amount":"10 drops"},{"item":"Eucalyptus essential oil","amount":"8 drops"}],"method":["Melt the coconut oil, cocoa butter and candelilla wax together in a double boiler until fully liquid.","Remove from heat and whisk in the arrowroot powder and baking soda until no lumps remain.","Let the mixture cool for 2-3 min, stirring once or twice so the powders don't settle to the bottom.","Stir in the tea tree and eucalyptus essential oils.","Pour into an empty deodorant tube or a small jar before it sets — it firms up fast.","Let it cool fully at room temperature (1-2 hours) before using."],"tips":["Candelilla wax is firmer than beeswax at the same weight — if the bar feels too soft in a hot room, add 1-2 g more next batch.","This fresh, clean scent is a good choice for an active, high-sweat day."],"safety_note":"Baking soda is alkaline and irritates some people's underarm skin (redness, itching, a rash). Patch test on your arm for a few days first. If you react, cut the baking soda to 5 g, or replace it entirely with the same amount of magnesium hydroxide powder, which most people tolerate better. Tea tree oil can also irritate on its own — patch test the blend.","keywords":["vegan deodorant","tea tree deodorant","eucalyptus deodorant","natural deodorant","candelilla wax","diy deodorant"],"pdf":"../../deodorant-recipes/4jp9eupm6n/deodorant-recipes.pdf"},{"slug":"vanilla-cedarwood-deodorant","title":"Vanilla Cedarwood Deodorant","cat":"deodorant","time":"10 min active, no cook time","batch_size":"about 2.5 oz (70 g), one standard deodorant tube","shelf_life":"Up to 6 months at room temperature. No water in this recipe, so no preservative is needed.","ingredients":[{"item":"Coconut oil","amount":"25 g (0.9 oz)"},{"item":"Mango butter","amount":"10 g (0.35 oz)"},{"item":"Beeswax pellets","amount":"8 g (0.3 oz)"},{"item":"Arrowroot powder","amount":"15 g (0.5 oz)"},{"item":"Baking soda","amount":"10 g (0.35 oz) — see the note below if your skin is sensitive"},{"item":"Cedarwood essential oil","amount":"10 drops"},{"item":"Vanilla fragrance oil","amount":"0.5 g (about 10 drops)"}],"method":["Melt the coconut oil, mango butter and beeswax together in a double boiler until fully liquid.","Remove from heat and whisk in the arrowroot powder and baking soda until no lumps remain.","Let the mixture cool for 2-3 min, stirring once or twice so the powders don't settle to the bottom.","Stir in the cedarwood essential oil and vanilla fragrance oil.","Pour into an empty deodorant tube or a small jar before it sets — it firms up fast.","Let it cool fully at room temperature (1-2 hours) before using."],"tips":["Mango butter is a bit softer than shea at room temperature — this bar glides on easily, even straight from a cool bathroom.","This warm, woody-sweet scent works well as a unisex option."],"safety_note":"Baking soda is alkaline and irritates some people's underarm skin (redness, itching, a rash). Patch test on your arm for a few days first. If you react, cut the baking soda to 5 g, or replace it entirely with the same amount of magnesium hydroxide powder, which most people tolerate better.","keywords":["vanilla deodorant","cedarwood deodorant","unisex deodorant","natural deodorant","baking soda","diy deodorant"],"pdf":"../../deodorant-recipes/4jp9eupm6n/deodorant-recipes.pdf"},{"slug":"rosemary-mint-deodorant","title":"Rosemary Mint Deodorant","cat":"deodorant","time":"10 min active, no cook time","batch_size":"about 2.5 oz (70 g), one standard deodorant tube","shelf_life":"Up to 6 months at room temperature. No water in this recipe, so no preservative is needed.","ingredients":[{"item":"Coconut oil","amount":"25 g (0.9 oz)"},{"item":"Shea butter","amount":"10 g (0.35 oz)"},{"item":"Beeswax pellets","amount":"8 g (0.3 oz)"},{"item":"Cornstarch","amount":"15 g (0.5 oz)"},{"item":"Baking soda","amount":"10 g (0.35 oz) — see the note below if your skin is sensitive"},{"item":"Rosemary essential oil","amount":"10 drops"},{"item":"Peppermint essential oil","amount":"8 drops"}],"method":["Melt the coconut oil, shea butter and beeswax together in a double boiler until fully liquid.","Remove from heat and whisk in the cornstarch and baking soda until no lumps remain.","Let the mixture cool for 2-3 min, stirring once or twice so the powders don't settle to the bottom.","Stir in the rosemary and peppermint essential oils.","Pour into an empty deodorant tube or a small jar before it sets — it firms up fast.","Let it cool fully at room temperature (1-2 hours) before using."],"tips":["Cornstarch works as well as arrowroot here and is usually already in the pantry.","The peppermint gives a noticeable cooling tingle when applied — that's normal and fades within a minute or two."],"safety_note":"Baking soda is alkaline and irritates some people's underarm skin (redness, itching, a rash). Patch test on your arm for a few days first. If you react, cut the baking soda to 5 g, or replace it entirely with the same amount of magnesium hydroxide powder, which most people tolerate better.","keywords":["rosemary deodorant","peppermint deodorant","mint deodorant","natural deodorant","baking soda","diy deodorant"],"pdf":"../../deodorant-recipes/4jp9eupm6n/deodorant-recipes.pdf"},{"slug":"sandalwood-patchouli-vegan-deodorant","title":"Sandalwood Patchouli Vegan Deodorant","cat":"deodorant","time":"10 min active, no cook time","batch_size":"about 2.5 oz (70 g), one standard deodorant tube","shelf_life":"Up to 6 months at room temperature. No water in this recipe, so no preservative is needed.","ingredients":[{"item":"Coconut oil","amount":"25 g (0.9 oz)"},{"item":"Cocoa butter","amount":"10 g (0.35 oz)"},{"item":"Candelilla wax (vegan substitute for beeswax)","amount":"6 g (0.2 oz)"},{"item":"Arrowroot powder","amount":"15 g (0.5 oz)"},{"item":"Baking soda","amount":"9 g (0.3 oz) — see the note below if your skin is sensitive"},{"item":"Sandalwood essential oil","amount":"8 drops"},{"item":"Patchouli essential oil","amount":"5 drops"}],"method":["Melt the coconut oil, cocoa butter and candelilla wax together in a double boiler until fully liquid.","Remove from heat and whisk in the arrowroot powder and baking soda until no lumps remain.","Let the mixture cool for 2-3 min, stirring once or twice so the powders don't settle to the bottom.","Stir in the sandalwood and patchouli essential oils.","Pour into an empty deodorant tube or a small jar before it sets — it firms up fast.","Let it cool fully at room temperature (1-2 hours) before using."],"tips":["Patchouli is strong — start with the stated amount and only add more next batch if you want a deeper scent.","This is a good gift option for anyone who prefers plant-based waxes over beeswax."],"safety_note":"Baking soda is alkaline and irritates some people's underarm skin (redness, itching, a rash). Patch test on your arm for a few days first. If you react, cut the baking soda to 5 g, or replace it entirely with the same amount of magnesium hydroxide powder, which most people tolerate better.","keywords":["sandalwood deodorant","patchouli deodorant","vegan deodorant","natural deodorant","baking soda","diy deodorant"],"pdf":"../../deodorant-recipes/4jp9eupm6n/deodorant-recipes.pdf"},{"slug":"grapefruit-ginger-energizing-deodorant","title":"Grapefruit Ginger Energizing Deodorant","cat":"deodorant","time":"10 min active, no cook time","batch_size":"about 2.5 oz (70 g), one standard deodorant tube","shelf_life":"Up to 6 months at room temperature. No water in this recipe, so no preservative is needed.","ingredients":[{"item":"Coconut oil","amount":"25 g (0.9 oz)"},{"item":"Shea butter","amount":"10 g (0.35 oz)"},{"item":"Beeswax pellets","amount":"8 g (0.3 oz)"},{"item":"Arrowroot powder","amount":"15 g (0.5 oz)"},{"item":"Baking soda","amount":"10 g (0.35 oz) — see the note below if your skin is sensitive"},{"item":"Steam-distilled grapefruit essential oil (not cold-pressed, which is phototoxic)","amount":"10 drops"},{"item":"Ginger essential oil","amount":"5 drops"}],"method":["Melt the coconut oil, shea butter and beeswax together in a double boiler until fully liquid.","Remove from heat and whisk in the arrowroot powder and baking soda until no lumps remain.","Let the mixture cool for 2-3 min, stirring once or twice so the powders don't settle to the bottom.","Stir in the grapefruit and ginger essential oils.","Pour into an empty deodorant tube or a small jar before it sets — it firms up fast.","Let it cool fully at room temperature (1-2 hours) before using."],"tips":["Use steam-distilled grapefruit, not cold-pressed — since this product stays on the skin, a phototoxic oil here is a bigger concern than in a rinse-off scrub.","This bright, spicy-citrus combo is a nice morning scent to pair with a workout routine."],"safety_note":"Baking soda is alkaline and irritates some people's underarm skin (redness, itching, a rash). Patch test on your arm for a few days first. If you react, cut the baking soda to 5 g, or replace it entirely with the same amount of magnesium hydroxide powder, which most people tolerate better.","keywords":["grapefruit deodorant","ginger deodorant","citrus deodorant","natural deodorant","baking soda","diy deodorant"],"pdf":"../../deodorant-recipes/4jp9eupm6n/deodorant-recipes.pdf"},{"slug":"gentle-chamomile-oat-sensitive-skin-deodorant","title":"Gentle Chamomile Oat Sensitive-Skin Deodorant","cat":"deodorant","time":"10 min active, no cook time","batch_size":"about 2.6 oz (75 g), one standard deodorant tube","shelf_life":"Up to 6 months at room temperature. No water in this recipe, so no preservative is needed.","ingredients":[{"item":"Coconut oil","amount":"25 g (0.9 oz)"},{"item":"Shea butter","amount":"10 g (0.35 oz)"},{"item":"Beeswax pellets","amount":"8 g (0.3 oz)"},{"item":"Arrowroot powder","amount":"20 g (0.7 oz)"},{"item":"Finely ground colloidal oatmeal","amount":"5 g (about 1 tsp)"},{"item":"Baking soda","amount":"6 g (0.2 oz) — already a lower, gentler amount than a standard recipe"},{"item":"Roman chamomile essential oil","amount":"8 drops"}],"method":["Melt the coconut oil, shea butter and beeswax together in a double boiler until fully liquid.","Remove from heat and whisk in the arrowroot powder, colloidal oatmeal and baking soda until no lumps remain.","Let the mixture cool for 2-3 min, stirring once or twice so the powders don't settle to the bottom.","Stir in the chamomile essential oil.","Pour into an empty deodorant tube or a small jar before it sets — it firms up fast.","Let it cool fully at room temperature (1-2 hours) before using."],"tips":["This recipe already uses less baking soda and more soothing powder than a standard batch — it's the one to reach for first if underarm skin tends to react.","Grind the oatmeal fine; whole oats feel gritty rather than soothing in a deodorant."],"safety_note":"Even at this lower amount, baking soda can still irritate very reactive skin (redness, itching, a rash). Patch test on your arm for a few days first. If you still react, replace the baking soda entirely with the same amount of magnesium hydroxide powder, which most people tolerate better. Chamomile is related to ragweed — skip it if you have a ragweed allergy.","keywords":["sensitive skin deodorant","chamomile deodorant","oat deodorant","gentle deodorant","low baking soda","diy deodorant"],"pdf":"../../deodorant-recipes/4jp9eupm6n/deodorant-recipes.pdf"},{"slug":"activated-charcoal-detox-deodorant","title":"Activated Charcoal Detox Deodorant","cat":"deodorant","time":"10 min active, no cook time","batch_size":"about 2.5 oz (70 g), one standard deodorant tube","shelf_life":"Up to 6 months at room temperature. No water in this recipe, so no preservative is needed.","ingredients":[{"item":"Coconut oil","amount":"25 g (0.9 oz)"},{"item":"Cocoa butter","amount":"10 g (0.35 oz)"},{"item":"Beeswax pellets","amount":"8 g (0.3 oz)"},{"item":"Arrowroot powder","amount":"15 g (0.5 oz)"},{"item":"Activated charcoal powder (cosmetic grade)","amount":"2 g (about 1/2 tsp)"},{"item":"Baking soda","amount":"10 g (0.35 oz) — see the note below if your skin is sensitive"},{"item":"Tea tree essential oil","amount":"10 drops"}],"method":["Melt the coconut oil, cocoa butter and beeswax together in a double boiler until fully liquid.","Remove from heat and whisk in the arrowroot powder, activated charcoal and baking soda until no lumps or dark streaks remain.","Let the mixture cool for 2-3 min, stirring once or twice so the powders don't settle to the bottom.","Stir in the tea tree essential oil.","Pour into an empty deodorant tube or a small jar before it sets — it firms up fast.","Let it cool fully at room temperature (1-2 hours) before using."],"tips":["The charcoal tints this deodorant a light gray — let it dry fully before dressing so it doesn't transfer to light-colored clothing.","Keep the charcoal amount small; this is a cosmetic ingredient here for feel and color, not a medical treatment."],"safety_note":"Baking soda is alkaline and irritates some people's underarm skin (redness, itching, a rash). Patch test on your arm for a few days first. If you react, cut the baking soda to 5 g, or replace it entirely with the same amount of magnesium hydroxide powder, which most people tolerate better.","keywords":["charcoal deodorant","detox deodorant","tea tree deodorant","natural deodorant","baking soda","diy deodorant"],"pdf":"../../deodorant-recipes/4jp9eupm6n/deodorant-recipes.pdf"},{"slug":"spiced-orange-holiday-deodorant","title":"Spiced Orange Holiday Deodorant","cat":"deodorant","time":"10 min active, no cook time","batch_size":"about 2.5 oz (70 g), one standard deodorant tube","shelf_life":"Up to 6 months at room temperature. No water in this recipe, so no preservative is needed.","ingredients":[{"item":"Coconut oil","amount":"25 g (0.9 oz)"},{"item":"Mango butter","amount":"10 g (0.35 oz)"},{"item":"Beeswax pellets","amount":"8 g (0.3 oz)"},{"item":"Arrowroot powder","amount":"15 g (0.5 oz)"},{"item":"Baking soda","amount":"10 g (0.35 oz) — see the note below if your skin is sensitive"},{"item":"Sweet orange essential oil","amount":"12 drops"},{"item":"Clove bud essential oil (a strong, 'hot' oil — do not exceed this amount)","amount":"3 drops"}],"method":["Melt the coconut oil, mango butter and beeswax together in a double boiler until fully liquid.","Remove from heat and whisk in the arrowroot powder and baking soda until no lumps remain.","Let the mixture cool for 2-3 min, stirring once or twice so the powders don't settle to the bottom.","Stir in the sweet orange essential oil, then the clove bud essential oil.","Pour into an empty deodorant tube or a small jar before it sets — it firms up fast.","Let it cool fully at room temperature (1-2 hours) before using."],"tips":["Clove bud oil is a warming, high-irritation-potential oil even in small amounts — never increase it past 3 drops in this batch size.","This spiced scent is a fun seasonal gift set alongside a holiday body butter or scrub."],"safety_note":"Baking soda is alkaline and irritates some people's underarm skin (redness, itching, a rash). Patch test on your arm for a few days first. If you react, cut the baking soda to 5 g, or replace it entirely with the same amount of magnesium hydroxide powder, which most people tolerate better. Clove bud oil can also irritate on its own at higher amounts — stick to the stated small dose and patch test the finished blend.","keywords":["holiday deodorant","spiced orange deodorant","clove deodorant","gift deodorant","baking soda","diy deodorant"],"pdf":"../../deodorant-recipes/4jp9eupm6n/deodorant-recipes.pdf"}]};
